package com.ascent.climb.data.i18n

/** Deutsche Quiz-Texte, Teil 3. Siehe Hinweis in PackDeQuiz2.kt. */
internal val PACK_DE_QUIZ_C: Map<String, String> = mapOf(
    "q.l37#0.p" to "Wie lautet die Reihenfolge der vier Phasen der Lawinensuche?",
    "q.l37#0.o0" to "Signal- und Hinweissuche → Grobsuche → Feinsuche → Punktsondierung",
    "q.l37#0.o1" to "Grobsuche → Feinsuche → Punktsondierung → Signalsuche",
    "q.l37#0.o2" to "Punktsondierung → Feinsuche → Grobsuche",
    "q.l37#0.o3" to "Suche → Graben → Sondieren",
    "q.l37#0.e" to "Die vier Phasen sind ein schrittweises Zusammenziehen: vom ganzen Hang über wenige Meter zur einen Punkt an der Oberfläche bis zur konkreten Tiefe. Jede übersprungene Phase kostet Zeit.",
    "q.l37#1.p" to "Welcher Abstand wird für die Suchstreifen üblicherweise gewählt?",
    "q.l37#1.o0" to "Etwa 40 Meter, zum Rand der Ablagerung etwa 20 Meter",
    "q.l37#1.o1" to "10 Meter",
    "q.l37#1.o2" to "80 Meter",
    "q.l37#1.o3" to "Je breiter, desto besser",
    "q.l37#1.e" to "40 Meter ist ein Lehrstandard, keine Gerätegrenze. Bei unsicherem Trainingsstand auf 30 Meter verengen – lieber ein paar Bahnen mehr.",
    "q.l37#2.p" to "Was muss die Gruppe vor Beginn der Suche unbedingt tun?",
    "q.l37#2.o0" to "Alle Geräte auf Empfang stellen und Störquellen wie Handys und Kameras ausschalten",
    "q.l37#2.o1" to "Zuerst eine Testgrube graben",
    "q.l37#2.o2" to "Zuerst Fotos machen",
    "q.l37#2.o3" to "Zuerst das Seil aufwickeln",
    "q.l37#2.e" to "Solange ein Gerät noch sendet, funktioniert die Suche nicht; elektronische Störungen verkleinern die Reichweite. Beides gehört in den ersten Schritt.",
    "q.l37#3.p" to "Worauf achtet man in der Signal- und Hinweissuche zuerst?",
    "q.l37#3.o0" to "Auf sichtbare Hinweise an der Schneeoberfläche (Handschuh, Stockende, Rucksackgurt)",
    "q.l37#3.o1" to "Auf den Wert am LVS",
    "q.l37#3.o2" to "Auf den Schneedeckenaufbau",
    "q.l37#3.o3" to "Auf die Windrichtung",
    "q.l37#3.e" to "Oberflächliche Hinweise können das Suchgebiet auf wenige Dutzend Meter verkleinern. Wer sofort auf das Gerät schaut, übersieht sie.",
    "q.l37#4.p" to "Auf welchen Abstand wird in der Grobsuche heruntergegangen?",
    "q.l37#4.o0" to "3–5 Meter",
    "q.l37#4.o1" to "20 Meter",
    "q.l37#4.o2" to "0,5 Meter",
    "q.l37#4.o3" to "10–15 Meter",
    "q.l37#4.e" to "Erst unter 3–5 Metern beginnt die Feinsuche. Hier wechselt man vom Laufen zum Gehen, und hier beginnt die Genauigkeit zu zählen.",
    "q.l37#5.p" to "Der angezeigte Abstand wird während der Grobsuche größer. Was bedeutet das?",
    "q.l37#5.o0" to "Die Richtung ist falsch, auf demselben Weg zurückgehen",
    "q.l37#5.o1" to "Das Signal ist zu stark",
    "q.l37#5.o2" to "Das Gerät ist defekt",
    "q.l37#5.o3" to "Die verschüttete Person hat sich bewegt",
    "q.l37#5.e" to "Das LVS zeigt einen Abstand; wächst er, geht man in die falsche Richtung. Diese Entscheidung muss schnell fallen, nicht mit langem Nachprüfen.",
    "q.l37#6.p" to "Wie geht man in der Feinsuche richtig vor?",
    "q.l37#6.o0" to "Das Gerät dicht über den Schnee führen, kreuzweise, die Stelle mit dem kleinsten Wert suchen und markieren",
    "q.l37#6.o1" to "Im Stehen im Kreis drehen",
    "q.l37#6.o2" to "Gerade hangabwärts gehen",
    "q.l37#6.o3" to "Mit der Sonde wahllos einstechen",
    "q.l37#6.e" to "Dicht über dem Schnee verringert Fehler durch Brechung im Schnee. Der kleinste Wert zu markieren gibt der Sonde einen klaren Startpunkt.",
    "q.l37#7.p" to "In welchem Winkel zur Schneeoberfläche wird bei der Punktsondierung eingestochen?",
    "q.l37#7.o0" to "Im 90-Grad-Winkel zur Schneeoberfläche (zum Hang)",
    "q.l37#7.o1" to "Im 90-Grad-Winkel zur Horizontalen",
    "q.l37#7.o2" to "Im 45-Grad-Winkel zum Hang",
    "q.l37#7.o3" to "In beliebigem Winkel",
    "q.l37#7.e" to "Senkrecht zur Horizontalen lässt die Sonde schräg durch die Schneedecke laufen, und der Hangwinkel vergrößert den Tiefenwert. Bei der Partnerrettung wird im 90-Grad-Winkel zur Schneeoberfläche sondiert.",
    "q.l37#8.p" to "Der erste Einstich trifft nichts. Wie geht es weiter?",
    "q.l37#8.o0" to "Im Raster von 25 Zentimetern nach außen erweitern",
    "q.l37#8.o1" to "Eine längere Sonde nehmen",
    "q.l37#8.o2" to "Direkt mit der Schaufel graben",
    "q.l37#8.o3" to "Diesen Punkt aufgeben",
    "q.l37#8.e" to "25 Zentimeter (etwa 10 Zoll) ist das Standardraster. Größer heißt Lücken, kleiner heißt Zeitverlust.",
    "q.l37#9.p" to "Woran erkennt man nach einem Treffer, ob es ein Mensch ist?",
    "q.l37#9.o0" to "Am «weichen, elastischen, körperähnlichen» Widerstand und am Vergleich mit der Umgebungstiefe",
    "q.l37#9.o1" to "Hauptsache hart getroffen, dann graben",
    "q.l37#9.o2" to "Ob Blut an der Sonde ist",
    "q.l37#9.o3" to "Am Geräusch",
    "q.l37#9.e" to "Stein und Eis haben einen harten, spröden Widerstand; ein Körper ist elastisch. Außerdem liegt eine verschüttete Person meist nicht tiefer als der umgebende Boden.",
    "q.l37#10.p" to "Wie wird die Sonde nach einem Treffer behandelt?",
    "q.l37#10.o0" to "Stecken lassen als Markierung für Lage und Tiefe",
    "q.l37#10.o1" to "Sofort herausziehen",
    "q.l37#10.o2" to "Noch tiefer hineindrücken",
    "q.l37#10.o3" to "An eine andere Person weitergeben",
    "q.l37#10.e" to "Die steckende Sonde ist das Zielkreuz der Grabenden und die Referenz dafür, ob man an der richtigen Stelle gräbt.",
    "q.l37#11.p" to "Die Verschüttung ist tiefer als die Sonde lang. Was ist richtig?",
    "q.l37#11.o0" to "Etwa einen Meter abtragen, mit dem LVS neu lokalisieren und erneut sondieren",
    "q.l37#11.o1" to "Weiter mit Gewalt sondieren",
    "q.l37#11.o2" to "Aufgeben",
    "q.l37#11.o3" to "Jemand anderen sondieren lassen",
    "q.l37#11.e" to "Mit Gewalt zu sondieren bringt nichts, weil man den Grund nicht erreicht. Erst den Abstand verringern, dann neu orten – nur so funktioniert es.",
    "q.l37#12.p" to "Warum wird beim organisierten Einsatz die Sonde senkrecht (zur Horizontalen) gehalten?",
    "q.l37#12.o0" to "Damit die Tiefenwerte der verschiedenen Personen vergleichbar sind und eine einheitliche Suchfläche entsteht",
    "q.l37#12.o1" to "Weil es kräftesparender ist",
    "q.l37#12.o2" to "Weil es schneller ist",
    "q.l37#12.o3" to "Weil es die Norm so verlangt",
    "q.l37#12.e" to "Eine organisierte Suchlinie ist eine Fläche und braucht vergleichbare Tiefenwerte. Die Partnerrettung zielt auf einen Punkt, deshalb ist dort senkrecht zur Schneeoberfläche genauer.",
    "q.l37#13.p" to "Was gehört zur Kontrolle des LVS vor dem Start?",
    "q.l37#13.o0" to "Ausreichende Batteriekapazität",
    "q.l37#13.o1" to "Ein Sendetest",
    "q.l37#13.o2" to "Empfang, Markieren und Unterdrücken beherrschen",
    "q.l37#13.o3" to "Am Körper tragen, nicht unten im Rucksack",
    "q.l37#13.e" to "Fehlt einer dieser vier Punkte, versagt das Gerät im entscheidenden Moment. Unten im Rucksack ist der häufigste Fehler – wird der Rucksack verschüttet oder verloren, ist das Gerät weg.",
    "q.l37#14.p" to "Worauf ist bei der Sonde zu achten?",
    "q.l37#14.o0" to "Länge passend zur lokalen Schneetiefe",
    "q.l37#14.o1" to "Zugseil und Verschluss in Ordnung",
    "q.l37#14.o2" to "Mit einer Hand auslegbar und arretierbar",
    "q.l37#14.o3" to "Möglichst leicht",
    "q.l37#14.e" to "Für Rettungsgruppen werden mindestens 3 Meter empfohlen (UIAA 157); persönlich sind 240–320 Zentimeter üblich. Leicht ist gut, Festigkeit und sichere Arretierung sind wichtiger.",
    "q.l37#15.p" to "Mehrere Personen sind verschüttet. Was ist richtig?",
    "q.l37#15.o0" to "Zuerst das erste Signal markieren oder unterdrücken",
    "q.l37#15.o1" to "Dann das zweite Signal suchen",
    "q.l37#15.o2" to "Nicht an einem Signal hängen bleiben und andere Bereiche aufgeben",
    "q.l37#15.o3" to "Nur die nächstgelegene Person retten",
    "q.l37#15.e" to "Bei mehreren Verschütteten ist das größte Risiko, nur einen zu finden. Genau dafür gibt es die Funktionen Markieren und Unterdrücken.",
    "q.l37#16.p" to "Bringe eine vollständige Suche in die richtige Reihenfolge.",
    "q.l37#16.o0" to "Alle Geräte auf Empfang, Störquellen ausschalten",
    "q.l37#16.o1" to "Entlang der Suchstreifen die Signalsuche durchführen",
    "q.l37#16.o2" to "Grobsuche bis auf 3–5 Meter",
    "q.l37#16.o3" to "Feinsuche bis zur Stelle mit dem kleinsten Wert, diese markieren",
    "q.l37#16.o4" to "Punktsondierung und Sonde stecken lassen",
    "q.l37#16.e" to "Die fünf Schritte ziehen sich von der Fläche zum Punkt zusammen. Wer einen Schritt sparen will, zahlt beim nächsten doppelt.",
    "q.l37#17.p" to "Bringe die Punktsondierung in die richtige Reihenfolge.",
    "q.l37#17.o0" to "Von der Stelle mit dem kleinsten Wert ausgehen, Sonde im 90-Grad-Winkel zur Schneeoberfläche",
    "q.l37#17.o1" to "Ohne Treffer im 25-Zentimeter-Raster erweitern",
    "q.l37#17.o2" to "Bei elastischem Widerstand innehalten",
    "q.l37#17.o3" to "Sonde als Markierung stecken lassen und mit dem Graben beginnen",
    "q.l37#17.e" to "Am häufigsten wird der letzte Schritt falsch gemacht: Viele ziehen die Sonde sofort nach dem Treffer heraus und verlieren damit die Referenz beim Graben.",
    "q.l37#18.p" to "Der Abstand der Suchstreifen beträgt etwa ______ Meter.",
    "q.l37#18.a0" to "40",
    "q.l37#18.e" to "Bei Unsicherheit auf 30 Meter verengen. Ein zu breiter Streifen lässt Signale durch – die häufigste Ursache für eine erfolglose Suche.",
    "q.l37#19.p" to "Die Kantenlänge des Rasters bei der Punktsondierung beträgt ______ Zentimeter.",
    "q.l37#19.a0" to "25",
    "q.l37#19.e" to "Etwa 10 Zoll. Ein zu großes Raster verfehlt den Körper, ein zu kleines kostet Zeit.",
    "q.l37#20.p" to "Bei der Partnerrettung wird die Sonde im 90-Grad-Winkel zur ______ eingestochen.",
    "q.l37#20.a0" to "Schneeoberfläche",
    "q.l37#20.a1" to "Hangfläche",
    "q.l37#20.e" to "Senkrecht zur Horizontalen vergrößert der Hangwinkel den Tiefenwert – der häufigste geometrische Fehler von Anfängern.",
    "q.l37#21.p" to "Ordne jeder Suchphase ihr Ziel zu.",
    "q.l37#21.l0" to "Signal- und Hinweissuche",
    "q.l37#21.l1" to "Grobsuche",
    "q.l37#21.l2" to "Feinsuche",
    "q.l37#21.l3" to "Punktsondierung",
    "q.l37#21.r0" to "Das erste Signal finden",
    "q.l37#21.r1" to "Den Abstand auf 3–5 Meter verringern",
    "q.l37#21.r2" to "Die oberflächlich nächste Stelle zur verschütteten Person finden",
    "q.l37#21.r3" to "Lage und Tiefe mit der Sonde bestätigen",
    "q.l37#21.e" to "Die vier Ziele ziehen sich stufenweise zusammen. Ziele zu kennen ist anpassungsfähiger, als Bewegungsabläufe zu lernen.",
    "q.l37#22.p" to "Ordne jedem Ausrüstungsteil seine Kernanforderung zu.",
    "q.l37#22.l0" to "LVS",
    "q.l37#22.l1" to "Sonde",
    "q.l37#22.l2" to "Schaufel",
    "q.l37#22.l3" to "Helm",
    "q.l37#22.r0" to "Digitale Dreiantenne, am Körper getragen, Markieren und Unterdrücken beherrscht",
    "q.l37#22.r1" to "Länge passend zur Schneetiefe, einhändig arretierbar",
    "q.l37#22.r2" to "Metallblatt, stabiler Schaft, schnell griffbereit",
    "q.l37#22.r3" to "Während Suche und Graben durchgehend tragen",
    "q.l37#22.e" to "Am häufigsten vergessen wird der Helm: Beim Graben fallen weiter Schneeblöcke und Eisstücke von oben.",
    "q.l37#23.p" to "Jemand bleibt am ersten Signal stehen und prüft es immer wieder. Was solltest du tun?",
    "q.l37#23.o0" to "Daran erinnern, zuerst zu markieren oder zu unterdrücken und die übrige Fläche weiter abzudecken",
    "q.l37#23.o1" to "Ihn weitermachen lassen",
    "q.l37#23.o2" to "Mit ihm stehen bleiben",
    "q.l37#23.o3" to "Die Suche abbrechen",
    "q.l37#23.e" to "Bei mehreren Verschütteten ist «zuerst alle Signale finden» wichtiger als «einen Punkt perfekt bestätigen».",
    "q.l37#24.p" to "Warum müssen während der Suche Handys und Kameras ausgeschaltet werden?",
    "q.l37#24.o0" to "Elektronische Geräte stören das LVS-Signal und verkürzen die nutzbare Suchweite",
    "q.l37#24.o1" to "Um Akku zu sparen",
    "q.l37#24.o2" to "Um es ruhig zu haben",
    "q.l37#24.o3" to "Damit niemand fotografiert",
    "q.l37#24.e" to "Störungen verkleinern die wirksame Breite des Suchstreifens und führen indirekt zu Lücken. In der Praxis wird diese Regel am häufigsten aufgeweicht.",
    "q.l37#25.p" to "Die Gruppe besteht aus zwei Personen, eine sucht, eine gräbt. Ist diese Aufteilung sinnvoll?",
    "q.l37#25.o0" to "Ja, aber nach dem Treffer sollten beide im Wechsel graben, nicht einer allein durchziehen",
    "q.l37#25.o1" to "Nein, beide sollten suchen",
    "q.l37#25.o2" to "Nein, man sollte auf Rettung warten",
    "q.l37#25.o3" to "Ja, und Wechsel ist nicht nötig",
    "q.l37#25.e" to "In der Zweiergruppe gilt «Treffer heißt Staffelübergabe». Wer allein durchgräbt, ist nach wenigen Minuten erschöpft und wird langsamer.",
    "q.l37#26.p" to "Vor der Suche hängt über dem Ablagerungsbereich noch Schnee. Was ist zu tun?",
    "q.l37#26.o0" to "Zuerst einen Sicherungsposten benennen und einen sicheren Anmarschweg wählen, dann suchen",
    "q.l37#26.o1" to "Direkt hineinlaufen",
    "q.l37#26.o2" to "Warten, bis der Schneefall aufhört",
    "q.l37#26.o3" to "Die Suche aufgeben",
    "q.l37#26.e" to "Dass Rettende von einer zweiten Lawine verschüttet werden, ist ein realer Unfalltyp. Sicherungsposten und Anmarschweg sind Teil der Suche, kein Zusatzschritt.",
    "q.l37#27.p" to "Was bedeuten die Ziele «10 Minuten bis zum Kontakt, 18 Minuten bis zum Ausgraben»?",
    "q.l37#27.o0" to "Sie sind interne Richtwerte für Training und Nachbereitung, keine Zusage",
    "q.l37#27.o1" to "Sie sind ein medizinisches Versprechen",
    "q.l37#27.o2" to "Sie sind eine Normvorgabe",
    "q.l37#27.o3" to "Sie sind eine Geräteleistung",
    "q.l37#27.e" to "Die Werte zeigen der Gruppe, an welchem Schritt sie langsam ist. Sie als Zusage zu lesen führt dazu, dass man die Beurteilung verliert, wenn sie nicht erreicht werden.",
    "q.l38#0.p" to "Was ist die erste Regel beim Graben?",
    "q.l38#0.o0" to "Immer von der Talseite aus arbeiten",
    "q.l38#0.o1" to "Von oben nach unten graben",
    "q.l38#0.o2" to "Von der Bergseite nach unten graben",
    "q.l38#0.o3" to "Seitlich waagerecht hineingraben",
    "q.l38#0.e" to "Die Talseite hat drei Vorteile: Der Schnee lässt sich nach unten werfen, der Kanal hat Gefälle, und die Grabenden stehen nicht über der verschütteten Person.",
    "q.l38#1.p" to "Was beschreibt die klassische Merkregel «das 1,5-Fache der Verschüttungstiefe»?",
    "q.l38#1.o0" to "Die Strecke, um die man vom Sondenstab hangabwärts abrückt",
    "q.l38#1.o1" to "Die Breite des Kanals",
    "q.l38#1.o2" to "Die Länge der Sonde",
    "q.l38#1.o3" to "Die Grabungszeit",
    "q.l38#1.e" to "Der Abstand schafft Platz für den Schneetransport. Es ist eine Erfahrungsregel – neuere Untersuchungen bieten eine Alternative.",
    "q.l38#2.p" to "Was empfiehlt die Untersuchung zum Schneekonveyor von 2023 für den Ansatzpunkt?",
    "q.l38#2.o0" to "Ab drei Personen und genug Platz direkt am Sondenstab entlang der Falllinie abwärts graben",
    "q.l38#2.o1" to "Immer das 1,5-Fache der Tiefe abrücken",
    "q.l38#2.o2" to "Von oben graben",
    "q.l38#2.o3" to "Seitlich waagerecht graben",
    "q.l38#2.e" to "Ein versetzter Ansatz verlängert den Weg bis zur Kopfposition. Die Empfehlung gilt unter der Voraussetzung «genug Helfende» und lässt sich nicht blind übertragen.",
    "q.l38#3.p" to "Wann ist ein versetzter Ansatz sinnvoll?",
    "q.l38#3.o0" to "Bei sehr geringer Tiefe, wenn die Füße fast ebenso tief liegen, oder bei zu wenigen Helfenden für ein Ein-Personen-Vorgehen",
    "q.l38#3.o1" to "Immer",
    "q.l38#3.o2" to "Bei sehr hartem Schnee",
    "q.l38#3.o3" to "Bei Dunkelheit",
    "q.l38#3.e" to "In diesen beiden Fällen verringert der Versatz unnötiges Umlagern. Sonst ist der Ansatz direkt am Sondenstab schneller.",
    "q.l38#4.p" to "Wie breit ist der Kanal des Konveyors üblicherweise?",
    "q.l38#4.o0" to "1–2 Meter",
    "q.l38#4.o1" to "0,3 Meter",
    "q.l38#4.o2" to "3–4 Meter",
    "q.l38#4.o3" to "Je schmaler, desto besser",
    "q.l38#4.e" to "Zu schmal senkt die Transportleistung, zu breit vervielfacht die Grabungsmenge. 1–2 Meter ist der Kompromiss zwischen Effizienz und Aufwand.",
    "q.l38#5.p" to "Unter welcher Kanalneigung rollt der Schnee zum Sondenstab zurück?",
    "q.l38#5.o0" to "26 Grad",
    "q.l38#5.o1" to "10 Grad",
    "q.l38#5.o2" to "45 Grad",
    "q.l38#5.o3" to "60 Grad",
    "q.l38#5.e" to "26 Grad ist der in der Untersuchung genannte kritische Wert. Reicht das Gefälle nicht, rutscht der weggeschaufelte Schnee zurück – die Arbeit war umsonst.",
    "q.l38#6.p" to "Welche der drei Techniken zum Wegbewegen des Schnees ist am effizientesten?",
    "q.l38#6.o0" to "Schlagen (paddling)",
    "q.l38#6.o1" to "Schaufeln (scooping)",
    "q.l38#6.o2" to "Blöcke schneiden (cutting blocks)",
    "q.l38#6.o3" to "Alle gleich",
    "q.l38#6.e" to "Beim Schlagen wird der Schnee «gewischt», die Bewegung ist fortlaufend und schnell. Blöcke schneiden eignet sich nur für harten Schnee, weil zuerst geschnitten werden muss.",
    "q.l38#7.p" to "Wozu wird beim Graben eine Person als Leitung bestimmt?",
    "q.l38#7.o0" to "Sie beobachtet Richtung, Schneelage oberhalb und Position der verschütteten Person – damit nicht alle mit gesenktem Kopf graben",
    "q.l38#7.o1" to "Zur Arbeitsaufsicht",
    "q.l38#7.o2" to "Zum Fotografieren",
    "q.l38#7.o3" to "Zur Einsparung von Personal",
    "q.l38#7.e" to "Sobald alle den Kopf senken, wird schief gegraben und die Gefahr einer zweiten Lawine übersehen. Die Leitung ist die einzige Person, die aufschaut.",
    "q.l38#8.p" to "Wie ändert sich die Reihenfolge, sobald das Gesicht erreicht ist?",
    "q.l38#8.o0" to "Erst Mund und Nase freimachen und Atemwege prüfen, dann Brust und Arme, zuletzt Beine und Körper",
    "q.l38#8.o1" to "Zuerst die Beine",
    "q.l38#8.o2" to "Zuerst an den Schultern ziehen",
    "q.l38#8.o3" to "Zuerst den Rucksack freimachen",
    "q.l38#8.e" to "Nur mit freiem Brustkorb ist Beatmung möglich. Zuerst die Beine zu befreien verzögert die Ventilation, und an den Schultern zu ziehen kann die Wirbelsäule schädigen.",
    "q.l38#9.p" to "Worauf stützt sich die Aussage «auch eine Person kann retten»?",
    "q.l38#9.o0" to "Unter Versuchsbedingungen schafft ein Ein-Personen-Konveyor mit begrenzten Mitteln auch 1,5 Meter Tiefe in 18 Minuten",
    "q.l38#9.o1" to "Weil Menschen Reserven haben",
    "q.l38#9.o2" to "Weil Schnee leicht ist",
    "q.l38#9.o3" to "Weil Verschüttete sich selbst befreien",
    "q.l38#9.e" to "Grabgeschwindigkeiten von etwa 13,2 Zentimetern pro Minute in hartem und 25,3 in weichem Schnee sind Messwerte – sie zeigen, dass sich das Ein-Personen-Vorgehen zum Üben lohnt.",
    "q.l38#10.p" to "Wie hoch sind die Grabgeschwindigkeiten in hartem und weichem Schnee etwa?",
    "q.l38#10.o0" to "Harter Schnee etwa 13 cm pro Minute, weicher etwa 25 cm pro Minute",
    "q.l38#10.o1" to "Beide etwa 5 cm pro Minute",
    "q.l38#10.o2" to "Beide etwa 50 cm pro Minute",
    "q.l38#10.o3" to "Harter Schnee ist schneller",
    "q.l38#10.e" to "Dieser Unterschied erklärt, warum die Schneequalität die Erwartung an die Rettungszeit verändert – und warum Blöcke schneiden nur bei hartem Schnee sinnvoll ist.",
    "q.l38#11.p" to "Was ist der häufigste Fehler beim Graben mit mehreren Personen?",
    "q.l38#11.o0" to "Alle drängen sich an einer Stelle, ohne Weitergabe und Wechsel",
    "q.l38#11.o1" to "Zu breit graben",
    "q.l38#11.o2" to "Zu schnell graben",
    "q.l38#11.o3" to "Die Schaufel benutzen",
    "q.l38#11.e" to "Dicht beieinander stehen alle im Weg und ist nicht durchhaltbar. Ein Wechselrhythmus ist deutlich schneller als «einer hält durch».",
    "q.l38#12.p" to "Welche Rollen müssen beim organisierten Graben besetzt sein?",
    "q.l38#12.o0" to "Leitung",
    "q.l38#12.o1" to "Graben und Schneetransport",
    "q.l38#12.o2" to "Sicherungsposten",
    "q.l38#12.o3" to "Eine Person für Zeit und Position",
    "q.l38#12.e" to "Die vier Rollen verteilen Richtung, Kraft, Sicherheit und Zeit. Fehlt eine, gerät genau dieser Punkt außer Kontrolle.",
    "q.l38#13.p" to "Welche Vorgehensweisen bringen den weggeschafften Schnee wieder zurück?",
    "q.l38#13.o0" to "Von oben oder von der Bergseite graben",
    "q.l38#13.o1" to "Zu flaches Kanalgefälle (unter etwa 26 Grad)",
    "q.l38#13.o2" to "Schnee oberhalb des Sondenstabs aufhäufen",
    "q.l38#13.o3" to "Den Kanal entlang der Falllinie anlegen",
    "q.l38#13.e" to "Die ersten drei lassen den Schnee zurückrutschen. Der vierte Punkt ist genau die richtige Vorgehensweise.",
    "q.l38#14.p" to "Was ist zum Ansatzpunkt richtig?",
    "q.l38#14.o0" to "Die klassische Merkregel lautet 1,5-fache Tiefe, von der Talseite queren",
    "q.l38#14.o1" to "Avalanche.org vereinfacht: bei weniger als einem Meter Tiefe einen Schritt zurück, bei mehr zwei",
    "q.l38#14.o2" to "ISSW 2023 empfiehlt bei genug Helfenden den Ansatz am Sondenstab entlang der Falllinie",
    "q.l38#14.o3" to "Merkregel und Forschung widersprechen sich völlig, es gilt nur eines",
    "q.l38#14.e" to "Die drei Aussagen sind «Prinzip plus zwei Generationen Erfahrung». In der Lehre gilt Prinzip → Merkregel → Update, dann wird die Merkregel nicht zum Aberglauben.",
    "q.l38#15.p" to "Bringe eine Standardgrabung in die richtige Reihenfolge.",
    "q.l38#15.o0" to "Arbeitsfläche auf der Talseite und Gefahr einer zweiten Lawine klären",
    "q.l38#15.o1" to "Vom Ansatzpunkt einen V-förmigen Kanal in Richtung Sonde graben",
    "q.l38#15.o2" to "Transportkette organisieren und wechseln",
    "q.l38#15.o3" to "Nach Erreichen des Gesichts zuerst Mund und Nase freimachen",
    "q.l38#15.e" to "Der Kern der Reihenfolge: erst Sicherheit, dann Effizienz, zuletzt die Priorität auf die Atemwege.",
    "q.l38#16.p" to "Bringe den Ablauf «nach Erreichen des Gesichts» in die richtige Reihenfolge.",
    "q.l38#16.o0" to "Schnee und Eisstücke aus Mund und Nase entfernen, Atemwege prüfen",
    "q.l38#16.o1" to "Schnee um Brust und Arme entfernen, damit sich der Brustkorb entfalten kann",
    "q.l38#16.o2" to "Beine und übrigen Körper freimachen",
    "q.l38#16.o3" to "Nach den Reanimationsregeln behandeln und den Transport organisieren",
    "q.l38#16.e" to "Diese Reihenfolge ist das Gegenteil von «erst ausgraben, dann helfen» – und sie ist richtig: Das Zeitfenster für die Beatmung zählt in Minuten.",
    "q.l38#17.p" to "Die kritische Neigung des Konveyor-Kanals liegt bei etwa ______ Grad.",
    "q.l38#17.a0" to "26",
    "q.l38#17.e" to "Unterhalb dieses Winkels rollen Schneeblöcke zum Sondenstab zurück und die Transportleistung bricht ein.",
    "q.l38#18.p" to "Die klassische Merkregel empfiehlt, vom Sondenstab hangabwärts etwa das ______-Fache der Verschüttungstiefe abzurücken.",
    "q.l38#18.a0" to "1,5",
    "q.l38#18.a1" to "1.5",
    "q.l38#18.e" to "Das 1,5-Fache ist eine Erfahrungsregel. Bei genug Helfenden sollte der Ansatz am Sondenstab entlang der Falllinie Vorrang haben.",
    "q.l38#19.p" to "Das Ziel der Partnerrettung liegt bei ______ Minuten bis zum Kontakt und 18 Minuten bis zum Ausgraben.",
    "q.l38#19.a0" to "10",
    "q.l38#19.e" to "10 und 18 sind interne Richtwerte für Training und Nachbereitung, um zu erkennen, an welchem Schritt es hakt.",
    "q.l38#20.p" to "Ordne jeder Technik ihre Einsatzbedingung zu.",
    "q.l38#20.l0" to "Schlagen (paddling)",
    "q.l38#20.l1" to "Schaufeln (scooping)",
    "q.l38#20.l2" to "Blöcke schneiden (cutting blocks)",
    "q.l38#20.l3" to "Weitergabe (conveyor)",
    "q.l38#20.r0" to "Am effizientesten, für die meisten lockeren Schneearten",
    "q.l38#20.r1" to "Danach, um Schnee aus dem Kanal zu bringen",
    "q.l38#20.r2" to "Am langsamsten, nur bei hartem Schnee",
    "q.l38#20.r3" to "Die Organisationsform bei mehreren Personen",
    "q.l38#20.e" to "Die Effizienzreihenfolge bestimmt «erst schlagen, dann schaufeln, Blöcke nur bei hartem Schnee». Weitergabe ist keine Technik, sondern eine Organisationsform.",
    "q.l38#21.p" to "Ordne jedem häufigen Fehler seine Folge zu.",
    "q.l38#21.l0" to "Von der Bergseite graben",
    "q.l38#21.l1" to "Zu flaches Kanalgefälle",
    "q.l38#21.l2" to "Nach dem Treffer zuerst am Körper ziehen",
    "q.l38#21.l3" to "Sonde nach dem Treffer herausziehen",
    "q.l38#21.r0" to "Schneeblöcke rollen ins Gesicht, langsam und gefährlich",
    "q.l38#21.r1" to "Schnee läuft zurück, mehrfaches Umlagern",
    "q.l38#21.r2" to "Kann die Wirbelsäule schädigen und Schnee in Mund und Nase schieben",
    "q.l38#21.r3" to "Die Referenz für Lage und Tiefe geht verloren",
    "q.l38#21.e" to "Alle vier Fehler sind häufig – und alle lassen sich durch vorheriges Üben vermeiden.",
    "q.l38#22.p" to "Der Schnee ist hart und die Gruppe besteht aus drei Personen. Wie wird der Ansatzpunkt gewählt?",
    "q.l38#22.o0" to "Am Sondenstab entlang der Falllinie, harte Abschnitte mit der Blocktechnik öffnen",
    "q.l38#22.o1" to "Das Dreifache der Tiefe abrücken",
    "q.l38#22.o2" to "Von oben graben",
    "q.l38#22.o3" to "Auf Gerät warten",
    "q.l38#22.e" to "Bei genug Helfenden gilt die Falllinie; harter Schnee ändert nur die Technik (Blöcke schneiden), nicht das Prinzip.",
    "q.l38#23.p" to "Warum ist «alle graben gleichzeitig mit aller Kraft» nicht schneller?",
    "q.l38#23.o0" to "Sie stehen sich im Weg, halten nicht durch, und niemand beobachtet den Schnee oberhalb",
    "q.l38#23.o1" to "Weil es zu warm wird",
    "q.l38#23.o2" to "Weil es zu wenige Schaufeln gibt",
    "q.l38#23.o3" to "Weil niemand die Leitung hat",
    "q.l38#23.e" to "Graben ist eine sehr intensive Tätigkeit, nach wenigen Minuten ist die Kraft weg. Wechsel, Leitung und Weitergabe verwandeln Personal erst in Geschwindigkeit.",
    "q.l38#24.p" to "Beim Graben liegt ein großer harter Schneeblock neben der verschütteten Person. Was ist richtig?",
    "q.l38#24.o0" to "Zuerst den Weg zu den Atemwegen freimachen, nicht wegen des Blocks die Beatmung verzögern",
    "q.l38#24.o1" to "Zuerst den Block wegschaffen",
    "q.l38#24.o2" to "Den Block mit dem Pickel zerschlagen",
    "q.l38#24.o3" to "Um den Block herumgraben",
    "q.l38#24.e" to "Der Block kann später weg. Das Zeitfenster für die Atemwege zählt in Minuten und hat Vorrang vor «die Stelle aufräumen».",
    "q.l38#25.p" to "Es ist nur eine Schaufel vorhanden. Was ist am sinnvollsten?",
    "q.l38#25.o0" to "Die körperlich stärkste Person gräbt, die anderen schieben mit Händen und Skiern und lösen sie ab",
    "q.l38#25.o1" to "Eine Person gräbt die ganze Zeit allein",
    "q.l38#25.o2" to "Auf eine zweite Schaufel warten",
    "q.l38#25.o3" to "Den Rucksack als Schaufel benutzen",
    "q.l38#25.e" to "Richtig ist der «Konveyor mit begrenzten Mitteln»: einer gräbt, die anderen bringen den Schnee nach außen.",
    "q.l38#26.p" to "In der Nachbereitung zeigt sich: Der Kontakt dauerte 14 Minuten. Welcher Schritt ist vor allem zu prüfen?",
    "q.l38#26.o0" to "Suche und Lokalisierung – welche der vier Phasen war langsam",
    "q.l38#26.o1" to "Die Grabungsphase",
    "q.l38#26.o2" to "Der Notruf",
    "q.l38#26.o3" to "Der Einkauf der Ausrüstung",
    "q.l38#26.e" to "Die Kontaktzeit wird von Suche und Lokalisierung bestimmt, die Grabungszeit vom Graben. Beide Werte müssen getrennt betrachtet werden.",
    // ---------- l23 Ausrüstungsliste und Tragesystem ----------
    "q.l23#0.p" to "Welche Kategorie sollte beim Aufstellen der Ausrüstungsliste zuerst feststehen?",
    "q.l23#0.o0" to "Wärme und Schutz sowie die technische Ausrüstung",
    "q.l23#0.o1" to "Kamera und Powerbank",
    "q.l23#0.o2" to "Snacks und Gewürze",
    "q.l23#0.o3" to "Frische Wechselkleidung",
    "q.l23#0.e" to "Die Reihenfolge der Liste entscheidet, was bei Schlechtwetter fehlt. Wärme, Schutz und technische Ausrüstung gehören zur Gruppe «fehlt sie, passiert etwas»; fehlender Komfort ist nur unangenehm.",

    "q.l23#1.p" to "Welche Volumina wählt man üblicherweise für Gipfelrucksack und Transporttasche?",
    "q.l23#1.o0" to "35–50 Liter / 90–120 Liter",
    "q.l23#1.o1" to "20–30 Liter / 50–60 Liter",
    "q.l23#1.o2" to "60–70 Liter / 60 Liter",
    "q.l23#1.o3" to "Je grösser, desto besser",
    "q.l23#1.e" to "Der Gipfelrucksack fasst den Tagesbedarf: Wärmeschicht, Verpflegung, Wasser, Stirnlampe, kleines Erste-Hilfe-Set. Das schwere Gepäck geht als Lasttransport und wird nicht ins Hochlager getragen.",

    "q.l23#2.p" to "Wo gehören schwere Gegenstände im Rucksack hin?",
    "q.l23#2.o0" to "Am Rücken, zwischen den Schulterblättern (oberer Rücken)",
    "q.l23#2.o1" to "Ganz nach unten",
    "q.l23#2.o2" to "Ganz nach aussen",
    "q.l23#2.o3" to "Dorthin, wo man schnell herankommt",
    "q.l23#2.e" to "Schweres nah am Rücken und hoch platziert hält den Schwerpunkt nahe am Körper und über der Hüfte; nur so bleibt der Gang stabil. Schweres am Boden zieht den Rucksack nach unten, belastet den Hüftgurt ungleich und schmerzt nach Stunden im Kreuz.",

    "q.l23#3.p" to "Worauf lastet das Gewicht des Rucksacks hauptsächlich?",
    "q.l23#3.o0" to "Auf dem Hüftgurt (etwa 60–70 %); die Schultergurte halten ihn nur am Körper",
    "q.l23#3.o1" to "Auf den Schultergurten",
    "q.l23#3.o2" to "Auf dem Brustkorb",
    "q.l23#3.o3" to "Auf einem Umhängeband am Hals",
    "q.l23#3.e" to "Der Hüftgurt leitet das Gewicht auf das Becken, den tragfähigsten Teil des Körpers. Wer nach kurzer Strecke die Schultern spürt, hat den Hüftgurt zu locker oder zu hoch sitzen.",

    "q.l23#4.p" to "Auf welchen Anteil des Körpergewichts sollte das Rucksackgewicht am Gipfeltag begrenzt werden?",
    "q.l23#4.o0" to "15–20 %",
    "q.l23#4.o1" to "30–35 %",
    "q.l23#4.o2" to "40 %",
    "q.l23#4.o3" to "Es gibt keine Obergrenze",
    "q.l23#4.e" to "Bei 60 kg Körpergewicht sind das etwa 9–12 kg. Darüber steigen der Sauerstoffverbrauch beim Aufstieg und das Risiko, das Gleichgewicht zu verlieren, deutlich.",

    "q.l23#5.p" to "Welches Vorgehen zum Schutz vor Nässe ist richtig?",
    "q.l23#5.o0" to "Schlafsack und Daunenjacke je in einem eigenen Packsack, Elektronik und Medikamente zusätzlich",
    "q.l23#5.o1" to "Der Rucksack ist dicht, Innensäcke sind unnötig",
    "q.l23#5.o2" to "Alles in einen einzigen grossen Sack",
    "q.l23#5.o3" to "Aussen einen Müllsack über den Rucksack ziehen genügt",
    "q.l23#5.e" to "An den Nähten dringt Wasser ein. Der Vorteil gestaffelter Verpackung: Selbst wenn die äussere Schicht nass wird, bleibt das Kerngepäck trocken, und ein gerissener Sack reisst nicht alles mit.",

    "q.l23#6.p" to "Welche drei Dinge werden vor dem Abmarsch am leichtesten vergessen und sind dann am gefährlichsten?",
    "q.l23#6.o0" to "Stirnlampe mit Ersatzbatterien, Reservehandschuhe, Erste-Hilfe-Set",
    "q.l23#6.o1" to "Sonnenbrille, Sonnencreme, Lippenpflege",
    "q.l23#6.o2" to "Trinkflasche, Essgeschirr, Essstäbchen",
    "q.l23#6.o3" to "Kamera, Stativ, Ersatzkarte",
    "q.l23#6.e" to "Die ersten beiden Punkte betreffen zwei häufige Szenarien: «vor Einbruch der Dunkelheit nicht zurück im Lager» und «Handschuhe durchnässt». Der dritte ist das, wovon alle annehmen, jemand anders bringe es mit.",

    "q.l23#7.p" to "An welchen Posten darf im Hochlager Gewicht eingespart werden?",
    "q.l23#7.o0" to "Ersatzkamera und Stativ",
    "q.l23#7.o1" to "Dritter Satz Wechselkleidung",
    "q.l23#7.o2" to "Stirnlampe und Ersatzbatterien",
    "q.l23#7.o3" to "Erste-Hilfe-Set",
    "q.l23#7.e" to "Gewicht spart man dort, wo es die Sicherheit nicht berührt. Stirnlampe, Erste-Hilfe-Set und Wärmeschicht sind nicht verhandelbar; Kamera und Wechselkleidung dienen dem Komfort.",

    "q.l23#8.p" to "Welche Merkmale zeichnen eine brauchbare Ausrüstungsliste aus?",
    "q.l23#8.o0" to "Nach Einsatzszenarien gruppiert, nicht nach Kaufreihenfolge",
    "q.l23#8.o1" to "Pflicht- und Optionalteile gekennzeichnet",
    "q.l23#8.o2" to "Unterschiede nach Jahreszeit und Höhenstufe",
    "q.l23#8.o3" to "Je länger, desto besser",
    "q.l23#8.e" to "Der Wert einer Liste liegt darin, dass man sie auch unter Druck abarbeiten kann. Gruppierung nach Szenario, markierte Pflichtteile und Anpassung an die Höhe machen sie direkt nutzbar; Länge führt eher dazu, dass man sie aufgibt.",

    "q.l23#9.p" to "Die Packreihenfolge in die richtige Abfolge bringen.",
    "q.l23#9.o0" to "Schlafsack und Daunenjacke in Packsäcke, ganz nach unten",
    "q.l23#9.o1" to "Schweres (Wasser, Kocher, technische Ausrüstung) am Rücken im oberen Mittelbereich",
    "q.l23#9.o2" to "Wärmeschicht und Tagesverpflegung nach oben",
    "q.l23#9.o3" to "Stirnlampe und Erste-Hilfe-Set in Deckelfach oder Seitentasche, sofort erreichbar",
    "q.l23#9.e" to "Zuerst das, was unterwegs nicht gebraucht wird, aber mit muss; dann das Schwere; zuletzt das, was ständig zur Hand sein soll. Stirnlampe und Erste-Hilfe-Set müssen ohne Abnehmen des Rucksacks erreichbar sein.",

    "q.l23#10.p" to "Wie lautet die richtige Prüfreihenfolge, nachdem der Rucksack aufgesetzt ist?",
    "q.l23#10.o0" to "Hüftgurt schliessen und festziehen",
    "q.l23#10.o1" to "Schultergurte an den Körper anpassen",
    "q.l23#10.o2" to "Brustgurt schliessen",
    "q.l23#10.o3" to "Aufstehen, einige Schritte gehen, Sitz prüfen",
    "q.l23#10.e" to "Eine vertauschte Reihenfolge drückt das Gewicht auf die Schultern: erst den Hüftgurt fixieren, dann die Schultergurte justieren; der Brustgurt verhindert nur das Verrutschen nach aussen. Zuletzt muss man in Bewegung prüfen.",

    "q.l23#11.p" to "Der Gipfelrucksack fasst üblicherweise 35–50 Liter, die Transporttasche ______ Liter.",
    "q.l23#11.a0" to "90–120",
    "q.l23#11.a1" to "90-120",
    "q.l23#11.a2" to "90~120",
    "q.l23#11.e" to "Die Transporttasche bringt das schwere Gepäck von der Strasse ins Lager; sie muss Schlafsack, Daunenjacke, Stiefel und technische Ausrüstung aufnehmen, üblich sind 90–120 Liter.",

    "q.l23#12.p" to "Der Hüftgurt trägt etwa ______ % des Rucksackgewichts (eine Zahl).",
    "q.l23#12.a0" to "60",
    "q.l23#12.a1" to "65",
    "q.l23#12.a2" to "70",
    "q.l23#12.a3" to "60–70",
    "q.l23#12.e" to "Etwa 60–70 %. Daran lässt sich auch der Sitz prüfen: Wer deutlich in den Schultern zieht, hat das Problem meist am Hüftgurt.",

    "q.l23#13.p" to "Rucksackbereich und passenden Inhalt einander zuordnen.",
    "q.l23#13.l0" to "Am Rücken, oberer Mittelbereich",
    "q.l23#13.l1" to "Rucksackboden",
    "q.l23#13.l2" to "Deckelfach",
    "q.l23#13.l3" to "Seitentasche",
    "q.l23#13.r0" to "Wasser, Kocher, technische Ausrüstung – also das Schwere",
    "q.l23#13.r1" to "Schlafsack und Daunenjacke (im Packsack)",
    "q.l23#13.r2" to "Wärmeschicht und Tagesverpflegung",
    "q.l23#13.r3" to "Stirnlampe, kleines Erste-Hilfe-Set, Sonnenschutz",
    "q.l23#13.e" to "Die Position bestimmt Zugriff und Schwerpunkt. Die Stirnlampe sitzt in der Seitentasche, damit bei Dunkelheit kein Suchen nötig ist; der Schlafsack liegt unten, weil er nur einmal täglich im Lager gebraucht wird.",

    "q.l23#14.p" to "Der Rucksack des Partners ist deutlich schwerer als der eigene. Was ist die sinnvollste Reaktion?",
    "q.l23#14.o0" to "Sofort alles ausbreiten und neu verteilen, die Gemeinschaftsausrüstung gleichmässig aufteilen",
    "q.l23#14.o1" to "Ihn selbst tragen lassen, das ist seine Entscheidung",
    "q.l23#14.o2" to "Die Hälfte übernehmen, auch wenn man selbst überladen ist",
    "q.l23#14.o3" to "Gemeinschaftsausrüstung wegwerfen",
    "q.l23#14.e" to "Das Tempo der Gruppe bestimmt der Langsamste, und Überladung macht den Langsamsten noch langsamer. Gemeinschaftsausrüstung wie Kocher, Seil und Erste-Hilfe-Set muss gleichmässig verteilt sein – und zwar vor dem Abmarsch.",

    // ---------- l24 Schlafsystem und Lagerausrüstung ----------
    "q.l24#0.p" to "Auf welche Temperaturangabe kommt es bei der Wahl des Schlafsacks an?",
    "q.l24#0.o0" to "Komforttemperatur",
    "q.l24#0.o1" to "Extremtemperatur",
    "q.l24#0.o2" to "Die tiefste Temperatur aus der Herstellerwerbung",
    "q.l24#0.o3" to "Das Gewicht",
    "q.l24#0.e" to "Die Komforttemperatur gibt an, bis zu welcher Temperatur man in Baselayer eine ganze Nacht ohne Frieren schläft; die Extremtemperatur ist nur die Grenze, an der man nicht erfriert. Zwischen beiden liegen oft mehr als 10 °C.",

    "q.l24#1.p" to "Wie ist die Komforttemperatur des Schlafsacks in grosser Höhe zu wählen?",
    "q.l24#1.o0" to "Mindestens 5 °C unter der erwarteten Tiefsttemperatur",
    "q.l24#1.o1" to "Gleich der erwarteten Tiefsttemperatur",
    "q.l24#1.o2" to "5 °C über der erwarteten Tiefsttemperatur",
    "q.l24#1.o3" to "Das spielt keine Rolle",
    "q.l24#1.e" to "Die Reserve ist nötig, weil der Stoffwechsel nachts sinkt, weniger gegessen wird und im Zelt Reif entstehen kann – die gefühlte Temperatur liegt tiefer als die Vorhersage.",

    "q.l24#2.p" to "Wogegen muss ein Daunenschlafsack vor allem geschützt werden?",
    "q.l24#2.o0" to "Feuchtigkeit – nass isoliert er fast nicht mehr",
    "q.l24#2.o1" to "Falten",
    "q.l24#2.o2" to "Sonne",
    "q.l24#2.o3" to "Abrieb",
    "q.l24#2.e" to "Feuchte Daune verliert ihre Loft und damit einen grossen Teil der Isolationsleistung; im Gelände lässt sie sich kaum wirklich trocknen. Ein wasserdichter Packsack ist die billigste wirksame Versicherung.",

    "q.l24#3.p" to "Wie werden Isomatten in Hochlagern üblicherweise eingesetzt?",
    "q.l24#3.o0" to "Geschlossenzellige Schaummatte und Luftmatte übereinander, die Dämmwerte addieren sich",
    "q.l24#3.o1" to "Nur eine Luftmatte",
    "q.l24#3.o2" to "Nur eine Alufolienmatte",
    "q.l24#3.o3" to "Direkt auf dem Zeltboden",
    "q.l24#3.e" to "Die Schaummatte unterbricht die Leitung in den Boden, die Luftmatte schafft eine ebene, bequeme Fläche. Die Kombination dient auch als Redundanz: Geht die Luftmatte kaputt, bleibt die Schaummatte.",

    "q.l24#4.p" to "Die Luftmatte verliert im Lager Luft. Was ist zuerst zu tun?",
    "q.l24#4.o0" to "Leckstelle finden und flicken, gleichzeitig die Schaummatte als Ersatz nutzen",
    "q.l24#4.o1" to "Weiterschlafen, morgen ist auch noch Zeit",
    "q.l24#4.o2" to "Die ganze Luft ablassen",
    "q.l24#4.o3" to "Das Zelt wechseln",
    "q.l24#4.e" to "Ein Leck wird mit der Zeit schlimmer, und nachts sinkt die Temperatur. Flicken plus Schaummatte als Reserve ist das Standardvorgehen; darauf zu setzen, dass es bis zum Morgen hält, ist ein Glücksspiel.",

    "q.l24#5.p" to "Wie wird ein Schlafsack richtig gelagert?",
    "q.l24#5.o0" to "Ausgebreitet oder locker aufgehängt an einem trockenen Ort",
    "q.l24#5.o1" to "Dauerhaft komprimiert im Packsack",
    "q.l24#5.o2" to "Vakuumiert",
    "q.l24#5.o3" to "Dicht verschlossen in einer Plastiktüte",
    "q.l24#5.e" to "Dauerhafte Kompression ermüdet die Loftstruktur der Daune; über einige Saisons sinkt die Wärmeleistung deutlich. Lagern heisst: locker und trocken.",

    "q.l24#6.p" to "Welche Massnahmen verbessern den Schlaf in grosser Höhe tatsächlich?",
    "q.l24#6.o0" to "Abends weniger trinken, über den Tag aber die Gesamtmenge decken",
    "q.l24#6.o1" to "Ohrstöpsel tragen, um Geräusche im Zelt zu dämpfen",
    "q.l24#6.o2" to "Nasse Kleidung zum Trocknen in den Schlafsack nehmen",
    "q.l24#6.o3" to "Vor dem Schlafen sehr reichlich essen",
    "q.l24#6.e" to "Nasse Kleidung im Schlafsack entzieht viel Wärme und durchfeuchtet die Daune – ein klassischer Fehler. Ein sehr voller Magen verstärkt das nächtliche Unbehagen.",

    "q.l24#7.p" to "Was gehört üblicherweise zu einem Schlafsystem?",
    "q.l24#7.o0" to "Schlafsack (mit Inlett)",
    "q.l24#7.o1" to "Isomatte (Schaum plus Luft)",
    "q.l24#7.o2" to "Kissen",
    "q.l24#7.o3" to "Zeltbodenplane",
    "q.l24#7.e" to "Diese vier Teile bestimmen zusammen Bodenleitung, Luftzirkulation und Komfort. Fehlt eines, geht nachts in genau dieser Richtung Wärme verloren.",

    "q.l24#8.p" to "In welcher Reihenfolge wird der Schlafplatz eingerichtet?",
    "q.l24#8.o0" to "Untergrund einebnen, Steine und spitze Gegenstände entfernen",
    "q.l24#8.o1" to "Bodenplane und Schaummatte auslegen",
    "q.l24#8.o2" to "Luftmatte aufblasen und prüfen",
    "q.l24#8.o3" to "Schlafsack ausbreiten, Platz zum Umdrehen lassen",
    "q.l24#8.e" to "Eine falsche Reihenfolge kostet Nacharbeit: Ist der Untergrund nicht sauber, ist die Luftmatte in einer Nacht durchstochen.",

    "q.l24#9.p" to "Die Komforttemperatur des Schlafsacks sollte mindestens ______ °C unter der erwarteten Tiefsttemperatur liegen.",
    "q.l24#9.a0" to "5",
    "q.l24#9.e" to "5 °C Reserve sind die gängige Praxis. In der Höhe fühlt sich die Nacht kälter an; diese Reserve ist nicht üppig.",

    "q.l24#10.p" to "Ein nasser Daunenschlafsack isoliert fast nicht mehr und gehört deshalb in einen eigenen ______.",
    "q.l24#10.a0" to "wasserdichten Packsack",
    "q.l24#10.a1" to "wasserdichten Sack",
    "q.l24#10.a2" to "Drybag",
    "q.l24#10.e" to "Der eigene wasserdichte Packsack trennt die Schichten: Wird aussen alles nass, bleibt der Kern trocken.",

    "q.l24#11.p" to "Schlafausrüstung und ihre Hauptfunktion einander zuordnen.",
    "q.l24#11.l0" to "Geschlossenzellige Schaummatte",
    "q.l24#11.l1" to "Luftmatte",
    "q.l24#11.l2" to "Schlafsack-Inlett",
    "q.l24#11.l3" to "Ohrstöpsel",
    "q.l24#11.r0" to "Unterbricht die Bodenleitung und ist nicht durchstichanfällig",
    "q.l24#11.r1" to "Schafft eine ebene, bequeme Fläche und lässt sich zur Dämmung kombinieren",
    "q.l24#11.r2" to "Verringert Verschmutzung und Feuchtigkeit im Schlafsack",
    "q.l24#11.r3" to "Dämpft Lärm und erleichtert das Einschlafen",
    "q.l24#11.e" to "Vier Ausrüstungsteile lösen vier verschiedene Probleme: Leitung, Ebenheit, Feuchtigkeit, Lärm. Fehlt eines, kommt das Problem aus genau dieser Richtung zurück.",

    "q.l24#12.p" to "Im Zelt hat sich stark Reif gebildet. Wie ist am nächsten Morgen vorzugehen?",
    "q.l24#12.o0" to "Zuerst den Schlafsack in den Packsack, dann den Reif von der Zeltinnenwand abschütteln",
    "q.l24#12.o1" to "Zuerst das Zelt abbauen, den Schlafsack draussen liegen lassen",
    "q.l24#12.o2" to "Den Reif mit Körperwärme wegschmelzen",
    "q.l24#12.o3" to "Ignorieren, die Sonne erledigt das",
    "q.l24#12.e" to "Reif fällt bei jeder Berührung als Eis ab. Den Schlafsack zuerst zu verpacken ist der entscheidende Handgriff, damit nicht eine ganze Tour an zehn Minuten am Morgen scheitert.",

    "q.l24#13.p" to "Warum ist der Schlaf in grosser Höhe meist schlechter?",
    "q.l24#13.o0" to "Sauerstoffmangel führt zu periodischer Atmung, die einen immer wieder aus dem leichten Schlaf reisst",
    "q.l24#13.o1" to "Das Zelt ist zu hart",
    "q.l24#13.o2" to "Weil man tagsüber zu wenig läuft",
    "q.l24#13.o3" to "Weil die Zeit in der Höhe langsamer vergeht",
    "q.l24#13.e" to "Das ist physiologisch. Man kann nur die Bedingungen verbessern – Wärme, Ruhe, Flüssigkeit – nicht von sich verlangen, acht Stunden durchzuschlafen.",

    "q.l24#14.p" to "Die Gruppe hat nur ein Reservezelt. Wer bekommt es zuerst?",
    "q.l24#14.o0" to "Wer am ehesten unterkühlt oder bereits Zeichen der Höhenkrankheit zeigt",
    "q.l24#14.o1" to "Die Tourenleitung",
    "q.l24#14.o2" to "Wer die beste Kondition hat",
    "q.l24#14.o3" to "Das Los entscheidet",
    "q.l24#14.e" to "Reserven werden nach Risiko verteilt, nicht nach Rang oder Kondition. Das muss vor dem Abmarsch geklärt sein, damit es nachts keinen Streit gibt.",

    // ---------- m04 Wetter und Navigation: Grundlagen ----------
    "q.m04#10.p" to "Worauf kommt es beim Wetterbericht mehr an als auf die Niederschlagswahrscheinlichkeit?",
    "q.m04#10.o0" to "Windgeschwindigkeit, Temperatur und Niederschlagsart (Regen/Schnee) in Abhängigkeit von der Höhe",
    "q.m04#10.o1" to "Nur auf die Niederschlagswahrscheinlichkeit",
    "q.m04#10.o2" to "Nur auf die Höchsttemperatur",
    "q.m04#10.o3" to "Nur auf die Luftfeuchtigkeit",
    "q.m04#10.e" to "Bei gleicher Niederschlagsmenge macht es einen grossen Unterschied, ob Regen oder Schnee fällt. Der Wind bestimmt die gefühlte Temperatur und ob Bewegung überhaupt möglich ist, die Temperatur bestimmt die Ausrüstung.",

    "q.m04#11.p" to "Welches Wettermuster ist im Gebirge am Nachmittag typisch?",
    "q.m04#11.o0" to "Zunehmende Bewölkung, einsetzende Konvektion, steigende Wahrscheinlichkeit für Gewitter und Schauer",
    "q.m04#11.o1" to "Anhaltend klar",
    "q.m04#11.o2" to "Nachlassender Wind",
    "q.m04#11.o3" to "Die Temperatur fällt am schnellsten",
    "q.m04#11.e" to "Daher stammt die Regel «vormittags aufbrechen, nachmittags exponiertes Gelände verlassen». Die Tourenplanung folgt diesem Rhythmus.",

    "q.m04#12.p" to "Wie viel Grad pro 1.000 m setzt man beim Temperaturgradienten zur Schätzung der Schneegrenze an?",
    "q.m04#12.o0" to "6,5 °C",
    "q.m04#12.o1" to "2 °C",
    "q.m04#12.o2" to "10 °C",
    "q.m04#12.o3" to "15 °C",
    "q.m04#12.e" to "6,5 °C je 1.000 m ist der mittlere Gradient. Damit lässt sich die Nullgradgrenze grob berechnen und abschätzen, ob Regen oder Schnee fällt.",

    // ---------- m25 Höhenpsychologie und Entscheidungsroutinen ----------
    "q.m25#12.p" to "Was ist nach einem Rückzug am wichtigsten in der Nachbesprechung?",
    "q.m25#12.o0" to "Die damalige Entscheidungsgrundlage nachvollziehen: welche Informationen übersehen wurden, an welchem Punkt die Entscheidung früher möglich gewesen wäre",
    "q.m25#12.o1" to "Nur das Ergebnis festhalten",
    "q.m25#12.o2" to "Alles dem Glück zuschreiben",
    "q.m25#12.o3" to "Nicht mehr davon sprechen",
    "q.m25#12.e" to "Es geht nicht um Schuld, sondern darum, «beim nächsten Mal früher zu erkennen» in konkrete Erfahrung zu verwandeln. Eine Zeitleiste aufzuschreiben nützt mehr als das Aufschreiben von Gefühlen.",

    // ---------- m06 Einstieg ins technische Bergsteigen ----------
    "q.m06#10.p" to "Was bezeichnet die «Selbstsicherung» unter den drei Systemen des technischen Bergsteigens?",
    "q.m06#10.o0" to "Mit Ankerpunkten und Seil einen Sturz auffangen",
    "q.m06#10.o1" to "Das Gehen",
    "q.m06#10.o2" to "Die Kletterbewegung",
    "q.m06#10.o3" to "Der Einkauf von Ausrüstung",
    "q.m06#10.e" to "Bewegung, Selbstsicherung und Partnersicherung (Belay) bilden einen Kreislauf: gehen können, sich selbst sichern können, andere sichern können. Fehlt eines von drei, beherrscht man das technische Bergsteigen nicht.",

    "q.m06#11.p" to "Warum folgt der technische Kurs meist der Reihenfolge «erst Bremsen, dann Klettern»?",
    "q.m06#11.o0" to "Weil der Rutschsturz die häufigste Gefahr ist und die Bremstechnik die Grundabsicherung",
    "q.m06#11.o1" to "Weil Klettern schwieriger ist",
    "q.m06#11.o2" to "Wegen der Reihenfolge der Ausrüstung",
    "q.m06#11.o3" to "Weil es in den Lehrbüchern so steht",
    "q.m06#11.e" to "Klettern zu können, aber nicht stoppen zu können, vergrössert das Risiko. Bremstechnik, Seilschaft und Sicherung – Fertigkeiten, die man im Normalfall nie braucht – müssen zuerst sitzen.",

    "q.m06#12.p" to "Welchen Wert hat wiederholtes Üben von Abläufen in sicherem Gelände?",
    "q.m06#12.o0" to "Die Bewegung wird zum Reflex, der kein Nachdenken braucht – erst dann bleibt im Ernstfall Aufmerksamkeit für die Entscheidung",
    "q.m06#12.o1" to "Um Zeit zu verbringen",
    "q.m06#12.o2" to "Um Fotos zu machen",
    "q.m06#12.o3" to "Um die Ausrüstungspreise zu kennen",
    "q.m06#12.e" to "Im Ernstfall sind Aufmerksamkeit und Urteilsvermögen durch Wetter, Erschöpfung und Angst belegt. Nur was automatisch läuft, gelingt im entscheidenden Moment.",
    // ---------- l25 Vorbereitung: Genehmigungen, Versicherung, Logistik ----------
    "q.l25#0.p" to "Was wird bei der Bergsteigergenehmigung am häufigsten unterschätzt?",
    "q.l25#0.o0" to "Der Vorlauf und die Zusatzauflagen (Bergführer, Kontaktperson, ärztliches Attest)",
    "q.l25#0.o1" to "Die Gebühren",
    "q.l25#0.o2" to "Das Format der Passfotos",
    "q.l25#0.o3" to "Die Öffnungszeiten der Ausgabestelle",
    "q.l25#0.e" to "Viele Routen verlangen eine Antragsfrist von mehreren Wochen und binden einen lokalen Führer oder eine Kontaktperson ein. Wer erst am Fusse des Berges beantragt, muss meist die Route ändern.",

    "q.l25#1.p" to "Welche zwei Punkte sind bei der Wahl der Versicherung am wichtigsten?",
    "q.l25#1.o0" to "Ob technisches Bergsteigen gedeckt ist und ob Hubschrauberrettung in grosser Höhe gedeckt ist",
    "q.l25#1.o1" to "Ob Flugverspätungen eingeschlossen sind",
    "q.l25#1.o2" to "Ob man kündigen kann",
    "q.l25#1.o3" to "Die Höhe der Prämie",
    "q.l25#1.e" to "Übliche Reiseversicherungen führen «technisches Bergsteigen» und «grosse Höhe» als Ausschluss. Erst im Schadensfall zu merken, dass nicht gezahlt wird, ist der häufigste zweite Schaden solcher Unfälle.",

    "q.l25#2.p" to "Für welche Teile der Logistikplanung ist eine Alternative zwingend?",
    "q.l25#2.o0" to "Transport, Lastentransport und Lagerversorgung – Abschnitt für Abschnitt",
    "q.l25#2.o1" to "Nur der Transport",
    "q.l25#2.o2" to "Nur die Unterkunft",
    "q.l25#2.o3" to "Alternativen sind nicht nötig",
    "q.l25#2.e" to "Im Gebirge sind Verzögerungen normal: Strasse unterbrochen, Flug gestrichen, Träger wechseln kurzfristig. Mit einer Alternative pro Abschnitt bringt ein einzelner Engpass nicht die ganze Kette zu Fall.",

    "q.l25#3.p" to "Was muss ein Tourenplan für die Kontaktperson daheim mindestens enthalten?",
    "q.l25#3.o0" to "Route, Zeiten der Kontrollpunkte, ab wann ohne Meldung der Notfallplan greift, und wie Alarm ausgelöst wird",
    "q.l25#3.o1" to "Nur den Bergnamen",
    "q.l25#3.o2" to "Nur die Namen der Mitgehenden",
    "q.l25#3.o3" to "Nur das Budget",
    "q.l25#3.e" to "Der Tourenplan soll anderen ermöglichen zu beurteilen, ob sie sich Sorgen machen müssen. Zeiten und Notfallplan sind der Kern, die Route die Voraussetzung.",

    "q.l25#4.p" to "Warum wird eine Budgetreserve von 20 % empfohlen?",
    "q.l25#4.o0" to "Weil Verzögerungen, zusätzliche Übernachtungen und kurzfristig engagierte Träger eintreten",
    "q.l25#4.o1" to "Für Souvenirs",
    "q.l25#4.o2" to "Für Trinkgelder",
    "q.l25#4.o3" to "Weil sich der Wechselkurs ändert",
    "q.l25#4.e" to "Diese Ausgaben sind nicht der Ausnahmefall, sondern die Regel. Die Reserve dient nicht dem Sparen, sondern soll verhindern, dass am Berg aus Geldgründen schlechte Entscheidungen fallen.",

    "q.l25#5.p" to "Welche Unterlagen werden für einen Gipfelnachweis üblicherweise verlangt?",
    "q.l25#5.o0" to "Gipfelfoto oder Video, Erklärungsformular, Genehmigung und Ausweisdokumente",
    "q.l25#5.o1" to "Nur ein Foto",
    "q.l25#5.o2" to "Nur die Unterschrift der Mitgehenden",
    "q.l25#5.o3" to "Keine Unterlagen",
    "q.l25#5.e" to "Die Anforderungen unterscheiden sich je nach Berg, doch Fotos, Erklärungsformular und Genehmigung werden fast immer gebraucht. Das vor dem Start zu klären ist viel einfacher, als es nach der Rückkehr nachzureichen.",

    "q.l25#6.p" to "Was muss vor dem Start für alle Teilnehmenden verbindlich geklärt werden?",
    "q.l25#6.o0" to "Treffpunkt und Zeit für Start und Rückzug",
    "q.l25#6.o1" to "Funkkanal und Rufregeln",
    "q.l25#6.o2" to "Medizinische Angaben und Unverträglichkeiten",
    "q.l25#6.o3" to "Die tägliche Essensverteilung pro Person",
    "q.l25#6.e" to "Die ersten beiden Punkte betreffen Trennung und Rettung, der dritte ist im Notfall entscheidend; die Essensverteilung ist ein Logistikdetail, das die Tourenleitung regelt, ohne dass die ganze Gruppe darüber diskutieren muss.",

    "q.l25#7.p" to "Bei welchen Unterlagen führt das Fehlen zur Verweigerung des Zutritts?",
    "q.l25#7.o0" to "Schutzgebiets- oder Bergsteigergenehmigung",
    "q.l25#7.o1" to "Identitätsnachweis",
    "q.l25#7.o2" to "Versicherungsschein (auf manchen Routen verlangt)",
    "q.l25#7.o3" to "Gipfelzertifikat",
    "q.l25#7.e" to "Das Gipfelzertifikat gibt es erst nach der Rückkehr und taugt nicht als Zugangsdokument. Die ersten beiden werden fast immer geprüft, der dritte je nach Route.",

    "q.l25#8.p" to "Welche Abfolge ist sinnvoll, von der Entscheidung für einen Berg bis zum Start?",
    "q.l25#8.o0" to "Route und Zeitfenster festlegen",
    "q.l25#8.o1" to "Genehmigung beantragen, Transport und Lastentransport buchen",
    "q.l25#8.o2" to "Passende Versicherung abschliessen, Ausschlussklauseln prüfen",
    "q.l25#8.o3" to "Dokumentenmappe zusammenstellen und Tourenplan bei der Kontaktperson hinterlegen",
    "q.l25#8.e" to "Erst mit der Route lässt sich die Genehmigung beantragen; sind Genehmigung und Transport fix, weiss man, für welche Tage und Tätigkeiten die Versicherung gelten muss; zuletzt die Dokumentenablage.",

    "q.l25#9.p" to "Bei verspätetem Gepäck oder wenn es nicht mitfliegt, muss ______ ins Handgepäck (welche Ausrüstung).",
    "q.l25#9.a0" to "Bergschuhe",
    "q.l25#9.a1" to "Hochgebirgsschuhe",
    "q.l25#9.a2" to "Schuhe",
    "q.l25#9.a3" to "persönliche technische Ausrüstung",
    "q.l25#9.e" to "Schuhe und persönliche technische Ausrüstung lassen sich unterwegs praktisch nicht ersetzen. Viele Teams verlangen, dass beides ins Handgepäck geht und nicht aufgegeben wird.",

    "q.l25#10.p" to "Als Budgetreserve werden üblicherweise ______ % empfohlen.",
    "q.l25#10.a0" to "20",
    "q.l25#10.e" to "20 % ist der Erfahrungswert. Zusatzausgaben im Gebirge ballen sich meist bei Verzögerung und Personal.",

    "q.l25#11.p" to "Dokument und Verwendungszweck einander zuordnen.",
    "q.l25#11.l0" to "Bergsteigergenehmigung",
    "q.l25#11.l1" to "Versicherungsschein und Rettungsnummer",
    "q.l25#11.l2" to "Gipfelerklärungsformular",
    "q.l25#11.l3" to "Tourenplan",
    "q.l25#11.r0" to "Zugangsnachweis, wird an Kontrollposten geprüft",
    "q.l25#11.r1" to "Grundlage für Rettungskontakt und Schadensabwicklung",
    "q.l25#11.r2" to "Wird für den Gipfelnachweis eingereicht",
    "q.l25#11.r3" to "Bleibt bei der Kontaktperson und dient der Entscheidung, wann Alarm ausgelöst wird",
    "q.l25#11.e" to "Vier Dokumente für vier Situationen: Zutritt, Notfall, Nachweis, fehlende Meldung. Fehlt eines, stockt die passende Situation.",

    "q.l25#12.p" to "Was folgt am wahrscheinlichsten daraus, dass vor dem Start nicht geklärt wurde, wer «Stopp» sagen darf?",
    "q.l25#12.o0" to "Niemand traut sich zu sprechen, wenn gestoppt werden müsste – das gemeinsame Schweigen vergrössert das Risiko",
    "q.l25#12.o1" to "Die Gruppe wird schneller",
    "q.l25#12.o2" to "Die Ausrüstung wird leichter",
    "q.l25#12.o3" to "Es hat keine Auswirkung",
    "q.l25#12.e" to "«Stopp» wird zu einer vorab erteilten Befugnis statt zu einer Prüfung persönlichen Muts. Das vor dem Start zu klären nützt weit mehr als eine Diskussion am Berg.",

    "q.l25#13.p" to "Die Genehmigung verlangt einen lokalen Bergführer, doch in der Gruppe gibt es Widerstand. Wie ist vorzugehen?",
    "q.l25#13.o0" to "Die Vorschrift einhalten und den Führer in Budget und Planung aufnehmen",
    "q.l25#13.o1" to "Den Kontrollposten umgehen",
    "q.l25#13.o2" to "Den Führer nur auf dem Papier führen",
    "q.l25#13.o3" to "Auf eine Route ausweichen, die keinen verlangt, und neu bewerten",
    "q.l25#13.e" to "Die Genehmigung zu umgehen ist nicht nur illegal, es setzt auch Rettung und Versicherungsschutz ausser Kraft. Entweder regelkonform oder andere Route – auf Glück zu setzen geht nicht.",

    "q.l25#14.p" to "Warum werden medizinische Angaben und Medikamentenpläne schon vor dem Start erhoben?",
    "q.l25#14.o0" to "Im Notfall müssen Gegenanzeigen und Vorerkrankungen bekannt sein; grosse Höhe verstärkt das Risiko bei Grunderkrankungen",
    "q.l25#14.o1" to "Um Rabatt auf die Versicherung zu bekommen",
    "q.l25#14.o2" to "Um Gruppen einzuteilen",
    "q.l25#14.o3" to "Es hat keinen praktischen Nutzen",
    "q.l25#14.e" to "Über 5.000 m kann eine gewöhnliche Infektion oder eine Medikamentenallergie zum Notfall werden. Die Angaben gehören vor den Start, nicht in die Befragung nach dem Vorfall.",

    // ---------- l22 Technische Ausrüstung, Navigation, Kommunikation ----------
    "q.l22#10.p" to "Worin liegt der wesentliche Unterschied zwischen Doppelseil (Halbseil) und Einfachseil?",
    "q.l22#10.o0" to "Beim Doppelseil wird abwechselnd in verschiedene Sicherungspunkte eingehängt; das senkt Seilreibung und Fangstoss, ist aber aufwendiger in der Handhabung",
    "q.l22#10.o1" to "Doppelseile sind billiger",
    "q.l22#10.o2" to "Doppelseile sind leichter",
    "q.l22#10.o3" to "Es gibt keinen Unterschied",
    "q.l22#10.e" to "Doppelseile passen zu gewundenen Routen, in denen die Seilreibung klein bleiben muss; das Einfachseil ist einfacher und direkter. Die Wahl richtet sich nach der Routenform, nicht danach, was professioneller wirkt.",

    "q.l22#11.p" to "Was ist mit einem Helm nach einem deutlichen Aufprall zu tun?",
    "q.l22#11.o0" to "Ausmustern und ersetzen, auch wenn er äusserlich unbeschädigt aussieht",
    "q.l22#11.o1" to "Weiterverwenden",
    "q.l22#11.o2" to "Mit Kleber reparieren",
    "q.l22#11.o3" to "Nur das Innenfutter tauschen",
    "q.l22#11.e" to "Der Helm dämpft über den Schaum; nach einem Aufprall ist die innere Struktur geschädigt, ohne dass man es sieht. Bei einem zweiten Aufprall sinkt die Schutzwirkung deutlich.",

    "q.l22#12.p" to "Was ist bei der Nutzung von Funkgeräten in der Gruppe am wichtigsten?",
    "q.l22#12.o0" to "Fester Kanal und feste Rufregeln, kurze Positionsmeldungen, kein Geplauder auf dem Kanal",
    "q.l22#12.o1" to "Lautstärke auf Maximum",
    "q.l22#12.o2" to "Ständig in Verbindung bleiben",
    "q.l22#12.o3" to "Nur die Tourenleitung trägt eines",
    "q.l22#12.e" to "Der Kanal ist eine gemeinsame Ressource. Langes Plaudern blockiert den wirklich dringenden Notruf und leert schnell den Akku.",

    "q.l22#13.p" to "Worin unterscheiden sich Satellitenkommunikationsgeräte (etwa inReach) und PLB?",
    "q.l22#13.o0" to "Satellitengeräte erlauben Wechselkommunikation, ein PLB sendet nur in eine Richtung und ist ausschliesslich für Notfälle gedacht",
    "q.l22#13.o1" to "Ein PLB kann SMS senden",
    "q.l22#13.o2" to "Beide sind völlig gleich",
    "q.l22#13.o3" to "Satellitengeräte brauchen keinen Strom",
    "q.l22#13.e" to "Ein registriertes PLB wird von Rettungsstellen beantwortet; ein Fehlalarm ist teuer. Satellitengeräte eignen sich für regelmässige Lebenszeichen und Absprachen. Die beiden haben unterschiedliche Aufgaben.",

    "q.l22#14.p" to "Bei Kälte bricht die Akkulaufzeit ein. Was ist die praktischste Gegenmassnahme?",
    "q.l22#14.o0" to "Ersatzakkus am Körper tragen und Geräte bei Nichtgebrauch in die Innentasche stecken",
    "q.l22#14.o1" to "Mehrere Akkus aussen am Rucksack mitführen",
    "q.l22#14.o2" to "Alle Funktionen abschalten",
    "q.l22#14.o3" to "Mit einer Wärmflasche heizen",
    "q.l22#14.e" to "Lithium-Ionen-Akkus können bei -20 °C nur noch die Hälfte der Kapazität liefern. Wärmen wirkt besser als mehr mitzunehmen, weil auch Ersatzakkus an Leistung verlieren.",

    "q.l22#15.p" to "Wie geht man vor dem Start richtig mit Offline-Karten um?",
    "q.l22#15.o0" to "Das Offline-Paket der gesamten Route herunterladen und zu Hause einmal im Flugmodus die Positionsanzeige testen",
    "q.l22#15.o1" to "Nur Screenshots der Route machen",
    "q.l22#15.o2" to "Auf die Online-Karte in Echtzeit vertrauen",
    "q.l22#15.o3" to "Eine kleine Karte ausdrucken",
    "q.l22#15.e" to "«Heruntergeladen» und «offline nutzbar» sind zwei verschiedene Dinge. Ein Test zu Hause zeigt fehlende Kacheln oder Berechtigungsprobleme rechtzeitig.",

    // ---------- m05 Zielberg: einfache Hochtour ----------
    "q.m05#10.p" to "Warum ist das Saisonfenster bei einem einfachen Schneeberg wichtig?",
    "q.m05#10.o0" to "Schneelage, Windverhältnisse und Genehmigungspraxis unterscheiden sich je nach Jahreszeit stark; ausserhalb des Fensters verdoppelt sich der Schwierigkeitsgrad",
    "q.m05#10.o1" to "Wegen der Ticketpreise",
    "q.m05#10.o2" to "Weil es voll wird",
    "q.m05#10.o3" to "Wegen der Sonneneinstrahlung",
    "q.m05#10.e" to "Derselbe Berg ist vor und nach dem Monsun zwei verschiedene Aufgaben. Erst die Saison wählen, dann die Route.",

    "q.m05#11.p" to "Was bedeutet «technische Handhabung erforderlich» bei der Wahl eines Einstiegsbergs?",
    "q.m05#11.o0" to "Ob Seilschaft, Sicherung, Gletscherspaltenbegehung und ähnliche Techniken nötig sind",
    "q.m05#11.o1" to "Ob Eintritt zu zahlen ist",
    "q.m05#11.o2" to "Ob ein Bergführer nötig ist",
    "q.m05#11.o3" to "Ob ein Zelt nötig ist",
    "q.m05#11.e" to "Genau hier liegt der Kernunterschied zwischen Wanderberg und technischem Berg. Für die erste Hochtour wählt man am besten eine Route ohne technische Handhabung.",

    "q.m05#12.p" to "Wie ist eine Gipfelquote richtig zu verstehen?",
    "q.m05#12.o0" to "Sie spiegelt Wetterfenster und Routenschwierigkeit, doch die Erhebungsgrundlage unterscheidet sich stark zwischen den Jahren",
    "q.m05#12.o1" to "Je höher, desto besser",
    "q.m05#12.o2" to "Je niedriger, desto sicherer",
    "q.m05#12.o3" to "Sie hat keinen Aussagewert",
    "q.m05#12.e" to "Die Gipfelquote ist eine Information, keine Garantie. Beim Lesen auf Jahr, Saison und darauf achten, ob Unterstützung durch kommerzielle Teams enthalten ist.",

    // ---------- l5 Steigeisentechnik: französisch / deutsch / gemischt ----------
    "q.l5#10.p" to "Unter dem Steigeisen bildet sich Schnee zu Klumpen (Balling). Was hilft am wirksamsten?",
    "q.l5#10.o0" to "Mit der Pickelspitze abklopfen und Antischneewachs auftragen oder Steigeisen mit Antistollplatte verwenden",
    "q.l5#10.o1" to "Weitergehen, durch die Bewegung taut es weg",
    "q.l5#10.o2" to "Gegen einen Baum treten",
    "q.l5#10.o3" to "Die Steigeisen abnehmen",
    "q.l5#10.e" to "Schneeklumpen nehmen den Zacken den Griff – das ist wie barfuss auf einer Eisflanke. Die Behandlung muss sofort erfolgen, nicht erst auf dem nächsten Absatz.",

    "q.l5#11.p" to "Wie bleibt der Fussknöchel beim Eintreten mit den Frontzacken?",
    "q.l5#11.o0" to "Entspannt, damit die Zacken senkrecht ins Eis eindringen; nicht verkrampft nach unten drücken",
    "q.l5#11.o1" to "Verkrampft",
    "q.l5#11.o2" to "Zehen nach oben gezogen",
    "q.l5#11.o3" to "Zuerst die Ferse aufsetzen",
    "q.l5#11.e" to "Verkrampfung ermüdet die Wade früh und lässt die Zacken schräg eindringen. Mit entspanntem Knöchel beissen die Zacken senkrecht.",

    "q.l5#12.p" to "Warum ist die französische Flachfusstechnik auf Hart- oder Blaufeis unzuverlässig?",
    "q.l5#12.o0" to "Die flach aufgesetzten Zacken dringen nicht ins harte Eis ein, das Eisen rutscht als Ganzes ab",
    "q.l5#12.o1" to "Weil sie zu langsam ist",
    "q.l5#12.o2" to "Weil sie zu anstrengend ist",
    "q.l5#12.o3" to "Weil die Haltung unschön aussieht",
    "q.l5#12.e" to "Die französische Technik lebt davon, dass die ganze Zackenreihe auf Schnee drückt. Hartes Eis bietet keine nachgebende Schneeschicht; dort muss auf Frontzackentechnik gewechselt werden.",

    "q.l5#13.p" to "Worin liegt der Vorteil der französischen Technik auf weichen Schneehängen?",
    "q.l5#13.o0" to "Kraftsparend und schnell, geeignet für lange mässig steile Hänge",
    "q.l5#13.o1" to "Sicherer",
    "q.l5#13.o2" to "Besser für hartes Eis",
    "q.l5#13.o3" to "Man braucht keinen Pickel",
    "q.l5#13.e" to "Weicher Schnee bietet ausreichend Auflagefläche; mit flachem Fuss zu gehen kostet deutlich weniger Kraft als wiederholtes Eintreten der Frontzacken. Die Technikwahl folgt der Schneebeschaffenheit.",

    "q.l5#14.p" to "Wie sieht die richtige Haltung bei der französischen Technik im Abstieg aus?",
    "q.l5#14.o0" to "Zehen nach unten, zuerst die Ferse aufsetzen, dann die ganze Sohle in den Schnee drücken",
    "q.l5#14.o1" to "Zehen nach oben",
    "q.l5#14.o2" to "Seitlich queren",
    "q.l5#14.o3" to "Nur die Frontzacken",
    "q.l5#14.e" to "Beim Abstieg kommt es darauf an, die ganze Zackenreihe im Schnee zu halten und den Schwerpunkt über dem Fuss zu behalten. Die zuerst aufgesetzte Ferse tritt die Stufe.",

    "q.l5#15.p" to "Was macht der bergseitige Fuss beim Queren?",
    "q.l5#15.o0" to "Mit den Innenzacken in den Hang beissen, den Knöchel hangwärts kippen",
    "q.l5#15.o1" to "Flach aufsetzen",
    "q.l5#15.o2" to "Zehen nach unten",
    "q.l5#15.o3" to "Vom Boden abheben",
    "q.l5#15.e" to "Beim Queren müssen beide Füsse im Hang beissen, damit ein stabiler Stand entsteht. Ein steifer Knöchel lässt die Zacken nur über die Oberfläche streifen.",

    // ---------- l6 Pickeltechnik und Selbstbremsung ----------
    "q.l6#10.p" to "Wo liegt der Pickelschaft beim Selbstbremsen am Körper?",
    "q.l6#10.o0" to "Zwischen Schulter und Brust, das Körpergewicht drückt auf den Pickelkopf",
    "q.l6#10.o1" to "An der Hüfte",
    "q.l6#10.o2" to "Über dem Kopf",
    "q.l6#10.o3" to "Seitlich am Bein",
    "q.l6#10.e" to "Je weiter oben der Druck liegt, desto besser wird Körpergewicht in Bremskraft umgesetzt. An der Hüfte hebt sich die Pickelspitze an, und die Bremswirkung ist praktisch null.",

    "q.l6#11.p" to "Was bezeichnet der Selbstbremsgriff (self-arrest grip)?",
    "q.l6#11.o0" to "Der Daumen liegt auf einer Seite des Pickelkopfes, die Handfläche darüber – jederzeit in die Bremsposition drehbar",
    "q.l6#11.o1" to "Beide Hände am Ende des Schafts",
    "q.l6#11.o2" to "Den Pickel einhändig baumeln lassen",
    "q.l6#11.o3" to "Die Hand in der Handschlaufe",
    "q.l6#11.e" to "Dieser Griff erlaubt es, im Moment des Ausrutschens ohne Umgreifen zu bremsen. Die halbe Sekunde fürs Umgreifen ist oft genau die Strecke, die man abrutscht.",

    "q.l6#12.p" to "Wie wirkt sich die Schneebeschaffenheit auf die Bremswirkung aus?",
    "q.l6#12.o0" to "Weicher Schnee bremst leicht, harter Schnee und Eisfläche lassen praktisch keine Bremsung zu",
    "q.l6#12.o1" to "Je härter, desto besser die Bremsung",
    "q.l6#12.o2" to "Unabhängig von der Schneebeschaffenheit",
    "q.l6#12.o3" to "Nasser Schnee ist am glattesten",
    "q.l6#12.e" to "Bremsen funktioniert über das Eindringen der Pickelspitze. Auf hartem Schnee entsteht nur eine flache Furche, auf Eis gar nichts – deshalb sichert man Eishänge mit Fixseil, nicht mit der Bremstechnik.",

    "q.l6#13.p" to "Was ist das Hauptrisiko eines Sturzes mit Handschlaufe (Leash)?",
    "q.l6#13.o0" to "Wird der Pickel mitgerissen, verdreht sich das Handgelenk oder man wird aus dem Gleichgewicht gezogen",
    "q.l6#13.o1" to "Die Handschlaufe reisst",
    "q.l6#13.o2" to "Der Pickel geht verloren",
    "q.l6#13.o3" to "Es sieht schlecht aus",
    "q.l6#13.e" to "Im Sturz kann die Handschlaufe zum Haken werden und das Handgelenk in eine ungünstige Stellung ziehen. In technischem Gelände ersetzt man sie meist durch eine Fangschlinge.",

    "q.l6#14.p" to "Was ist nach erfolgreicher Bremsung und Stillstand zuerst zu tun?",
    "q.l6#14.o0" to "Position und Sicherheit von sich selbst und den Mitgehenden prüfen, dann Verletzungen und Ausrüstung kontrollieren",
    "q.l6#14.o1" to "Sofort aufstehen",
    "q.l6#14.o2" to "Weiter absteigen",
    "q.l6#14.o3" to "Zuerst den Pickel holen",
    "q.l6#14.e" to "Anhalten ist nicht gleich Sicherheit: Man kann noch im Hang hängen, und andere können mitgerissen worden sein. Erst beurteilen, dann handeln.",

    "q.l6#15.p" to "Warum ist «mit der Pickelspitze auf das Eis schlagen» keine wirksame Bremsbewegung?",
    "q.l6#15.o0" to "Bremsen braucht anhaltenden Druck, keinen Einzelschlag – ein Schlag lässt den Pickel abprallen",
    "q.l6#15.o1" to "Weil es zu laut ist",
    "q.l6#15.o2" to "Weil der Pickel kaputtgeht",
    "q.l6#15.o3" to "Weil das Eis zu hart ist",
    "q.l6#15.e" to "Bremsen ist ein Vorgang aus Anpressen und Gleiten mit Abbremsen. Ein einzelner Schlag spritzt nur Splitter heraus, der Körper rutscht weiter.",
    // ---------- l7 Rutschsturz: Reaktion und Selbstbremsung ----------
    "q.l7#10.p" to "Was ist im Moment des Ausrutschens zuerst zu schützen?",
    "q.l7#10.o0" to "Der Kopf – gleichzeitig den Körper in eine bremsfähige Lage bringen (Bauch- oder Rückenlage)",
    "q.l7#10.o1" to "Der Rucksack",
    "q.l7#10.o2" to "Der Pickel",
    "q.l7#10.o3" to "Das Handy",
    "q.l7#10.e" to "Kopfverletzungen sind eine der häufigsten Todesursachen beim Rutschsturz. Drehen, Kopf schützen und Pickel aufsetzen müssen gleichzeitig beginnen.",

    "q.l7#11.p" to "Wie lautet der Standardruf, wenn Steinschlag oder ein Sturz zu sehen ist?",
    "q.l7#11.o0" to "Laut «Steinschlag!» oder «Sturz!» rufen, kurz und wiederholt",
    "q.l7#11.o1" to "Ruhig beobachten",
    "q.l7#11.o2" to "Nur winken",
    "q.l7#11.o3" to "Pfeifen",
    "q.l7#11.e" to "Der Ruf soll die Leute unterhalb dazu bringen, sofort aufzuschauen und auszuweichen. Der Ton ist wichtiger als die Erklärung; kurz und wiederholt wirkt besser als ausführlich.",

    "q.l7#12.p" to "Eine Person rutscht in der Seilschaft. Was tun die anderen?",
    "q.l7#12.o0" to "Sofort bremsen und die Seilspannung halten, nicht gleichzeitig in Bewegung kommen",
    "q.l7#12.o1" to "Gemeinsam hinlaufen",
    "q.l7#12.o2" to "Das Seil loslassen",
    "q.l7#12.o3" to "Sich hinsetzen",
    "q.l7#12.e" to "Bewegt sich alles gleichzeitig, verliert das Seil die Spannung und die stürzende Person rutscht weiter. Der erste Schritt der Bremsung ist, selbst festen Stand zu bekommen.",

    "q.l7#13.p" to "Der Sturz ist gestoppt, das Seil bleibt gespannt. Wie weiter?",
    "q.l7#13.o0" to "Spannung halten, zuerst eine Sicherung aufbauen, dann zur betroffenen Person vorgehen",
    "q.l7#13.o1" to "Sofort Seil nachgeben",
    "q.l7#13.o2" to "Die Person soll selbst hochklettern",
    "q.l7#13.o3" to "Das Seil durchschneiden",
    "q.l7#13.e" to "Seil nachgeben kann einen erneuten Sturz auslösen. Erst sich selbst fixieren, dann ist an Rettung zu denken.",

    "q.l7#14.p" to "Warum können Steigeisen beim Rutschsturz zur Gefahr werden?",
    "q.l7#14.o0" to "Die Zacken haken sich in Schnee oder Kleidung, was zu Verdrehungen oder einem abrupten Stopp führt",
    "q.l7#14.o1" to "Weil sie zu schwer sind",
    "q.l7#14.o2" to "Weil sie sich lösen",
    "q.l7#14.o3" to "Weil sie verschleissen",
    "q.l7#14.e" to "Hakt ein Fuss plötzlich ein, dreht sich der Körper um das Gelenk. Deshalb ist die Haltung «Füsse voraus, Knie gebeugt» so wichtig.",

    "q.l7#15.p" to "Beim Abstieg passieren besonders viele Unfälle. Was ist die Hauptursache?",
    "q.l7#15.o0" to "Erschöpfung, nachlassende Aufmerksamkeit und die innere Entspannung «es ist geschafft»",
    "q.l7#15.o1" to "Die Dunkelheit",
    "q.l7#15.o2" to "Verschlissene Ausrüstung",
    "q.l7#15.o3" to "Eine schwierigere Route",
    "q.l7#15.e" to "Im Abstieg ist das Gelände oft exponierter, während die Wachsamkeit am niedrigsten ist. Den Abstieg als zweite Hälfte der Tour zu planen ist keine Formalie.",

    // ---------- l8 Abstieg am Schneehang und Glissade ----------
    "q.l8#10.p" to "Welche Haltung empfiehlt sich beim Abstieg über einen steileren Hartschneehang?",
    "q.l8#10.o0" to "Dem Hang zugewandt, mit drei Kontaktpunkten schrittweise absteigen",
    "q.l8#10.o1" to "Mit dem Gesicht nach aussen schnell abwärts gehen",
    "q.l8#10.o2" to "Kontrolliert abrutschen (Glissade)",
    "q.l8#10.o3" to "Hinunterspringen",
    "q.l8#10.e" to "Mit dem Gesicht zum Hang kann jederzeit mit dem Pickel gebremst werden. Gesicht nach aussen taugt nur bei flachen Hängen oder weichem Schnee.",

    "q.l8#11.p" to "Wie wird die Bremsbereitschaft bei der kontrollierten Glissade hergestellt?",
    "q.l8#11.o0" to "Der Pickel bleibt in einer Position, aus der jederzeit aufgesetzt und gebremst werden kann",
    "q.l8#11.o1" to "Den Pickel in den Rucksack packen",
    "q.l8#11.o2" to "Beide Hände öffnen",
    "q.l8#11.o3" to "Die Augen schliessen",
    "q.l8#11.e" to "Der Spass der Glissade beruht darauf, jederzeit anhalten zu können. Falsche Haltung oder zu harter Schnee machen aus der Glissade direkt einen Rutschsturz.",

    "q.l8#12.p" to "Welche Kontrolle muss vor dem Abseilen abgeschlossen sein?",
    "q.l8#12.o0" to "Ankerpunkt, Knoten, Seilende, Einfädelrichtung des Abseilgeräts und die Rückfallsicherung",
    "q.l8#12.o1" to "Nur der Ankerpunkt",
    "q.l8#12.o2" to "Nur die Seillänge",
    "q.l8#12.o3" to "Nur die Mitgehenden",
    "q.l8#12.e" to "Abseilunfälle gehen fast immer auf einen dieser fünf Punkte zurück. Die Reihe laut Punkt für Punkt durchzugehen ist verlässlicher als «ich denke, es passt».",

    "q.l8#13.p" to "Wo trifft Steinschlag beim Abseilen am ehesten?",
    "q.l8#13.o0" to "Direkt unter dem Seil",
    "q.l8#13.o1" to "Drei Meter seitlich versetzt",
    "q.l8#13.o2" to "Neben dem Ankerpunkt",
    "q.l8#13.o3" to "Hinter dem Absatz",
    "q.l8#13.e" to "Direkt darunter verläuft die Falllinie des Steinschlags. Beim Abseilen möglichst seitlich versetzt bleiben und die Kante zügig passieren.",

    "q.l8#14.p" to "Was ist die häufigste Ursache, wenn das Seil nach dem Doppelseilabseilen nicht abgezogen werden kann?",
    "q.l8#14.o0" to "Verknotete Seilenden, ein Knoten in einer Felsspalte oder ungleiche Seillängen",
    "q.l8#14.o1" to "Das Seil ist zu alt",
    "q.l8#14.o2" to "Das Abseilgerät ist zu klein",
    "q.l8#14.o3" to "Der Ankerpunkt sitzt zu hoch",
    "q.l8#14.e" to "Vor dem Abziehen prüfen, ob die Seilenden frei sind, nichts eingehängt ist und beide Stränge gleich lang sind. Klemmt es, zuerst den Winkel ändern statt zu ziehen.",

    "q.l8#15.p" to "Wozu dient der Stopfknoten am Seilende beim Abseilen?",
    "q.l8#15.o0" to "Er verhindert, dass das Seilende aus dem Abseilgerät rutscht und man unkontrolliert stürzt",
    "q.l8#15.o1" to "Erleichtert das Aufnehmen des Seils",
    "q.l8#15.o2" to "Markiert die Länge",
    "q.l8#15.o3" to "Verringert den Verschleiss",
    "q.l8#15.e" to "Reicht die Seillänge nicht, bedeutet ein durchgerutschtes Seilende den sofortigen Verlust der Bremsung. Der Knoten kostet fast nichts und ist trotzdem in vielen Unfällen die entscheidende Trennlinie.",

    // ---------- l9 Grundknoten ----------
    "q.l9#10.p" to "Was ist der Vorteil des Achterknotens gegenüber dem Überhandknoten?",
    "q.l9#10.o0" to "Er lässt sich nach Belastung verhältnismässig leicht lösen und ist strukturell klar zu prüfen",
    "q.l9#10.o1" to "Er ist kleiner",
    "q.l9#10.o2" to "Er braucht weniger Seil",
    "q.l9#10.o3" to "Er braucht keine Sicherung am Ende",
    "q.l9#10.e" to "Der Überhandknoten frisst sich unter Last fest und lässt sich im Gelände kaum lösen. Der Achterknoten bleibt nach Belastung zerlegbar – deshalb ist er der Standard-Verbindungsknoten.",

    "q.l9#11.p" to "Wo wird ein Stopfknoten üblicherweise gesetzt?",
    "q.l9#11.o0" to "Am Seilende, damit das Seil nicht aus dem Gerät rutscht",
    "q.l9#11.o1" to "In der Seilmitte",
    "q.l9#11.o2" to "Am Ankerpunkt",
    "q.l9#11.o3" to "Am Gurtring",
    "q.l9#11.e" to "Beim Abseilen, Ablassen und Nachsteigen kann das Seilende durchrutschen. Der Stopfknoten ist die letzte mechanische Sicherung.",

    "q.l9#12.p" to "Wofür wird der doppelte Spierenstich vor allem verwendet?",
    "q.l9#12.o0" to "Zum Verbinden zweier Seile mit ähnlichem Durchmesser",
    "q.l9#12.o1" to "Zum Verbinden von Seil und Klettergurt",
    "q.l9#12.o2" to "Als Klemmknoten",
    "q.l9#12.o3" to "Zum Fixieren eines Ankerpunkts",
    "q.l9#12.e" to "Der doppelte Spierenstich ist kompakt und läuft gut durch; er eignet sich für Reepschnur und Bandschlingen. Nach Belastung lässt er sich schwer lösen, daher genug Seilende stehen lassen.",

    "q.l9#13.p" to "Was muss nach jedem Knoten getan werden?",
    "q.l9#13.o0" to "Verlauf und Länge der freien Enden prüfen und die Kontrolle Punkt für Punkt laut durchgehen",
    "q.l9#13.o1" to "Einmal daran ziehen genügt",
    "q.l9#13.o2" to "Ein Foto als Nachweis machen",
    "q.l9#13.o3" to "Wachs auftragen",
    "q.l9#13.e" to "«Richtig geknotet» und «fertig geknotet» sind zwei verschiedene Dinge. Zu kurze Seilenden rutschen unter Last durch; die Kontrolle muss zu einem festen Ablauf werden.",

    "q.l9#14.p" to "Warum ist eine Knotenstelle die Schwachstelle im System?",
    "q.l9#14.o0" to "Der Knoten biegt das Seil und senkt die Festigkeit deutlich",
    "q.l9#14.o1" to "Weil der Knoten zu schwer ist",
    "q.l9#14.o2" to "Wegen der Farbe",
    "q.l9#14.o3" to "Weil Reibungswärme entsteht",
    "q.l9#14.e" to "Im Knoten ist das Seil gebogen und die Last verteilt sich ungleich. Beim Systemaufbau gehört der Knoten an eine Position mit geringer Last, nicht an den tragenden Kern.",

    "q.l9#15.p" to "Was ist die wichtigste Eigenschaft eines Klemmknotens (etwa Prusik)?",
    "q.l9#15.o0" to "Er klemmt unter Last am Hauptseil und lässt sich unbelastet verschieben – eine Einweg-Absicherung",
    "q.l9#15.o1" to "Er blockiert immer",
    "q.l9#15.o2" to "Je dicker, desto besser",
    "q.l9#15.o3" to "Er taugt nur zum Abseilen",
    "q.l9#15.e" to "Der Wert liegt im Einweg-Prinzip: unter Last blockiert, unbelastet verschiebbar. Genau deshalb funktioniert er als Backup und zum Aufsteigen.",

    // ---------- l10 Klettergurt und Seilschaft ----------
    "q.l10#10.p" to "Was ist mit der Rückfädelung nach dem Anlegen des Klettergurts gemeint?",
    "q.l10#10.o0" to "Ob die Schnallen von Hüftgurt und Beinschlaufen durch beide Ringe zurückgefädelt sind und genug Gurtband übersteht",
    "q.l10#10.o1" to "Ob der Schraubkarabiner verschlossen ist",
    "q.l10#10.o2" to "Ob der Knoten festgezogen ist",
    "q.l10#10.o3" to "Ob der Helm geschlossen ist",
    "q.l10#10.e" to "Unvollständige Rückfädelung ist der häufigste Gurtfehler von Anfängern: Es sieht angelegt aus, gibt aber unter Last nach.",

    "q.l10#11.p" to "Wie ist das Seilende beim Gehen in der Seilschaft zu behandeln?",
    "q.l10#11.o0" to "Am Seilsack oder am Körper fixieren, damit es nicht auf dem Boden schleift",
    "q.l10#11.o1" to "Einfach im Schnee nachschleifen lassen",
    "q.l10#11.o2" to "Vollständig auslegen",
    "q.l10#11.o3" to "Um die Hand wickeln",
    "q.l10#11.e" to "Ein schleifendes Seilende hakt an Steigeisen, Felsen und Schneebrücken und wird im Sturz zur Stolperfalle. Aufgeräumt ist Grunddisziplin.",

    "q.l10#12.p" to "Warum darf der Seilabstand in der Seilschaft nicht zu kurz sein?",
    "q.l10#12.o0" to "Stürzt eine Person in eine Spalte, zieht sie die Mitgehenden direkt mit, und es fehlt Raum für die Rettung",
    "q.l10#12.o1" to "Weil das Seil nicht reicht",
    "q.l10#12.o2" to "Weil man nicht schnell vorankommt",
    "q.l10#12.o3" to "Weil es unschön aussieht",
    "q.l10#12.e" to "Der Abstand ist die Reaktionsstrecke. Zu kurz bindet zwei Personen zu einer Last zusammen, zu lang erschwert Bremsen und Verständigung.",

    "q.l10#13.p" to "Beim Übergang von der Seilschaft zum Vorstiegssichern: Was wird zuerst aufgebaut?",
    "q.l10#13.o0" to "Ein verlässlicher Standplatz und die Selbstsicherung",
    "q.l10#13.o1" to "Das Seil",
    "q.l10#13.o2" to "Die Kommunikation",
    "q.l10#13.o3" to "Das Foto",
    "q.l10#13.e" to "Der Übergang ist eine Unfallhäufungsstelle: In diesem Moment ist man weder in der Seilschaft noch gesichert. Erst den Stand bauen, dann das Seil lösen.",

    "q.l10#14.p" to "Wann erhöht die Seilschaft das Risiko?",
    "q.l10#14.o0" to "Auf flachen Hängen ohne Sturzgefahr, wo Knoten und Seilabstand mehr Stolper- und Abstimmungsaufwand erzeugen",
    "q.l10#14.o1" to "Immer",
    "q.l10#14.o2" to "Bei Gletscherspalten",
    "q.l10#14.o3" to "Beim Abstieg",
    "q.l10#14.e" to "Die Seilschaft ist ein Werkzeug gegen Sturz und Spalte. Im falschen Gelände überwiegt der Aufwand den Nutzen.",

    "q.l10#15.p" to "Was muss die Gruppe vor dem Anseilen gemeinsam festlegen?",
    "q.l10#15.o0" to "Seilabstand, Kommandos, Reihenfolge beim Passieren der Spaltenzone und Haltezeichen",
    "q.l10#15.o1" to "Die Marken der Ausrüstung",
    "q.l10#15.o2" to "Das Gehtempo",
    "q.l10#15.o3" to "Die Fotoaufgaben",
    "q.l10#15.e" to "Die Verlässlichkeit der Seilschaft kommt aus einheitlicher Reaktion. Ohne abgestimmte Kommandos wird der erste Zwischenfall zum Chaos.",

    // ---------- m07 Standplatzbau: Grundlagen ----------
    "q.m07#12.p" to "Wohin soll der Verschluss eines Schraubkarabiners zeigen?",
    "q.m07#12.o0" to "Vom Fels weg, fern von Reibung und Lastrichtung, damit Seil oder Kante ihn nicht aufdrücken",
    "q.m07#12.o1" to "Nach oben",
    "q.m07#12.o2" to "Nach unten",
    "q.m07#12.o3" to "Beliebig",
    "q.m07#12.e" to "Ein von aussen aufgedrückter Verschluss ist eine reale Versagensart. Die falsche Richtung heisst, die Zuverlässigkeit dem Zufall zu überlassen.",

    "q.m07#13.p" to "Warum darf eine Bandschlinge beim Verbinden zweier Ankerpunkte nicht über eine scharfe Kante laufen?",
    "q.m07#13.o0" to "Scharfe Kanten schneiden die Schlinge an, die Festigkeit sinkt unter Last deutlich",
    "q.m07#13.o1" to "Weil es unschön aussieht",
    "q.m07#13.o2" to "Weil sie rutscht",
    "q.m07#13.o3" to "Weil sie zu kurz ist",
    "q.m07#13.e" to "Ein kleiner Einschnitt kann die Festigkeit halbieren. Muss die Schlinge über eine Kante, dann mit Schutzmantel oder als verlängerte Kette.",

    "q.m07#14.p" to "In welchem Winkel wird eine Eisschraube üblicherweise gesetzt?",
    "q.m07#14.o0" to "Leicht nach oben (etwa 10–15 Grad), entgegen der Lastrichtung",
    "q.m07#14.o1" to "Völlig waagerecht",
    "q.m07#14.o2" to "Nach unten geneigt",
    "q.m07#14.o3" to "Beliebig",
    "q.m07#14.e" to "Leicht nach oben folgt die Schraube der Lastrichtung und wird in das Eis gedrückt statt herausgezogen. Bei schlechtem Eis länger und schräger setzen.",

    "q.m07#15.p" to "Der Standplatz hat nur einen einzigen Ankerpunkt. Was ist am wichtigsten?",
    "q.m07#15.o0" to "Einen unabhängigen Backup ergänzen oder auf verlässlicheres Gelände ausweichen",
    "q.m07#15.o1" to "Wie gewohnt nutzen",
    "q.m07#15.o2" to "Mehrere Karabiner einhängen",
    "q.m07#15.o3" to "Das Seil kürzen",
    "q.m07#15.e" to "Die Zahl der Karabiner ist keine Redundanz. Redundanz setzt voraus, dass die Versagensursachen verschieden sind.",

    // ---------- m08 Zielberg: Gangshka und Haba ----------
    "q.m08#12.p" to "Bei 5.000er-Bergen wie Gangshka und Haba: Was muss am frühesten geplant werden?",
    "q.m08#12.o0" to "Akklimatisierungsrhythmus und Wetterfenster, nicht die technische Schwierigkeit",
    "q.m08#12.o1" to "Der Einkauf der Ausrüstung",
    "q.m08#12.o2" to "Die Fotopositionen",
    "q.m08#12.o3" to "Die Aufgabenverteilung im Team",
    "q.m08#12.e" to "Die Schwierigkeit von 5.000ern liegt meist in Höhe und Wetter, nicht in der Technik. Zeit in die Akklimatisierung zu investieren bringt mehr als eine weitere Technikübung.",

    "q.m08#13.p" to "Wie ist mit Genehmigungen und Führerpflicht umzugehen?",
    "q.m08#13.o0" to "Die lokalen Vorschriften vorab klären; wo Führer oder Registrierung verlangt sind, diese genau einhalten",
    "q.m08#13.o1" to "Erst vor Ort fragen",
    "q.m08#13.o2" to "Den Kontrollposten umgehen",
    "q.m08#13.o3" to "Über Bekannte eine Ausnahme erbitten",
    "q.m08#13.e" to "Viele 5.000er verlangen Registrierung oder einen Führer. Bergsteigen ohne Genehmigung setzt Rettung und Versicherung gleichzeitig ausser Kraft.",

    "q.m08#14.p" to "Was ist die Logik hinter einem Stufenweg wie «Nebengipfel, dann Hauptgipfel»?",
    "q.m08#14.o0" to "Erst auf einer leichteren Route Akklimatisierung und Kondition prüfen, dann die technische Schwierigkeit draufsetzen",
    "q.m08#14.o1" to "Weil es billiger ist",
    "q.m08#14.o2" to "Weil es näher liegt",
    "q.m08#14.o3" to "Weil dort mehr Leute sind",
    "q.m08#14.e" to "Der Kern des Stufenwegs ist, jeweils nur eine Variable zu ändern. Steigen Höhe und technische Schwierigkeit gleichzeitig, lässt sich bei Problemen die Ursache kaum bestimmen.",

    "q.m08#15.p" to "Welche Informationen zum Rückzug müssen vor dem Start geklärt sein?",
    "q.m08#15.o0" to "Abstiegsweg, Lage der Reservecamps, nächste medizinische Versorgung und Kontaktwege",
    "q.m08#15.o1" to "Nur der Abstiegsweg",
    "q.m08#15.o2" to "Nur die medizinische Versorgung",
    "q.m08#15.o3" to "Nichts davon",
    "q.m08#15.e" to "Rückzug heisst nicht einfach zurückgehen. Bei Wetterverschlechterung kann das nächste Reservecamp die einzige machbare Option sein.",

    // ---------- l13 Akute Bergkrankheit AMS ----------
    "q.l13#14.p" to "Wie lange nach Ankunft in der Höhe treten AMS-Symptome üblicherweise auf?",
    "q.l13#14.o0" to "6–12 Stunden",
    "q.l13#14.o1" to "Sofort",
    "q.l13#14.o2" to "Nach 3 Tagen",
    "q.l13#14.o3" to "Nach einer Woche",
    "q.l13#14.e" to "Dieses Zeitfenster ist wichtig: Der Nachmittag und die Nacht des Ankunftstags sind die Beobachtungsphase – und der Grund, nicht weiter aufzusteigen.",

    "q.l13#15.p" to "Was ist das entscheidende Unterscheidungsmerkmal zwischen AMS und HACE?",
    "q.l13#15.o0" to "Ob Ataxie oder eine Bewusstseinsveränderung auftritt",
    "q.l13#15.o1" to "Die Stärke des Kopfschmerzes",
    "q.l13#15.o2" to "Ob Übelkeit besteht",
    "q.l13#15.o3" to "Die Herzfrequenz",
    "q.l13#15.e" to "Kopfschmerz und Übelkeit sind bei AMS häufig; sobald der Gang unsicher wird oder das Bewusstsein trübt, ist wie bei HACE zu behandeln und sofort abzusteigen.",

    "q.l13#16.p" to "Darf man 24 Stunden nach Abklingen der AMS-Symptome weiter aufsteigen?",
    "q.l13#16.o0" to "Ja, aber langsamer und unter engmaschiger Beobachtung",
    "q.l13#16.o1" to "Ja, beliebig",
    "q.l13#16.o2" to "Nie wieder",
    "q.l13#16.o3" to "Man muss 1.000 m absteigen",
    "q.l13#16.e" to "Vollständiges Abklingen zeigt, dass die Akklimatisierung fortschreitet. Trotzdem konservativer bleiben – und bei Rückkehr der Symptome den Aufstieg beenden.",

    "q.l13#17.p" to "Was wird leicht fälschlich als AMS eingeschätzt?",
    "q.l13#17.o0" to "Dehydratation, Erkältung und Schlafmangel",
    "q.l13#17.o1" to "Ein Knochenbruch",
    "q.l13#17.o2" to "Erfrierungen",
    "q.l13#17.o3" to "Schneeblindheit",
    "q.l13#17.e" to "Die Symptome überschneiden sich. Was nach Flüssigkeit und Ruhe deutlich besser wird, ist meist kein AMS; was bleibt oder zunimmt, wird als AMS behandelt.",

    "q.l13#18.p" to "Was ist bei Schmerzmitteln während einer AMS zu beachten?",
    "q.l13#18.o0" to "Schmerzmittel verdecken nur die Symptome und sind kein Grund, weiter aufzusteigen",
    "q.l13#18.o1" to "Wer sie genommen hat, darf aufsteigen",
    "q.l13#18.o2" to "Die Dosis darf erhöht werden",
    "q.l13#18.o3" to "Sie sind völlig unzulässig",
    "q.l13#18.e" to "Das Schmerzmittel lässt das Signal verschwinden, der Verlauf bleibt. Nach verdeckten Symptomen weiter aufzusteigen ist der häufigste Weg zur Verschlechterung.",

    "q.l13#19.p" to "Warum wird die Höhenkrankheit bei Kindern und älteren Menschen häufiger übersehen?",
    "q.l13#19.o0" to "Sie können Symptome schlechter benennen; Verhaltensänderungen zeigen sich oft vor der eigentlichen Klage",
    "q.l13#19.o1" to "Weil sie unempfindlich sind",
    "q.l13#19.o2" to "Weil sie sich schnell akklimatisieren",
    "q.l13#19.o3" to "Weil sie selten in die Berge gehen",
    "q.l13#19.e" to "Kinder zeigen Somnolenz, Weinen, Appetitlosigkeit; ältere Menschen oft nur fehlende Energie. Verhalten zu beobachten ist verlässlicher, als auf eine Aussage zu warten.",
    // ---------- l14 HACE und HAPE: Notfälle ----------
    "q.l14#12.p" to "Wie testet man Ataxie bei HACE vor Ort am einfachsten?",
    "q.l14#12.o0" to "Auf einer geraden Linie Ferse an Zehen setzen (Fersen-Zehen-Gang)",
    "q.l14#12.o1" to "Auf einem Bein stehen",
    "q.l14#12.o2" to "Kniebeugen",
    "q.l14#12.o3" to "Auf der Stelle springen",
    "q.l14#12.e" to "Kein gerader Gang, schwankender Gang bedeutet positiv. Der Test braucht kein Gerät, jeder kann ihn durchführen, und er taugt als tägliches Screening.",

    "q.l14#13.p" to "Wie entwickelt sich der Husten bei HAPE meist?",
    "q.l14#13.o0" to "Vom trockenen Husten zu schaumigem Auswurf, die Belastbarkeit bricht schnell ein",
    "q.l14#13.o1" to "Von produktivem Husten zu trockenem Husten",
    "q.l14#13.o2" to "Er bleibt unverändert",
    "q.l14#13.o3" to "Er tritt nur nachts auf",
    "q.l14#13.e" to "Schaumiger Auswurf und Atemnot in Ruhe sind die typische Kombination bei HAPE. Bis rosa-schaumiger Auswurf auftritt, ist der Zustand meist schon ausgeprägt.",

    "q.l14#14.p" to "In welcher Phase der Tour tritt HAPE häufiger auf?",
    "q.l14#14.o0" to "In der ersten bis zweiten Nacht nach dem Aufstieg",
    "q.l14#14.o1" to "Vor dem Start",
    "q.l14#14.o2" to "Während des Abstiegs",
    "q.l14#14.o3" to "Nach der Rückkehr ins Flachland",
    "q.l14#14.e" to "Nachts ist der Sauerstoffmangel am stärksten, HAPE zeigt sich oft in der zweiten Nacht. Deshalb gilt der ersten Nacht besondere Aufmerksamkeit.",

    "q.l14#15.p" to "Bei Verdacht auf HACE oder HAPE: Wie lautet die Prioritätenfolge?",
    "q.l14#15.o0" to "Sofort absteigen und Sauerstoff geben; Medikamente sind unterstützend",
    "q.l14#15.o1" to "Erst Medikamente, dann beobachten",
    "q.l14#15.o2" to "Erst eine Nacht abwarten",
    "q.l14#15.o3" to "Erst auf Rettung warten",
    "q.l14#15.e" to "Der Abstieg ist die einzige Massnahme, die den Verlauf sicher umkehrt. Medikamente und Sauerstoff dienen dazu, Zeit für den Abstieg zu gewinnen.",

    "q.l14#16.p" to "Was leistet der Gamow-Beutel, und wo liegt seine Grenze?",
    "q.l14#16.o0" to "Er simuliert einen Abstieg und gewinnt Zeit, ersetzt aber keinen echten Abstieg",
    "q.l14#16.o1" to "Er heilt die Erkrankung",
    "q.l14#16.o2" to "Er ist dauerhaft einsetzbar",
    "q.l14#16.o3" to "Er ist nur bei wachem Bewusstsein möglich",
    "q.l14#16.e" to "Der Beutel ist ein transportables Tiefland: Er braucht Personal, kostet Kraft und hat begrenzte Kapazität. Er ist Übergangslösung, nicht Ziel.",

    "q.l14#17.p" to "Nach einem HAPE während einer Tour: Was ist nach der Erholung zu tun?",
    "q.l14#17.o0" to "Auf dieser Tour nicht weiter aufsteigen, den Abstieg organisieren",
    "q.l14#17.o1" to "Zwei Tage pausieren und dann weiter",
    "q.l14#17.o2" to "Andere Route wählen und weitermachen",
    "q.l14#17.o3" to "Mit halber Dosis weitermachen",
    "q.l14#17.e" to "Das Rezidivrisiko von HAPE ist hoch, und ein zweiter Schub kann schneller und schwerer verlaufen. Diese Besteigung ist beendet.",

    "q.l14#18.p" to "Wie zeigt sich die Bewusstseinsveränderung bei HACE konkret?",
    "q.l14#18.o0" to "Somnolenz, Antworten am Thema vorbei, auffälliges Verhalten, Halluzinationen",
    "q.l14#18.o1" to "Nur Koma",
    "q.l14#18.o2" to "Nur Kopfschmerz",
    "q.l14#18.o3" to "Nur Übelkeit",
    "q.l14#18.e" to "Früh kann es nur «ruhiger als sonst» sein oder wiederholtes Sprechen. Mitgehende bemerken es meist früher als die Person selbst – deshalb gegenseitig beobachten.",

    "q.l14#19.p" to "Warum können HAPE und HACE gleichzeitig auftreten?",
    "q.l14#19.o0" to "Beide sind Ausdruck der schweren Höhenkrankheit und können pathologisch nebeneinander bestehen",
    "q.l14#19.o1" to "Weil die Medikamente dieselben sind",
    "q.l14#19.o2" to "Weil die Symptome ähnlich sind",
    "q.l14#19.o3" to "Sie treten nie gemeinsam auf",
    "q.l14#19.e" to "Klinisch sind Kombinationen von HACE und HAPE häufig. Die Behandlung ist dieselbe: absteigen, Sauerstoff, bei Bedarf Medikamente.",

    // ---------- l15 Akklimatisierungsstrategie ----------
    "q.l15#12.p" to "Welche Veränderung setzt bei der Akklimatisierung zuerst ein?",
    "q.l15#12.o0" to "Erhöhte Ventilation (tieferes und schnelleres Atmen)",
    "q.l15#12.o1" to "Mehr rote Blutkörperchen",
    "q.l15#12.o2" to "Stärkere Muskulatur",
    "q.l15#12.o3" to "Sinkende Herzfrequenz",
    "q.l15#12.e" to "Die Ventilation steigt binnen Stunden, die Vermehrung der roten Blutkörperchen braucht Tage bis Wochen. Deshalb ist die erste Nacht die härteste.",

    "q.l15#13.p" to "Warum verschlechtern Alkohol und sedierende Medikamente die Höhenkrankheit?",
    "q.l15#13.o0" to "Sie dämpfen den Atemantrieb und verstärken so den nächtlichen Sauerstoffmangel",
    "q.l15#13.o1" to "Weil sie entwässern",
    "q.l15#13.o2" to "Weil sie den Magen reizen",
    "q.l15#13.o3" to "Weil sie den Schlaf stören",
    "q.l15#13.e" to "In der Höhe ist der Atemantrieb ohnehin geschwächt; solche Substanzen unterdrücken ihn weiter. Ein alkoholisiertes Bild lässt sich zudem leicht mit frühem HACE verwechseln.",

    "q.l15#14.p" to "Periodische Atmung ist nachts in der Höhe häufig. Wie entsteht sie?",
    "q.l15#14.o0" to "Der Sauerstoffmangel führt zu Hyperventilation, das dadurch zu niedrige CO₂ zu einer Atempause, und das wiederholt sich",
    "q.l15#14.o1" to "Durch verengte Atemwege",
    "q.l15#14.o2" to "Durch ein Herzproblem",
    "q.l15#14.o3" to "Durch einen psychischen Effekt",
    "q.l15#14.e" to "Das ist physiologisch und kein Grund zur Panik. Es zerreisst aber den Schlaf und ist einer der Gründe, tiefer zu übernachten.",

    "q.l15#15.p" to "Welches Zeichen gehört nicht zu den frühen Warnsignalen einer schlechten Akklimatisierung?",
    "q.l15#15.o0" to "Besserer Appetit und erholsamer Schlaf",
    "q.l15#15.o1" to "Anhaltender Kopfschmerz",
    "q.l15#15.o2" to "Nächtliches, wiederholtes Aufwachen mit Atemnot",
    "q.l15#15.o3" to "Sinkende Belastbarkeit",
    "q.l15#15.e" to "Essen können, gut schlafen, gehen können sind die drei Zeichen guter Akklimatisierung. Treten sie nicht ein, ist das Tempo zu reduzieren.",

    "q.l15#16.p" to "Wie stark ist die Evidenz für intermittierendes Hypoxietraining (Präkonditionierung)?",
    "q.l15#16.o0" to "Es gibt physiologische Effekte, aber sie ersetzen keine Akklimatisierung vor Ort",
    "q.l15#16.o1" to "Es ersetzt die Akklimatisierung vollständig",
    "q.l15#16.o2" to "Es ist völlig wirkungslos",
    "q.l15#16.o3" to "Es wirkt nur bei Leistungssportlern",
    "q.l15#16.e" to "Präkonditionierung kann die Akklimatisierung etwas verkürzen, entscheidend bleiben aber Aufstiegsgeschwindigkeit und Schlafhöhe. Es ist kein Abkürzungsweg.",

    "q.l15#17.p" to "Was ist das Hauptrisiko, mit einer nicht ausgeheilten Erkältung in grosse Höhe zu gehen?",
    "q.l15#17.o0" to "Die Entzündung der Atemwege erhöht das HAPE-Risiko",
    "q.l15#17.o1" to "Man steckt die Mitgehenden an",
    "q.l15#17.o2" to "Die Erkältung wird schlimmer",
    "q.l15#17.o3" to "Es hat keinen Einfluss",
    "q.l15#17.e" to "Das ist der am leichtesten übersehene Punkt. Eine Erkältung als Kleinigkeit abzutun und trotzdem aufzusteigen ist ein häufiger Auslöser von HAPE.",

    "q.l15#18.p" to "Wie ist ein Ruhetag in der Akklimatisierungsphase richtig zu nutzen?",
    "q.l15#18.o0" to "Auf gleicher Höhe in Bewegung bleiben, Schlaf und Essen nachholen, statt völlig flachzuliegen",
    "q.l15#18.o1" to "Völlig im Zelt liegen",
    "q.l15#18.o2" to "Weiter aufsteigen",
    "q.l15#18.o3" to "Ins Tal absteigen",
    "q.l15#18.e" to "Leichte Bewegung unterstützt Ventilation und Kreislauf. Völliges Liegen verlangsamt die Akklimatisierung und dämpft den Appetit.",

    "q.l15#19.p" to "Warum gilt «die Tourenplanung selbst ist Prävention»?",
    "q.l15#19.o0" to "Aufstiegsgeschwindigkeit und Schlafhöhe bestimmen den grössten Teil des Risikos; den Plan zu ändern wirkt grundsätzlicher als Tabletten",
    "q.l15#19.o1" to "Weil ein Plan leicht zu schreiben ist",
    "q.l15#19.o2" to "Weil Medikamente teuer sind",
    "q.l15#19.o3" to "Weil der Bergführer es verlangt",
    "q.l15#19.e" to "Wer Akklimatisierungstage einplant, braucht selten Medikamente; wer den Plan randvoll macht, stützt sich meist auf Tabletten.",

    // ---------- l16 Unterkühlung und Erfrierungen ----------
    "q.l16#12.p" to "Welcher Kerntemperatur entspricht etwa die leichte Unterkühlung?",
    "q.l16#12.o0" to "35–32 °C, wach und mit deutlichem Zittern",
    "q.l16#12.o1" to "38 °C",
    "q.l16#12.o2" to "Unter 30 °C",
    "q.l16#12.o3" to "Unter 28 °C",
    "q.l16#12.e" to "Leicht ist durch Zittern und klares Bewusstsein gekennzeichnet. Zittern zeigt, dass der Körper noch Wärme produziert – und dass noch etwas zu retten ist.",

    "q.l16#13.p" to "Warum ist das Nachlassen des Zitterns ein Warnsignal?",
    "q.l16#13.o0" to "Der Körper kann die Temperatur nicht mehr über Wärmeproduktion halten und geht in mittelschwere Unterkühlung über",
    "q.l16#13.o1" to "Es zeigt Erholung",
    "q.l16#13.o2" to "Es zeigt, dass die Person schläft",
    "q.l16#13.o3" to "Es zeigt Erschöpfung",
    "q.l16#13.e" to "Von «zittert ohne Ende» zu «zittert nicht mehr» ist keine Besserung, sondern ein Versagen der Gegenregulation. Sofort wiedererwärmen und transportieren.",

    "q.l16#14.p" to "Wie ist bei einer bewusstseinsgetrübten unterkühlten Person vorzugehen?",
    "q.l16#14.o0" to "Keine heissen Getränke geben, sondern isolieren, vom Boden trennen und schonend transportieren",
    "q.l16#14.o1" to "Heisse Zuckerlösung einflössen",
    "q.l16#14.o2" to "Hände und Füsse reiben",
    "q.l16#14.o3" to "Die Person gehen lassen",
    "q.l16#14.e" to "Bei getrübtem Bewusstsein ist der Schluckreflex unzuverlässig, Getränke führen zur Aspiration. Grobe Bewegungen können Herzrhythmusstörungen auslösen.",

    "q.l16#15.p" to "Zum Wiedererwärmen erfrorener Gliedmassen vor Ort: Welche Wassertemperatur ist richtig?",
    "q.l16#15.o0" to "37–40 °C",
    "q.l16#15.o1" to "50–60 °C",
    "q.l16#15.o2" to "Eiswasser",
    "q.l16#15.o3" to "Je heisser, desto besser",
    "q.l16#15.e" to "Diese Temperatur liegt nahe der Körpertemperatur: Sie erwärmt, ohne zu verbrühen. Zu heiss verursacht einen Zweitschaden, zu kalt bleibt wirkungslos.",

    "q.l16#16.p" to "Warum muss nach dem Wiedererwärmen ein erneutes Auftauen und Erfrieren vermieden werden?",
    "q.l16#16.o0" to "Wiederholtes Auftauen und Erfrieren schädigt das Gewebe weit stärker als eine einmalige Erfrierung",
    "q.l16#16.o1" to "Weil es schmerzt",
    "q.l16#16.o2" to "Weil es anschwillt",
    "q.l16#16.o3" to "Weil Narben bleiben",
    "q.l16#16.e" to "Auftauen und wieder erfrieren ist schlimmer als durchgehend gefroren zu bleiben. Wiedererwärmt wird daher nur, wenn ein erneutes Erfrieren ausgeschlossen ist.",

    "q.l16#17.p" to "Was ist bei Erfrierungen vor Ort nicht zu tun?",
    "q.l16#17.o0" to "Mit Schnee reiben, über Feuer halten, mit Alkohol abreiben",
    "q.l16#17.o1" to "In warmem Wasser erwärmen",
    "q.l16#17.o2" to "Mit sterilem Verband abdecken",
    "q.l16#17.o3" to "Die Extremität hochlagern",
    "q.l16#17.e" to "Reibung und trockene Hitze verschlimmern den Gewebeschaden. Vor Ort gilt nur: warmes Wasser, Schutz, Schmerzbehandlung.",

    "q.l16#18.p" to "Kann man nach einer Erfrierung der Füsse weitergehen?",
    "q.l16#18.o0" to "Möglichst nicht – Gehen verschlimmert den Gewebeschaden; wer auf Rettung warten kann, wartet",
    "q.l16#18.o1" to "Gehen ist unproblematisch",
    "q.l16#18.o2" to "Laufen geht schneller",
    "q.l16#18.o3" to "Solange es nicht schmerzt, ja",
    "q.l16#18.e" to "Belastet man einen wiedererwärmten, erfrorenen Fuss, verschlimmert sich der Schaden deutlich. Deshalb muss der Zeitpunkt der Wiedererwärmung abgewogen werden.",

    "q.l16#19.p" to "Was sind die drei wichtigsten Massnahmen gegen Unterkühlung?",
    "q.l16#19.o0" to "Trocken bleiben, Wind abhalten, rechtzeitig Energie zuführen",
    "q.l16#19.o1" to "Mehr Kleidung anziehen",
    "q.l16#19.o2" to "Viel heisses Wasser trinken",
    "q.l16#19.o3" to "Viel gehen",
    "q.l16#19.e" to "Nässe, Wind und Energiemangel sind die drei Eintrittspforten der Unterkühlung. Die Gegenmittel heissen Funktionsschicht, Windschicht und regelmässiges Essen.",

    // ---------- m14 Gefahrenbeurteilung und Entscheidung ----------
    "q.m14#17.p" to "Wie zeigt sich versunkener Aufwand (sunk cost) typisch in Bergentscheidungen?",
    "q.m14#17.o0" to "So viel Geld und Zeit investiert – das darf nicht umsonst gewesen sein",
    "q.m14#17.o1" to "Die Wettervorhersage stimmt nicht",
    "q.m14#17.o2" to "Die Ausrüstung reicht nicht",
    "q.m14#17.o3" to "Die Mitgehenden sind zu langsam",
    "q.m14#17.e" to "Je mehr investiert wurde, desto schwerer fällt der Verzicht. Der bereits gezahlte Preis kommt durch Weitermachen nicht zurück, es kommen nur neue Risiken hinzu.",

    "q.m14#18.p" to "Wann entsteht Gruppendenken am ehesten?",
    "q.m14#18.o0" to "Bei starkem Zusammenhalt, fehlenden Gegenstimmen und einer zu früh festgelegten Haltung der Leitung",
    "q.m14#18.o1" to "Bei grossen Meinungsunterschieden",
    "q.m14#18.o2" to "Bei kleiner Gruppengrösse",
    "q.m14#18.o3" to "Bei schlechtem Wetter",
    "q.m14#18.e" to "Zusammenhalt ist gut, unterdrückt aber Widerspruch. Die Jüngsten zuerst sprechen zu lassen und jemanden als Advokat des Gegenarguments zu benennen sind übliche Gegenmittel.",

    "q.m14#19.p" to "Was ist der Bestätigungsfehler?",
    "q.m14#19.o0" to "Nur Informationen zu suchen, die die eigene Einschätzung stützen, und Gegenbelege zu übersehen",
    "q.m14#19.o1" to "Informationen nicht behalten zu können",
    "q.m14#19.o2" to "Übermässige Vorsicht",
    "q.m14#19.o3" to "Sich auf andere zu verlassen",
    "q.m14#19.e" to "Wer heute aufsteigen will, nimmt nur die guten Wetterzeichen wahr. Aktiv nach Gegenbeispielen zu suchen ist das einzige Gegenmittel.",

    "q.m14#20.p" to "Warum werden wichtige Entscheidungen mit Checklisten getroffen?",
    "q.m14#20.o0" to "Unter Müdigkeit und Stress fällt manches weg; die Liste macht aus «daran denken» ein «Punkt für Punkt prüfen»",
    "q.m14#20.o1" to "Zur Dokumentation",
    "q.m14#20.o2" to "Um professionell zu wirken",
    "q.m14#20.o3" to "Weil es vorgeschrieben ist",
    "q.m14#20.e" to "Eine Checkliste ersetzt kein Urteil, sie stellt sicher, dass alle Informationen für das Urteil vorliegen.",

    "q.m14#21.p" to "Was ist ein Beispiel für den Ankereffekt auf Tour?",
    "q.m14#21.o0" to "Die geplanten 6 Stunden bis zum Lager als Norm nehmen und die tatsächlichen Verhältnisse ignorieren",
    "q.m14#21.o1" to "Dem Bergführer vertrauen",
    "q.m14#21.o2" to "Auf die Karte schauen",
    "q.m14#21.o3" to "Die Körpertemperatur messen",
    "q.m14#21.e" to "Ist der Anker gesetzt, richtet sich jede weitere Beurteilung daran aus. Besser ist es, den tatsächlichen Fortschritt zur Grundlage zu machen statt den Planwert.",

    "q.m14#22.p" to "Warum lohnt es, Entscheidungen festzuhalten (Zeit, Grundlage, Ergebnis)?",
    "q.m14#22.o0" to "Die Nachbesprechung hat eine Grundlage, und die Gruppe versteht dieselben Fakten gleich",
    "q.m14#22.o1" to "Für den Bericht",
    "q.m14#22.o2" to "Für die Versicherung",
    "q.m14#22.o3" to "Für ein Buch",
    "q.m14#22.e" to "Ohne Aufzeichnung wird die Nachbesprechung zum Aneinandervorbeireden. Eine aufgeschriebene Zeitleiste zeigt, an welchem Punkt eine Entscheidung früher möglich gewesen wäre.",

    "q.m14#23.p" to "Welches konkrete Risiko bringt der Expertenhalo?",
    "q.m14#23.o0" to "Niemand wagt, einen offensichtlichen Fehler zu hinterfragen, und der Fehler wird einfach umgesetzt",
    "q.m14#23.o1" to "Der Experte wird müde",
    "q.m14#23.o2" to "Der Experte ist zu teuer",
    "q.m14#23.o3" to "Der Experte kennt die Route nicht",
    "q.m14#23.e" to "Der Halo unterdrückt, dass Informationen nach oben kommen. Der gefährlichste Zustand in einer Gruppe ist nicht, dass niemand etwas weiss, sondern dass niemand etwas sagt.",
    // ---------- m12 Fortgeschrittene Seilsysteme und mechanischer Vorteil ----------
    "q.m12#16.p" to "Wie hoch ist der theoretische mechanische Vorteil eines 3:1-Systems?",
    "q.m12#16.o0" to "Ein Meter Seil gezogen hebt die Last etwa einen Drittelmeter",
    "q.m12#16.o1" to "Die Last halbiert sich",
    "q.m12#16.o2" to "Die Geschwindigkeit bleibt gleich",
    "q.m12#16.o3" to "Klemmknoten sind nicht nötig",
    "q.m12#16.e" to "Mechanischer Vorteil entspricht der Zahl der tragenden Seilstränge. 3:1 heisst, die aufzubringende Kraft beträgt rund ein Drittel der Last (ohne Reibung).",

    "q.m12#17.p" to "Wie ist die Effizienz eines 5:1-Systems in der Praxis meist?",
    "q.m12#17.o0" to "Niedriger als der theoretische Wert, weil Rollen und Seil Reibung erzeugen",
    "q.m12#17.o1" to "Höher als der theoretische Wert",
    "q.m12#17.o2" to "Genau gleich dem theoretischen Wert",
    "q.m12#17.o3" to "Unabhängig von der Reibung",
    "q.m12#17.e" to "Jede Rolle verliert durch Reibung; real erreicht man oft nur sechs bis sieben Zehntel des theoretischen Werts. Beim Aufbau Reserve einplanen.",

    "q.m12#18.p" to "Was kostet es vor allem, einen Schraubkarabiner statt einer Rolle als Umlenkpunkt zu verwenden?",
    "q.m12#18.o0" to "Die Reibung steigt deutlich, die Effizienz sinkt",
    "q.m12#18.o1" to "Die Festigkeit reicht nicht",
    "q.m12#18.o2" to "Der Klettergurt wird abgenutzt",
    "q.m12#18.o3" to "Er lässt sich nicht verriegeln",
    "q.m12#18.e" to "Ein Karabiner lenkt um, verringert aber keine Reibung; ein Teil der Zugkraft wird von der Reibung verbraucht. Wo eine Rolle verfügbar ist, nimmt man die Rolle.",

    "q.m12#19.p" to "Welche Aufgabe hat der Einweg-Klemmknoten im Rettungssystem?",
    "q.m12#19.o0" to "Er blockiert nach dem Zug und verhindert, dass die Last zurücksinkt",
    "q.m12#19.o1" to "Die Festigkeit erhöhen",
    "q.m12#19.o2" to "Die Reibung verringern",
    "q.m12#19.o3" to "Zwei Seile verbinden",
    "q.m12#19.e" to "Ohne Klemmknoten rutscht die Last bei jedem Loslassen zurück. Der Klemmknoten ist der Schlüssel, um wiederholte Zugintervalle in Weg umzusetzen.",

    "q.m12#20.p" to "Warum wird im Rettungssystem ein Backup-Klemmknoten gesetzt?",
    "q.m12#20.o0" to "Der Hauptklemmknoten kann durchrutschen oder versagen; das Backup ist die letzte Sicherung",
    "q.m12#20.o1" to "Damit es ordentlich aussieht",
    "q.m12#20.o2" to "Um die Zugkraft zu erhöhen",
    "q.m12#20.o3" to "Um Seil zu sparen",
    "q.m12#20.e" to "Die Zuverlässigkeit eines Klemmknotens hängt von passendem Durchmesser und Zustand ab. In kritischen Systemen sind zwei Klemmknoten Standard.",

    "q.m12#21.p" to "Beim Ziehen einer verletzten Person sollte das System möglichst...",
    "q.m12#21.o0" to "nah am Gelände verlaufen, damit die Person nicht gegen Fels oder Wechte stösst",
    "q.m12#21.o1" to "so hoch wie möglich ziehen",
    "q.m12#21.o2" to "so schnell wie möglich ziehen",
    "q.m12#21.o3" to "senkrecht hochziehen",
    "q.m12#21.e" to "Die Schäden beim Ziehen entstehen häufiger durch Anstossen als durch die Zugkraft. Routenführung und Lage der Sicherungspunkte sind ebenso wichtig.",

    "q.m12#22.p" to "Was kostet ein 6:1-System (Verbundsystem) im Vergleich zu 3:1?",
    "q.m12#22.o0" to "Mehr Material, langsamerer Aufbau, höherer Seilverbrauch",
    "q.m12#22.o1" to "Kraftsparender und schneller",
    "q.m12#22.o2" to "Es kostet nichts",
    "q.m12#22.o3" to "Es lässt sich nicht mehr einholen",
    "q.m12#22.e" to "Je höher der mechanische Vorteil, desto komplexer der Aufbau und desto mehr Seil wird gebraucht. Bei der Rettung ist «schnell» oft wichtiger als «kraftsparend».",

    "q.m12#23.p" to "Wird mitten im System ein Umbau nötig, was ist die Grundanforderung?",
    "q.m12#23.o0" to "Zu jedem Zeitpunkt trägt mindestens ein Gerät die Last, und es entsteht keine ungesicherte Lücke",
    "q.m12#23.o1" to "Schnell arbeiten",
    "q.m12#23.o2" to "Zu zweit arbeiten",
    "q.m12#23.o3" to "Dasselbe Seil verwenden",
    "q.m12#23.e" to "Umbaumomente sind Unfallhäufungspunkte in der Rettung. Wo immer Altes gelöst wird, muss zuerst das Neue stehen.",

    "q.m12#24.p" to "Was ist zu tun, wenn das Seil im System über eine scharfe Kante läuft?",
    "q.m12#24.o0" to "Schutzmantel anbringen oder den Verlauf ändern, damit der Seilmantel nicht angeschnitten wird",
    "q.m12#24.o1" to "Einfach darüberlaufen lassen",
    "q.m12#24.o2" to "Fester spannen",
    "q.m12#24.o3" to "Eine Bandschlinge statt Seil nehmen",
    "q.m12#24.e" to "Ein angeschnittenes Lastseil verliert abrupt an Festigkeit. Ein Schutzmantel kostet wenig – der Preis kann ein Seil oder ein Sturz sein.",

    "q.m12#25.p" to "Warum sind die Anforderungen an Ankerpunkte in Rettungssystemen höher als bei einem normalen Standplatz?",
    "q.m12#25.o0" to "Sie müssen statische Last plus dynamische Schwankungen aufnehmen, und es gibt meist nur ein System",
    "q.m12#25.o1" to "Weil sie wichtiger sind",
    "q.m12#25.o2" to "Weil mehr Personen beteiligt sind",
    "q.m12#25.o3" to "Wegen der Seillänge",
    "q.m12#25.e" to "Bei einer Rettung gibt es keinen zweiten Standplatz als Auffangnetz. Versagt der Anker, fallen beide.",

    "q.m12#26.p" to "Was ist neben dem mechanischen Vorteil bei der Schätzung der nötigen Zugkraft zu berücksichtigen?",
    "q.m12#26.o0" to "Gewicht von Person und Ausrüstung, Reibung an Seil und Rollen, Widerstand des Geländes",
    "q.m12#26.o1" to "Das Wetter",
    "q.m12#26.o2" to "Die Zeit",
    "q.m12#26.o3" to "Das Gewicht der Mitgehenden",
    "q.m12#26.e" to "Die theoretische Zugkraft wird oft unterschätzt. Mit Reibung und Gelände kann der tatsächliche Aufwand das Doppelte betragen.",

    "q.m12#27.p" to "Was ist nach dem Aufbau des Systems zuerst zu tun?",
    "q.m12#27.o0" to "Einmal ohne Last ziehen und prüfen, ob Verlauf, Klemmknoten und Anker stimmen",
    "q.m12#27.o1" to "Sofort eine Person ziehen",
    "q.m12#27.o2" to "Ein Foto machen",
    "q.m12#27.o3" to "Das Seil aufnehmen",
    "q.m12#27.e" to "Ein Probezug ohne Last findet rund 80 % der Aufbaufehler. Diese zehn Sekunden können einen Systemausfall ersparen.",

    // ---------- m13 Selbstrettung und Seilschaftsrettung ----------
    "q.m13#14.p" to "Wie lautet die richtige Reihenfolge beim Selbstaufstieg mit Klemmknoten (Prusiken)?",
    "q.m13#14.o0" to "Aufstehen (oberen Klemmknoten schieben), setzen (Gewicht verlagern), unteren Klemmknoten schieben, wiederholen",
    "q.m13#14.o1" to "Beide Klemmknoten gleichzeitig schieben",
    "q.m13#14.o2" to "Nur den oberen Klemmknoten schieben",
    "q.m13#14.o3" to "Mit den Armen ziehen",
    "q.m13#14.e" to "Der Zyklus Aufstehen, Setzen, Schieben verlagert das Gewicht zwischen oberem und unterem Klemmknoten. Wer beide gleichzeitig schiebt, rutscht ab.",

    "q.m13#15.p" to "Wozu dient die Fussstrippe beim Selbstaufstieg?",
    "q.m13#15.o0" to "Sie verlagert Gewicht auf die Beine und entlastet die Arme",
    "q.m13#15.o1" to "Sie erhöht die Reibung",
    "q.m13#15.o2" to "Sie verbindet mit dem Klettergurt",
    "q.m13#15.o3" to "Sie markiert die Höhe",
    "q.m13#15.e" to "Nur mit den Armen zu ziehen ermüdet nach wenigen dutzend Metern. Die Fussstrippe bringt die Beine ins Spiel und entscheidet darüber, ob man herauskommt.",

    "q.m13#16.p" to "Was ist bei einer Seilschaftsrettung zuerst zu tun?",
    "q.m13#16.o0" to "Bremsen und fixieren, damit die gestürzte Person nicht weiter abrutscht",
    "q.m13#16.o1" to "Sofort in die Spalte hinabsteigen",
    "q.m13#16.o2" to "Rettung rufen",
    "q.m13#16.o3" to "Ein Foto zur Dokumentation machen",
    "q.m13#16.e" to "Das Bremsen ist das Einzige, was keinen Aufschub duldet. Erst fixieren, dann über Kommunikation, System und Ziehen sprechen.",

    "q.m13#17.p" to "Eine Person hängt in der Spalte. Welche Schäden sind am meisten zu befürchten?",
    "q.m13#17.o0" to "Unterkühlung, Druck durch das Seil und Verletzungen durch Anstossen",
    "q.m13#17.o1" to "Sonnenbrand",
    "q.m13#17.o2" to "Höhenkrankheit",
    "q.m13#17.o3" to "Dehydratation",
    "q.m13#17.e" to "In der Spalte ist es extrem kalt, und das Hängen im Gurt behindert die Durchblutung. Rettung muss schnell sein, nicht nur kräftig.",

    "q.m13#18.p" to "Warum bekommt die gestürzte Person zuerst eine Selbstsicherung?",
    "q.m13#18.o0" to "Damit sie nicht mehr am Hauptseil hängt und die Rettenden die Hände für den Systemaufbau frei haben",
    "q.m13#18.o1" to "Weil man dem Seil nicht traut",
    "q.m13#18.o2" to "Weil es vorgeschrieben ist",
    "q.m13#18.o3" to "Weil Ausrüstung fehlt",
    "q.m13#18.e" to "Eine Selbstsicherung aus Klemmknoten oder Pickel stabilisiert die Position und gibt der Person eine Aufgabe, was die Panik verringert.",

    "q.m13#19.p" to "Wie wird eine handlungsunfähige Person richtig aus der Spalte geholt?",
    "q.m13#19.o0" to "Ein 3:1- oder 5:1-System aufbauen und von oben ziehen",
    "q.m13#19.o1" to "Das Seil direkt mit den Händen ziehen",
    "q.m13#19.o2" to "Die Person soll selbst hochklettern",
    "q.m13#19.o3" to "Das Seil um die Hüfte wickeln",
    "q.m13#19.e" to "Mit den Händen zu ziehen ist praktisch unmöglich und geht mit Kontrollverlust einher. Ziehen über ein System ist die einzige verlässliche Methode.",

    "q.m13#20.p" to "Woher kommt der Zeitdruck bei einer Rettung?",
    "q.m13#20.o0" to "Geschwindigkeit der Unterkühlung, Wetterwechsel, Erschöpfung der Gruppe",
    "q.m13#20.o1" to "Nur von der Erschöpfung",
    "q.m13#20.o2" to "Nur vom Wetter",
    "q.m13#20.o3" to "Nur von der Unterkühlung",
    "q.m13#20.e" to "Alle drei wirken gleichzeitig. Der Rettungsplan muss die Frage «wie lange dauert es» beantworten, nicht nur «ist es machbar».",

    "q.m13#21.p" to "Welche Kommunikationsform ist bei einer Rettung am unzuverlässigsten?",
    "q.m13#21.o0" to "Rufen über einen kleinen Schneehügel hinweg",
    "q.m13#21.o1" to "Funkgerät",
    "q.m13#21.o2" to "Seilzeichen",
    "q.m13#21.o3" to "Pfeife",
    "q.m13#21.e" to "Wind, Seillänge und Gelände schlucken den Schall. Vorab vereinbarte Seil- oder Pfeifzeichen sind verlässlicher als Rufen vor Ort.",

    "q.m13#22.p" to "Warum müssen Selbstrettungstechniken in sicherem Gelände bis zur Automatik geübt werden?",
    "q.m13#22.o0" to "Im echten Sturz ist die Aufmerksamkeit von Angst besetzt; nur automatisierte Abläufe funktionieren dann",
    "q.m13#22.o1" to "Für die Prüfung",
    "q.m13#22.o2" to "Für die Geschwindigkeit",
    "q.m13#22.o3" to "Für das Aussehen",
    "q.m13#22.e" to "Das ist die gemeinsame Logik aller Rettungsausbildungen: Was ohne Nachdenken läuft, lässt Aufmerksamkeit für Beobachten und Beurteilen frei.",

    "q.m13#23.p" to "Was ist bei einer Dreierseilschaft die Hauptaufgabe der zweiten Person während der Rettung?",
    "q.m13#23.o0" to "Beim Bremsen helfen, das System vorbereiten, den Bereich oberhalb beobachten",
    "q.m13#23.o1" to "Fotografieren",
    "q.m13#23.o2" to "Weitergehen",
    "q.m13#23.o3" to "Das Seil aufnehmen",
    "q.m13#23.e" to "Genau darin liegt der Sinn der Dreierseilschaft: eine Person bremst, eine baut das System, eine beobachtet. In der Zweierseilschaft muss beides gleichzeitig gelingen.",

    "q.m13#24.p" to "Wie lautet die Priorität, wenn die gestürzte Person nicht mehr reagiert?",
    "q.m13#24.o0" to "So schnell wie möglich herausholen und mit der Ersten Hilfe beginnen, parallel externe Hilfe rufen",
    "q.m13#24.o1" to "Zuerst ein 5:1-System bauen",
    "q.m13#24.o2" to "Auf Rettung warten",
    "q.m13#24.o3" to "Zuerst dokumentieren",
    "q.m13#24.e" to "Keine Reaktion bedeutet ein sehr kurzes Zeitfenster. Dann gilt «schnell» vor «kraftsparend»; notfalls mit dem einfachsten System.",

    "q.m13#25.p" to "Welcher Schritt wird nach einer Rettung am leichtesten vergessen?",
    "q.m13#25.o0" to "System und Ablauf nachbesprechen und die Probleme aufschreiben",
    "q.m13#25.o1" to "Das Seil aufnehmen",
    "q.m13#25.o2" to "Absteigen",
    "q.m13#25.o3" to "Essen",
    "q.m13#25.e" to "Der Unterschied zwischen Übung und Ernstfall zeigt sich in der Nachbesprechung: welcher Schritt langsam war, welcher Knoten falsch, welches Kommando niemand verstanden hat.",

    "q.m13#26.p" to "Warum muss das Rettungssystem unabhängig vom Hauptseil sein?",
    "q.m13#26.o0" to "Das Hauptseil kann durch Eissplitter oder Kanten beschädigt sein und trägt weiterhin Last",
    "q.m13#26.o1" to "Weil es vorgeschrieben ist",
    "q.m13#26.o2" to "Weil es länger ist",
    "q.m13#26.o3" to "Weil es leichter ist",
    "q.m13#26.e" to "Ein Rettungssystem an ein beschädigtes, lasttragendes Hauptseil zu hängen, addiert zwei Risiken auf einmal.",

    "q.m13#27.p" to "Was muss in einer Spaltenzone vorab entschieden werden?",
    "q.m13#27.o0" to "Wer bremst, wer das System baut, wie kommuniziert wird",
    "q.m13#27.o1" to "Wer vorne geht",
    "q.m13#27.o2" to "Wer das schwerste Gepäck trägt",
    "q.m13#27.o3" to "Wer fotografiert",
    "q.m13#27.e" to "Die Aufgabenverteilung gehört vor den Start. In den ersten dreissig Sekunden nach einem Sturz hat niemand Zeit zu besprechen, wer was tut.",

    // ---------- m17 Hochlager und Materialwirtschaft ----------
    "q.m17#16.p" to "Wozu dient die Materialrotation zwischen Hochlagern?",
    "q.m17#16.o0" to "Jedes Lager hat genau so viel, wie es braucht; niemand hortet, nirgends fehlt es",
    "q.m17#16.o1" to "Um Gewicht zu sparen",
    "q.m17#16.o2" to "Um die Zählung zu erleichtern",
    "q.m17#16.o3" to "Um Vorschriften zu erfüllen",
    "q.m17#16.e" to "Expeditionsmaterial wird abschnittsweise zugeteilt. Ohne Rotationsplan steht man vor dem Gipfelversuch häufig ohne Gas im Hochlager.",

    "q.m17#17.p" to "Wie wird der Brennstoffbedarf im Lager berechnet?",
    "q.m17#17.o0" to "Personen × Tage × Verbrauch pro Person und Tag (Schneeschmelzen ist der grösste Posten)",
    "q.m17#17.o1" to "Nach der Zahl der Gaskartuschen",
    "q.m17#17.o2" to "Nach dem Gewicht",
    "q.m17#17.o3" to "Nach Erfahrung",
    "q.m17#17.e" to "Schneeschmelzen für Trinkwasser ist der grösste Brennstoffposten in der Höhe. Gerechnet wird für kältestes Wetter, nicht für Idealbedingungen.",

    "q.m17#18.p" to "Worauf kommt es beim Verstärken eines Zeltes gegen starken Wind an?",
    "q.m17#18.o0" to "Winkel der Abspannleinen, Fixpunkte auf der Windseite und Beschweren des Schneefangs",
    "q.m17#18.o1" to "Die Farbe des Zeltes",
    "q.m17#18.o2" to "Der Reissverschluss des Innenzeltes",
    "q.m17#18.o3" to "Die Dicke der Bodenplane",
    "q.m17#18.e" to "Zelte versagen meist nicht am Stoff, sondern an einem Fixpunkt. Doppelte Leinen auf der Windseite und Schneeblöcke auf dem Schneefang sind Standard.",

    "q.m17#19.p" to "Was sind Vor- und Nachteil einer Schneehöhle am Hang?",
    "q.m17#19.o0" to "Guter Windschutz und warm; dafür Gefahr von Einsturz und Kohlenmonoxid",
    "q.m17#19.o1" to "Spart das Zelt; dafür zu kalt",
    "q.m17#19.o2" to "Praktisch; dafür verboten",
    "q.m17#19.o3" to "Es gibt kein Risiko",
    "q.m17#19.e" to "Eine Schneehöhle braucht Lüftung und eine belastbare Deckenstärke. Ein Kocher in einer geschlossenen Höhle ist das typische Szenario einer Kohlenmonoxidvergiftung.",

    "q.m17#20.p" to "Wovor ist beim Kochen im Zelt am meisten zu schützen?",
    "q.m17#20.o0" to "Kohlenmonoxidvergiftung und Brand",
    "q.m17#20.o1" to "Feuchtigkeit",
    "q.m17#20.o2" to "Kälte ausserhalb des Sauerstoffmangels",
    "q.m17#20.o3" to "Verformung des Zeltes",
    "q.m17#20.e" to "Kohlenmonoxid ist farb- und geruchlos, die Symptome ähneln der Höhenkrankheit. Lüftung offen halten und möglichst in der Apsis oder draussen kochen.",

    "q.m17#21.p" to "Wie ist mit Abfall im Hochlager umzugehen?",
    "q.m17#21.o0" to "Alles ins Tal tragen, im Hochlager weder vergraben noch verbrennen",
    "q.m17#21.o1" to "Im Schnee vergraben",
    "q.m17#21.o2" to "Verbrennen",
    "q.m17#21.o3" to "Für die nächste Gruppe liegen lassen",
    "q.m17#21.e" to "In grosser Höhe zersetzt sich fast nichts; Vergraben und Verbrennen kommt beim Abschmelzen wieder zum Vorschein. Hinauszutragen ist die einzige regelkonforme Lösung.",

    "q.m17#22.p" to "Wie lässt sich das Schneeschmelzen effizienter gestalten?",
    "q.m17#22.o0" to "Erst etwas Wasser einfüllen, dann Schnee zugeben, mit grosser Flamme arbeiten und Trockenbrennen vermeiden",
    "q.m17#22.o1" to "Den Topf sofort voll Schnee füllen",
    "q.m17#22.o2" to "Mit kleiner Flamme langsam erhitzen",
    "q.m17#22.o3" to "Mit kaltem Wasser schmelzen",
    "q.m17#22.e" to "Trockenbrennen verbrennt den Topfboden und ist sehr unwirtschaftlich. Wasser als Startfüllung plus grosse Flamme spart spürbar Brennstoff und Zeit.",

    "q.m17#23.p" to "Wie sollte die Schlafhöhe bei Hochlagern geplant werden?",
    "q.m17#23.o0" to "Möglichst nach Plan rotieren und nicht mehrere Nächte hintereinander im Hochlager schlafen",
    "q.m17#23.o1" to "Je höher, desto besser",
    "q.m17#23.o2" to "Immer im höchsten Lager schlafen",
    "q.m17#23.o3" to "Beliebig",
    "q.m17#23.e" to "Rotation verbindet Akklimatisierung mit Erholung. Mehrere Nächte im Hochlager sammeln Müdigkeit an und bremsen den gesamten Rhythmus.",
    // ---------- l32 Fixseile und Ankersysteme ----------
    "q.l32#0.p" to "Fixseile werden nach Zweck in drei Klassen geteilt. Welche Gruppe ist richtig?",
    "q.l32#0.o0" to "Handlauf, kurzes Fixseil, Expeditionseinrichtung",
    "q.l32#0.o1" to "Einfachseil, Doppelseil, Zwillingsseil",
    "q.l32#0.o2" to "Dynamisches Seil, statisches Seil, Reepschnur",
    "q.l32#0.o3" to "Oberer, mittlerer, unterer Abschnitt",
    "q.l32#0.e" to "Die drei Klassen stehen für drei Szenarien und drei Standardvorgehen. Wer die Szenarien verwechselt, baut einen Handlauf nach Art eines Fixseils für eine ganze Saison.",

    "q.l32#1.p" to "Welches Seil gehört an ein langes Fixseil?",
    "q.l32#1.o0" to "Statisches Seil (dehnungsarm)",
    "q.l32#1.o1" to "Dynamisches Seil",
    "q.l32#1.o2" to "Reepschnur",
    "q.l32#1.o3" to "Bandschlinge",
    "q.l32#1.e" to "Die Dehnung des dynamischen Seils ist für Stürze gedacht; am Fixseil lässt sie einen «auf und ab federn» und erhöht den Verschleiss.",

    "q.l32#2.p" to "Welcher Durchmesserbereich ist für statische Fixseile üblich?",
    "q.l32#2.o0" to "9–11 mm",
    "q.l32#2.o1" to "5–6 mm",
    "q.l32#2.o2" to "7–8 mm",
    "q.l32#2.o3" to "12–14 mm",
    "q.l32#2.e" to "Zu dünn bedeutet wenig Abriebfestigkeit und glattes Griffgefühl; zu dick steigert Gewicht und Volumen. 9–11 mm ist der übliche Bereich für Expeditionseinrichtungen.",

    "q.l32#3.p" to "Was ist das Problem, wenn zwei Ankerpunkte auf einer gemeinsamen Bandschlinge hängen?",
    "q.l32#3.o0" to "Es ist eine Reihenschaltung, keine Redundanz",
    "q.l32#3.o1" to "Es verschwendet Bandschlinge",
    "q.l32#3.o2" to "Es sieht unschön aus",
    "q.l32#3.o3" to "Es bremst den Seillauf",
    "q.l32#3.e" to "In einer Reihenschaltung lockert der Ausfall eines Punktes das ganze System und die Last springt. Redundanz setzt voraus, dass jeder Punkt eigenständig am Karabiner hängt.",

    "q.l32#4.p" to "Was bedeutet «unabhängig» in den fünf Ankerprüfungen?",
    "q.l32#4.o0" to "Die beiden Ankerpunkte liegen in verschiedenem Fels, an verschiedenen Bäumen oder an verschiedenen Bolts",
    "q.l32#4.o1" to "Die beiden Ankerpunkte liegen nah beieinander",
    "q.l32#4.o2" to "Beide hängen an derselben Bandschlinge",
    "q.l32#4.o3" to "Zwei Klemmkeile in derselben Risslinie",
    "q.l32#4.e" to "Zwei Klemmkeile in derselben Risslinie fallen gemeinsam aus, wenn dieser Felskörper versagt. Unabhängigkeit fragt danach, ob die Versagensursache dieselbe ist.",

    "q.l32#5.p" to "Was prüft der Punkt «Richtung» bei einem Ankerpunkt?",
    "q.l32#5.o0" to "Der Ankerpunkt muss die tatsächliche Lastrichtung aufnehmen können, nicht nur nach unten",
    "q.l32#5.o1" to "Der Ankerpunkt soll zur Aussicht zeigen",
    "q.l32#5.o2" to "Das Seil soll gerade verlaufen",
    "q.l32#5.o3" to "Der Ankerpunkt soll oben liegen",
    "q.l32#5.e" to "Beim Einrichten entstehen seitliche Pendelbewegungen, beim Aufsteigen schwingt man mit. Ein Anker, der nur nach unten gedacht ist, versagt bei Querlast.",

    "q.l32#6.p" to "Wovor ist bei Ankerpunkten im Schnee besonders zu warnen?",
    "q.l32#6.o0" to "Schneefestigkeit und Schmelzrisiko – beim Tauen kann ein ganzer Abschnitt versagen",
    "q.l32#6.o1" to "Der Schnee ist zu weich zum Vergraben",
    "q.l32#6.o2" to "Der Schnee macht das Seil nass",
    "q.l32#6.o3" to "Der Schneeanker ist zu schwer",
    "q.l32#6.e" to "Die Verlässlichkeit eines Schneeankers hängt stark von Temperatur und Tageszeit ab. Ein Anker am Nachmittag beim Tauen ist womöglich ein anderer als am frühen Morgen.",

    "q.l32#7.p" to "Wozu dient der Stopfknoten am Seilende?",
    "q.l32#7.o0" to "Er verhindert, dass das Seilende aus dem Gerät rutscht",
    "q.l32#7.o1" to "Er erleichtert das Aufnehmen des Seils",
    "q.l32#7.o2" to "Er markiert die Länge",
    "q.l32#7.o3" to "Er erhöht die Reibung",
    "q.l32#7.e" to "Rutscht beim Abseilen oder Nachsteigen das Seilende aus dem Gerät, ist die Verbindung weg. Der Stopfknoten ist die billigste und wirksamste Versicherung.",

    "q.l32#8.p" to "Was leistet eine Zwischenumlenkung (re-belay) vor allem?",
    "q.l32#8.o0" to "Sie lässt das Seil glatt folgen und begrenzt Sturz und Abrieb auf einen Abschnitt",
    "q.l32#8.o1" to "Sie erhöht das Gewicht",
    "q.l32#8.o2" to "Sie erleichtert das Fotografieren",
    "q.l32#8.o3" to "Sie ersetzt den Standplatz",
    "q.l32#8.e" to "Ohne Zwischenumlenkung bildet das Seil an Felskanten einen harten Knick: Das Abziehen wird mühsam, der Abrieb sammelt sich, und die Sturzhöhe wächst.",

    "q.l32#9.p" to "Dürfen beim Einrichten Personen unterhalb stehen?",
    "q.l32#9.o0" to "Nein, während oben gearbeitet wird, muss der Bereich darunter frei sein",
    "q.l32#9.o1" to "Ja, um Werkzeug anreichen zu können",
    "q.l32#9.o2" to "Ja, mit Helm",
    "q.l32#9.o3" to "Ja, solange niemand herumalbert",
    "q.l32#9.e" to "Steinschlag ist die wichtigste Verletzungsquelle beim Einrichten. Personen darunter zu lassen heisst, den gefährlichsten Platz den Mitgehenden zuzuweisen.",

    "q.l32#10.p" to "Was muss schon in der Planungsphase des Einrichtens feststehen?",
    "q.l32#10.o0" to "Start und Ende jedes Abschnitts, Umlenkungen und Rückzugspunkte, Seillänge, Befestigungsart",
    "q.l32#10.o1" to "Farbe, Marke, Preis, Gewicht",
    "q.l32#10.o2" to "Wer zuerst geht, wer fotografiert, wer Wasser kocht, wer abrechnet",
    "q.l32#10.o3" to "Wetter, Stimmung, Budget, Urlaubstage",
    "q.l32#10.e" to "Diese vier Punkte entscheiden, ob ein Rückzug überhaupt möglich ist. Ohne Planung direkt ans Seil zu gehen heisst, den Rückzug dem Zufall zu überlassen.",

    "q.l32#11.p" to "Warum müssen Fixseile «regelmässig geprüft und dokumentiert» werden?",
    "q.l32#11.o0" to "Eingerichtete Routen bleiben oft eine ganze Saison hängen; Sonne, Abrieb und Frost-Tau-Wechsel verändern den Seilzustand",
    "q.l32#11.o1" to "Für die Revision",
    "q.l32#11.o2" to "Um Haftung zu verteilen",
    "q.l32#11.o3" to "Das ist nicht nötig",
    "q.l32#11.e" to "Aufgerauter Mantel, Verhärtung und flachgedrückte Stellen sind Ausmusterungssignale. Ohne Aufzeichnung kann niemand sagen, wie viele Tage dieses Seil gehangen hat.",

    "q.l32#12.p" to "Welche Punkte gehören zu den fünf Ankerprüfungen?",
    "q.l32#12.o0" to "Unabhängigkeit",
    "q.l32#12.o1" to "Lastverteilung (gleichmässig)",
    "q.l32#12.o2" to "Richtung",
    "q.l32#12.o3" to "Kantenschutz",
    "q.l32#12.e" to "Der fünfte Punkt ist das Backup. Am leichtesten wird der Kantenschutz übersehen: Eine von einer Felskante angeschnittene Bandschlinge behält nur noch einen Bruchteil ihrer Festigkeit.",

    "q.l32#13.p" to "Welche Befunde sprechen dafür, dass ein Fixseil ausgemustert gehört?",
    "q.l32#13.o0" to "Aufgeraute Stellen am Mantel, der Kern ist fühlbar",
    "q.l32#13.o1" to "Das Seil ist hart und fühlt sich spröde an",
    "q.l32#13.o2" to "Örtlich flachgedrückte Verformung",
    "q.l32#13.o3" to "Die Farbe ist verblasst",
    "q.l32#13.e" to "Die ersten drei sind strukturelle Schäden. Verblassen ist nur optisch – aber der Zusammenhang mit UV-Alterung ist zu beachten.",

    "q.l32#14.p" to "Welche Anforderungen an die Selbstsicherung gelten beim Einrichten?",
    "q.l32#14.o0" to "Zu jedem Zeitpunkt mindestens zwei Verbindungspunkte",
    "q.l32#14.o1" to "Helm tragen",
    "q.l32#14.o2" to "Absperrung oberhalb, Schutz vor Steinschlag",
    "q.l32#14.o3" to "Restseil im Seilsack führen",
    "q.l32#14.e" to "Zusammen ergeben sie die Sicherheit am Arbeitsplatz. Die «zwei Verbindungspunkte» sind die einzige harte Regel; Ausnahme ist nur das direkte Einbinden beim Vorstieg.",

    "q.l32#15.p" to "Auf welchen Ebenen lässt sich die Redundanz eines Fixseilsystems verwirklichen?",
    "q.l32#15.o0" to "Ankerredundanz (zwei unabhängige Punkte)",
    "q.l32#15.o1" to "Verbindungsredundanz (PAS oder Bandschlinge als Backup)",
    "q.l32#15.o2" to "Geräteredundanz (Backup-Klemmknoten)",
    "q.l32#15.o3" to "Farbredundanz (mehrere Farben kaufen)",
    "q.l32#15.e" to "Die drei Ebenen bedeuten: System versagt nicht, Umlasten geht nicht ins Leere, kein Gerät trägt allein. Farbe hat mit Sicherheit nichts zu tun.",

    "q.l32#16.p" to "Bringe den Aufbau eines Fixseilabschnitts in die richtige Reihenfolge.",
    "q.l32#16.o0" to "Start, Ende und Umlenkungen festlegen, Seillänge abschätzen",
    "q.l32#16.o1" to "Ankerpunkte setzen (unabhängig, lastverteilt, mit Backup)",
    "q.l32#16.o2" to "Seil legen und Zwischenumlenkungen setzen",
    "q.l32#16.o3" to "Stopfknoten setzen und Seilzustand dokumentieren",
    "q.l32#16.e" to "Beim Abschätzen Reserve für Knoten und Verbindungen einrechnen – lieber zu lang als zu kurz. Der Stopfknoten kommt zuletzt, darf aber nie fehlen.",

    "q.l32#17.p" to "Einer der Ankerpunkte wirkt zweifelhaft. Wie ist die Reihenfolge des Vorgehens?",
    "q.l32#17.o0" to "Den Abschnitt nicht mehr benutzen und die Personen in sichere Position bringen",
    "q.l32#17.o1" to "Einen unabhängigen Backup-Punkt ergänzen",
    "q.l32#17.o2" to "Die Lastverteilung neu einstellen",
    "q.l32#17.o3" to "Prüfen, dokumentieren, dann über die Fortsetzung entscheiden",
    "q.l32#17.e" to "Erst die Menschen in Sicherheit, dann die technische Behandlung. Umgekehrt wird der Behebungsvorgang selbst zum Unfallort.",

    "q.l32#18.p" to "Wie lautet der richtige Alltagsablauf für ein dauerhaft genutztes Fixseil?",
    "q.l32#18.o0" to "Vor dem Start Ankerpunkte und Seilzustand prüfen",
    "q.l32#18.o1" to "Beim Passieren beide Verbindungen kontrollieren",
    "q.l32#18.o2" to "Beim Abbau Abrieb und Stopfknoten prüfen",
    "q.l32#18.o3" to "Prüfdatum und Befunde festhalten",
    "q.l32#18.e" to "Der Wert dieses Ablaufs liegt darin, die Prüfung zur Gewohnheit zu machen. Ein Fixseil über eine ganze Saison aus dem Gedächtnis zu verwalten geht früher oder später schief.",

    "q.l32#19.p" to "Die Norm für dynamische Seile ist EN ______.",
    "q.l32#19.a0" to "892",
    "q.l32#19.e" to "Dynamisches Seil EN 892 / UIAA 101, statisches Seil EN 1891 / UIAA 110. Beim Einkauf und bei der Prüfung über die Normnummer abgleichen.",

    "q.l32#20.p" to "Für Fixseile ist ein ______ Seil zu verwenden (dynamisch oder statisch).",
    "q.l32#20.a0" to "statisches",
    "q.l32#20.a1" to "statisches Seil",
    "q.l32#20.e" to "Statische Seile sind dehnungsarm und abriebfest und damit für dauerhafte Fixierung geeignet. Die Dehnung eines dynamischen Seils lässt das Fixseil bei jeder Benutzung federn.",

    "q.l32#21.p" to "Beim Einrichten muss am Seilende ein ______ sitzen, damit es nicht aus dem Gerät rutscht.",
    "q.l32#21.a0" to "Stopfknoten",
    "q.l32#21.a1" to "Knoten",
    "q.l32#21.e" to "Das ist der am häufigsten ausgelassene Schritt – und der mit den direktesten Folgen.",

    "q.l32#22.p" to "Der übliche Durchmesserbereich statischer Seile für Expeditionseinrichtungen ist ______–11 mm.",
    "q.l32#22.a0" to "9",
    "q.l32#22.e" to "9–11 mm verbindet Abriebfestigkeit mit vertretbarem Gewicht. Unter 9 mm verschleisst das Seil schnell, über 11 mm wird die Last deutlich.",

    "q.l32#23.p" to "Ordne Fixseiltyp und typisches Szenario einander zu.",
    "q.l32#23.l0" to "Handlauf",
    "q.l32#23.l1" to "Kurzes Fixseil",
    "q.l32#23.l2" to "Expeditionseinrichtung",
    "q.l32#23.l3" to "Zwischenumlenkung",
    "q.l32#23.r0" to "Kurze exponierte Passage, an der man sich festhält",
    "q.l32#23.r1" to "Ein Steilabschnitt oder eine Seillänge, wiederholt auf und ab",
    "q.l32#23.r2" to "Lange Route, viele Seillängen, Lastentransport, ganze Saison",
    "q.l32#23.r3" to "Teilt ein langes Seil und verringert Knick und Abrieb",
    "q.l32#23.e" to "Das Szenario bestimmt den Standard: je länger, je belasteter, je exponierter, desto höher die Anforderungen an Ankerredundanz und Seildokumentation.",

    "q.l32#24.p" to "Ordne Gerät und Normnummer einander zu.",
    "q.l32#24.l0" to "Statisches Seil",
    "q.l32#24.l1" to "Dynamisches Seil",
    "q.l32#24.l2" to "Steigklemme",
    "q.l32#24.l3" to "Klettergurt",
    "q.l32#24.r0" to "EN 1891 / UIAA 110",
    "q.l32#24.r1" to "EN 892 / UIAA 101",
    "q.l32#24.r2" to "EN 567",
    "q.l32#24.r3" to "EN 12277",
    "q.l32#24.e" to "Die Normnummer ist Grundlage für Einkauf und Prüfung – und dafür, zu erkennen, für welche Art von Last ein Gerät überhaupt gebaut wurde.",

    "q.l32#25.p" to "Ordne Ankerproblem und Folge einander zu.",
    "q.l32#25.l0" to "Reihenschaltung",
    "q.l32#25.l1" to "Nur eine Lastrichtung berücksichtigt",
    "q.l32#25.l2" to "Ungeschützte scharfe Kante",
    "q.l32#25.l3" to "Einzelpunkt ohne Backup",
    "q.l32#25.r0" to "Der Ausfall eines Punktes lockert das System und die Last springt",
    "q.l32#25.r1" to "Bei Querlast wird der Anker herausgezogen oder bricht",
    "q.l32#25.r2" to "Die Bandschlinge wird angeschnitten, die Festigkeit sinkt deutlich",
    "q.l32#25.r3" to "Fällt die einzige Verbindung aus, ist der Schutz vollständig weg",
    "q.l32#25.e" to "Vier Probleme, vier Versagensarten. Sie treten oft gemeinsam auf – deshalb wird Punkt für Punkt geprüft und nicht nach Gefühl.",

    "q.l32#26.p" to "Jemand sagt: «Das Seil hängt erst eine Saison, das muss man nicht prüfen.» Was ist die beste Antwort?",
    "q.l32#26.o0" to "Beim Fixseil zählen Exposition und Abrieb, nicht die Länge der Saison",
    "q.l32#26.o1" to "Stimmt, eine Prüfung ist nicht nötig",
    "q.l32#26.o2" to "Einfach eine andere Farbe nehmen",
    "q.l32#26.o3" to "Solange es nicht gerissen ist, ist es in Ordnung",
    "q.l32#26.e" to "Sonne, Frost-Tau-Wechsel und Reibung an Kanten summieren Schäden. Der Prüfzyklus eines Fixseils richtet sich nach der Nutzungsintensität, nicht nach dem Kalender.",

    "q.l32#27.p" to "Nach welchem Prinzip wird die Seillänge beim Einrichten abgeschätzt?",
    "q.l32#27.o0" to "Reserve für Knoten und Verbindungen einrechnen – lieber zu lang als zu kurz",
    "q.l32#27.o1" to "Genau die Abschnittslänge",
    "q.l32#27.o2" to "Je kürzer, desto leichter, desto besser",
    "q.l32#27.o3" to "Nach der Luftlinie auf der Karte",
    "q.l32#27.e" to "Zu kurz macht den ganzen Abschnitt unbrauchbar, zu lang kostet nur etwas Gewicht. Knoten, Verbindungen und Umlenkungen verbrauchen Länge und müssen mitgerechnet werden.",

    "q.l32#28.p" to "Eine Person will ein Fixseil mit seitlichem Pendelbereich passieren. Was ist vorher am wichtigsten zu klären?",
    "q.l32#28.o0" to "Ob die Ankerpunkte Querlast aufnehmen können und ob ein zweiter Verbindungspunkt vorhanden ist",
    "q.l32#28.o1" to "Die Farbe des Seils",
    "q.l32#28.o2" to "Die Seillänge",
    "q.l32#28.o3" to "Das Körpergewicht der Person",
    "q.l32#28.e" to "Ein seitliches Pendeln verwandelt einen «nach unten» gedachten Anker in eine Querlast – genau so werden viele Anker herausgezogen.",

    "q.l32#29.p" to "Warum braucht eine Fixseilroute Rückzugspunkte?",
    "q.l32#29.o0" to "Damit bei Wetterwechsel oder verändertem Zustand der Gruppe ein sicherer Ausstieg innerhalb eines Abschnitts möglich ist",
    "q.l32#29.o1" to "Zum Ausruhen",
    "q.l32#29.o2" to "Zum Lagern von Ausrüstung",
    "q.l32#29.o3" to "Zum Fotografieren",
    "q.l32#29.e" to "Eine lange Route geht nicht jedes Mal bis zum Ende. Der Rückzugspunkt entscheidet, ob es bei Verschlechterung noch eine Option gibt.",

    // ---------- l33 Aufstieg, Knotenpassage und Seilwechsel ----------
    "q.l33#0.p" to "Was gehört nicht zur Standardausrüstung für den Aufstieg am Fixseil?",
    "q.l33#0.o0" to "Abseilgerät (Achter oder Tuber)",
    "q.l33#0.o1" to "Handsteigklemme",
    "q.l33#0.o2" to "Fussstrippe",
    "q.l33#0.o3" to "Backup-Klemmknoten",
    "q.l33#0.e" to "Beim Aufstieg braucht man kein Abseilgerät; es gehört zum Seilwechsel und zum Abseilen. Die Ausrüstungsliste richtet sich nach der aktuellen Tätigkeit – nicht danach, alles anzuhängen.",

    "q.l33#1.p" to "Wie lautet der Merksatz für die Aufstiegsbewegung?",
    "q.l33#1.o0" to "Aufstehen, setzen, schieben",
    "q.l33#1.o1" to "Ziehen, stützen, springen",
    "q.l33#1.o2" to "Hocken, springen, greifen",
    "q.l33#1.o3" to "Schieben, ziehen, setzen",
    "q.l33#1.e" to "Beide Füsse in die Fussstrippe, aufstehen, Schwerpunkt hebt sich, Bruststeigklemme schieben, setzen, Handsteigklemme schieben. Mit dem richtigen Rhythmus spart man die Hälfte der Kraft.",

    "q.l33#2.p" to "Wo soll der Schwerpunkt beim Aufsteigen liegen?",
    "q.l33#2.o0" to "Nah am Seil",
    "q.l33#2.o1" to "Möglichst weit nach aussen",
    "q.l33#2.o2" to "Seitlich pendelnd",
    "q.l33#2.o3" to "Möglichst weit nach hinten gelehnt",
    "q.l33#2.e" to "Ein nach aussen pendelnder Schwerpunkt bringt Querlast auf die Steigklemme, sie kann abspringen, und der Kraftaufwand steigt stark. Am Seil zu bleiben ist Sicherheit und Effizienz zugleich.",

    "q.l33#3.p" to "Was ist die Ausnahme von der Regel der zwei Verbindungen?",
    "q.l33#3.o0" to "Das direkte Einbinden beim Vorstieg",
    "q.l33#3.o1" to "Bei gutem Wetter",
    "q.l33#3.o2" to "Tagsüber",
    "q.l33#3.o3" to "Bei kurzen Strecken",
    "q.l33#3.e" to "Beim Vorstieg ist die Person selbst Teil des Systems und kann keinen zweiten Punkt einhängen. Ansonsten sollten immer zwei unabhängige Verbindungen bestehen.",

    "q.l33#4.p" to "Was ist die erste Regel bei der Knotenpassage?",
    "q.l33#4.o0" to "Erst die neue Verbindung aufbauen, dann die alte lösen",
    "q.l33#4.o1" to "Erst die alte lösen, dann die neue aufbauen",
    "q.l33#4.o2" to "Beides gleichzeitig bedienen",
    "q.l33#4.o3" to "Den Knoten einfach überspringen",
    "q.l33#4.e" to "Die umgekehrte Reihenfolge erzeugt kurzzeitig einen Zustand mit nur einem Punkt oder ganz ohne Punkt. Die Knotenpassage ist im Kern ein kontrolliertes Umlasten im System.",

    "q.l33#5.p" to "Dürfen bei der Knotenpassage beide Steigklemmen gleichzeitig vom Seil?",
    "q.l33#5.o0" to "Nein, zu jedem Zeitpunkt muss mindestens eine am Seil hängen und Last tragen",
    "q.l33#5.o1" to "Ja, wenn es schnell geht",
    "q.l33#5.o2" to "Ja, wenn jemand zusieht",
    "q.l33#5.o3" to "Ja, bei kurzen Knoten",
    "q.l33#5.e" to "Beide gleichzeitig zu lösen bedeutet den vollständigen Verlust der Aufstiegsverbindung. Lieber eine Minute mehr für den Umbau als ein einziges Risiko.",

    "q.l33#6.p" to "Was ist der erste Schritt beim Übergang vom Aufsteigen zum Abseilen?",
    "q.l33#6.o0" to "Sich mit PAS oder Bandschlinge in den Ankerpunkt einhängen",
    "q.l33#6.o1" to "Zuerst die Handsteigklemme lösen",
    "q.l33#6.o2" to "Zuerst das Abseilgerät montieren",
    "q.l33#6.o3" to "Zuerst die Bruststeigklemme öffnen",
    "q.l33#6.e" to "Erst eine vom Aufstiegssystem unabhängige Verbindung schaffen, dann lässt sich das alte System lösen. Das ist der gemeinsame Ausgangspunkt aller Wechselmanöver.",

    "q.l33#7.p" to "Was muss nach dem Montieren des Abseilgeräts und vor dem Lösen der Steigklemme geschehen?",
    "q.l33#7.o0" to "Das Abseilgerät muss Last bekommen und getestet werden",
    "q.l33#7.o1" to "Der Klettergurt wird geöffnet",
    "q.l33#7.o2" to "Das Seil wird aufgenommen",
    "q.l33#7.o3" to "Der Helm wird abgenommen",
    "q.l33#7.e" to "Der Lasttest ist die einzige Möglichkeit zu bestätigen, dass das neue System das Körpergewicht wirklich trägt. Wer diesen Schritt überspringt, kann nach dem Lösen des alten Systems direkt stürzen.",

    "q.l33#8.p" to "Welche Aufgabe hat der Reibungsknoten (Backup) über dem Abseilgerät?",
    "q.l33#8.o0" to "Er blockiert bei einem Griffverlust automatisch und wirkt als unabhängiges Backup",
    "q.l33#8.o1" to "Er erhöht die Abseilgeschwindigkeit",
    "q.l33#8.o2" to "Er schont das Seil",
    "q.l33#8.o3" to "Er markiert die Position",
    "q.l33#8.e" to "Der Reibungsknoten klemmt, sobald die Bremshand öffnet. Er ist die einzige Absicherung für den gefährlichsten Moment: die geöffnete Hand.",

    "q.l33#9.p" to "Wozu wird vor dem Abseilen ein Stopfknoten am Seilende gesetzt?",
    "q.l33#9.o0" to "Damit das Seilende nicht aus dem Abseilgerät rutscht",
    "q.l33#9.o1" to "Zum leichteren Aufnehmen des Seils",
    "q.l33#9.o2" to "Zur Markierung der Seillänge",
    "q.l33#9.o3" to "Zur Verringerung des Abriebs",
    "q.l33#9.e" to "Reicht die Seillänge nicht, bedeutet ein durchgerutschtes Seilende den sofortigen Verlust der Bremsung. Der Stopfknoten gehört zur Pflichtprüfung vor jedem Abseilen.",

    "q.l33#10.p" to "Wie lautet die richtige Reihenfolge beim Passieren einer Zwischenumlenkung?",
    "q.l33#10.o0" to "Erst in den Umlenkpunkt einhängen, dann die Steigklemme umsetzen, zuletzt die Ankerverbindung lösen",
    "q.l33#10.o1" to "Erst die Steigklemme umsetzen, dann einhängen",
    "q.l33#10.o2" to "Einfach durchfahren, ohne einzuhängen",
    "q.l33#10.o3" to "Erst die Ankerverbindung lösen, dann umsetzen",
    "q.l33#10.e" to "An der Umlenkung ist das Seil vom Karabiner geführt: wenig Platz, und die Bewegung wird leicht unsauber. Erst eine unabhängige Verbindung schafft Fehlertoleranz.",

    "q.l33#11.p" to "Was ist bei einem klemmenden Seil zu tun?",
    "q.l33#11.o0" to "Zuerst den Zugwinkel ändern oder seitlich ziehen, nicht direkt unter dem Seil reissen",
    "q.l33#11.o1" to "Direkt darunter stehen und kräftig ziehen",
    "q.l33#11.o2" to "Mit dem Körpergewicht ruckartig ziehen",
    "q.l33#11.o3" to "Das Seil durchschneiden",
    "q.l33#11.e" to "Direkt darunter zu ziehen bringt einen ins Ziel von zurückschnellendem Seil oder Steinschlag und kann den Knoten noch fester setzen. Den Winkel zu ändern ist der wirksamste erste Schritt.",

    "q.l33#12.p" to "Beim Abziehen nach dem Doppelseilabseilen: an welcher Seite ziehen?",
    "q.l33#12.o0" to "An der Seite mit geringerer Reibung",
    "q.l33#12.o1" to "An der Seite mit höherer Reibung",
    "q.l33#12.o2" to "Egal welche Seite",
    "q.l33#12.o3" to "An beiden Seiten gleichzeitig",
    "q.l33#12.e" to "Die Seite mit weniger Reibung lässt sich leichter abziehen und schont den Mantel. Voraussetzung: Stopfknoten gesetzt und nichts eingehängt.",

    "q.l33#13.p" to "Was gehört beim Aufstieg am Fixseil zwingend an den Mann oder die Frau?",
    "q.l33#13.o0" to "Hand- und Bruststeigklemme (oder ein zweiter Klemmknoten)",
    "q.l33#13.o1" to "Fussstrippe",
    "q.l33#13.o2" to "Backup-Klemmknoten und PAS",
    "q.l33#13.o3" to "Helm",
    "q.l33#13.e" to "Diese vier bilden das vollständige Aufstiegs- und Backupsystem. Fehlt eines, ist man bei Knotenpassage und Seilwechsel zum Ein-Punkt-Betrieb gezwungen.",

    "q.l33#14.p" to "Welche Fehler sind beim Seilwechsel am häufigsten?",
    "q.l33#14.o0" to "Erst das alte System lösen, dann das neue aufbauen",
    "q.l33#14.o1" to "Die Steigklemme lösen, ohne das Abseilgerät auf Last getestet zu haben",
    "q.l33#14.o2" to "Beide Steigklemmen gleichzeitig lösen",
    "q.l33#14.o3" to "Vor dem Seilwechsel in den Ankerpunkt einhängen",
    "q.l33#14.e" to "Die ersten drei sind Reihenfolgefehler. Der vierte Punkt ist genau das richtige Vorgehen – das Einhängen dient dazu, die ersten drei Fehler zu vermeiden.",

    "q.l33#15.p" to "Welche Prüfungen gehören vor das Abseilen?",
    "q.l33#15.o0" to "Einfädelrichtung des Abseilgeräts korrekt",
    "q.l33#15.o1" to "Reibungsknoten als Backup gesetzt und wirksam",
    "q.l33#15.o2" to "Stopfknoten am Seilende gesetzt",
    "q.l33#15.o3" to "Seillänge reicht bis zum nächsten Stand",
    "q.l33#15.e" to "Fehlt einer dieser Punkte, kann die Kontrolle verloren gehen. Die Prüfgruppe muss vollständig abgeschlossen sein, bevor die Sicherung gelöst wird.",

    "q.l33#16.p" to "Welche Mittel können bei der Knotenpassage als «neue Verbindung» dienen?",
    "q.l33#16.o0" to "PAS oder Bandschlinge oberhalb des Knotens einhängen",
    "q.l33#16.o1" to "In einen nahen Ankerpunkt einhängen",
    "q.l33#16.o2" to "Oberhalb eine zweite Steigklemme setzen",
    "q.l33#16.o3" to "Mit der Hand das Seil greifen",
    "q.l33#16.e" to "Mit der Hand zu greifen ist keine Verbindung – sobald die Hand öffnet, ist sie weg. Die ersten drei schaffen einen vom alten System unabhängigen Lastpunkt.",

    "q.l33#17.p" to "Bringe die Knotenpassage im Aufstieg in die richtige Reihenfolge.",
    "q.l33#17.o0" to "Vor dem Knoten langsamer werden, Lage des Knotens und den Seilabschnitt darüber prüfen",
    "q.l33#17.o1" to "Mit PAS oder Bandschlinge oberhalb des Knotens oder an einen nahen Anker einhängen",
    "q.l33#17.o2" to "Oberhalb eine zweite Steigklemme oder einen Klemmknoten setzen und aufstehen, um das Gewicht zu verlagern",
    "q.l33#17.o3" to "Die untere Steigklemme lösen und oberhalb des Knotens wieder setzen",
    "q.l33#17.o4" to "Prüfen, dass die neue Verbindung Last trägt, dann das PAS-Backup lösen",
    "q.l33#17.e" to "Der Kern der fünf Schritte ist «immer einen Punkt mehr». Fehlt ein Schritt, entsteht ein Moment mit nur einem Lastpunkt oder ganz ohne Verbindung.",

    "q.l33#18.p" to "Bringe den Übergang vom Aufsteigen zum Abseilen in die richtige Reihenfolge.",
    "q.l33#18.o0" to "In den Ankerpunkt einhängen (PAS oder Bandschlinge)",
    "q.l33#18.o1" to "Abseilgerät montieren und das Seil korrekt einfädeln",
    "q.l33#18.o2" to "Das Abseilgerät auf Last bringen und testen",
    "q.l33#18.o3" to "Handsteigklemme lösen, Bruststeigklemme oder Backup-Klemmknoten behalten",
    "q.l33#18.o4" to "Die andere Steigklemme lösen und prüfen, dass Abseilgerät und Backup funktionieren",
    "q.l33#18.o5" to "PAS lösen und mit dem Abseilen beginnen",
    "q.l33#18.e" to "Die Reihenfolge ist fest und wird nicht spontan geändert. Jeder Schritt sichert, dass mindestens eine verlässliche Verbindung besteht.",

    "q.l33#19.p" to "Bringe den Übergang vom Abseilen zum Aufsteigen in die richtige Reihenfolge.",
    "q.l33#19.o0" to "Über dem Abseilgerät einen Klemmknoten oder eine Steigklemme setzen und am Gurt einhängen",
    "q.l33#19.o1" to "Aufstehen und das Gewicht auf den Klemmknoten verlagern",
    "q.l33#19.o2" to "Eine zweite Steigklemme oder Fussstrippe setzen und Last prüfen",
    "q.l33#19.o3" to "Das Abseilgerät abnehmen",
    "q.l33#19.o4" to "Mit dem Aufstieg beginnen",
    "q.l33#19.e" to "Entscheidend ist der dritte Schritt: Das neue System muss bereits Last tragen, bevor das Abseilgerät entfernt werden darf.",

    "q.l33#20.p" to "Bringe die Knotenpassage beim Abseilen in die richtige Reihenfolge.",
    "q.l33#20.o0" to "Oberhalb des Knotens mit PAS in den Knoten oder einen Ankerpunkt einhängen und ein Backup schaffen",
    "q.l33#20.o1" to "Das Abseilgerät unter den Knoten setzen, straffen und auf Last prüfen",
    "q.l33#20.o2" to "PAS lösen und weiter abseilen",
    "q.l33#20.e" to "Lässt sich ein dicker Knoten nicht direkt passieren, wird zuerst der Backup-Klemmknoten unter den Knoten gesetzt und dann das Gerät – zwischen beiden Umsetzungen besteht immer eine verlässliche Verbindung.",

    "q.l33#21.p" to "Beim Aufstieg am Fixseil sind zu jedem Zeitpunkt ______ unabhängige Verbindungspunkte zu halten.",
    "q.l33#21.a0" to "2",
    "q.l33#21.a1" to "zwei",
    "q.l33#21.e" to "Zwei Verbindungen sind die harte Regel der Fixseilarbeit. Die einzige Ausnahme ist das direkte Einbinden beim Vorstieg.",

    "q.l33#22.p" to "Beim Übergang vom Aufsteigen zum Abseilen muss zuerst in den ______ eingehängt werden, dann werden die Steigklemmen gelöst.",
    "q.l33#22.a0" to "Ankerpunkt",
    "q.l33#22.a1" to "Standplatz",
    "q.l33#22.a2" to "Umlenkpunkt",
    "q.l33#22.e" to "Erst eine vom alten System unabhängige Verbindung zu bekommen ist der Ausgangspunkt aller Wechselmanöver.",

    "q.l33#23.p" to "Der Backup-Reibungsknoten über dem Abseilgerät ist häufig ein Prusik oder ein ______.",
    "q.l33#23.a0" to "Autoblock",
    "q.l33#23.a1" to "Franzosenknoten",
    "q.l33#23.a2" to "Reibungsknoten",
    "q.l33#23.e" to "Beide blockieren beim Öffnen der Hand. Falsch herum oder in falscher Länge montiert versagen sie, deshalb muss der Aufbau bis zur Automatik sitzen.",

    "q.l33#24.p" to "Ordne Vorgang und Kernprinzip einander zu.",
    "q.l33#24.l0" to "Knotenpassage",
    "q.l33#24.l1" to "Passieren einer Umlenkung",
    "q.l33#24.l2" to "Aufstieg zu Abseilen",
    "q.l33#24.l3" to "Abseilen zu Aufstieg",
    "q.l33#24.r0" to "Erst die neue Verbindung, dann die alte lösen",
    "q.l33#24.r1" to "Erst in den Ankerpunkt einhängen, dann das Gerät umsetzen",
    "q.l33#24.r2" to "Einhängen, Gerät montieren, testen, Steigklemme lösen",
    "q.l33#24.r3" to "Erst wenn das neue System Last trägt, das Abseilgerät entfernen",
    "q.l33#24.e" to "Die gemeinsame Struktur aller vier Vorgänge ist Aufbauen, Umlasten, Abbauen. Die Struktur zu merken ist vergessensfester als die Schrittfolge.",

    "q.l33#25.p" to "Ordne die Prüfliste ABCDE ihren Inhalten zu.",
    "q.l33#25.l0" to "A – Ankerpunkte",
    "q.l33#25.l1" to "B – Backup",
    "q.l33#25.l2" to "C – Verbindungen",
    "q.l33#25.l3" to "E – Ausstieg",
    "q.l33#25.r0" to "Zwei unabhängige Punkte, lastverteilt, richtige Lastrichtung, Kanten geschützt",
    "q.l33#25.r1" to "PAS oder Klemmknoten vorhanden, jedes Gerät mit eigenem Backup",
    "q.l33#25.r2" to "Karabiner verschlossen, Knoten festgezogen, Stopfknoten am Seilende",
    "q.l33#25.r3" to "Nächster Rückzugspunkt bekannt, Seillänge reicht, Kommunikation geklärt",
    "q.l33#25.e" to "Der Wert dieser Liste liegt darin, sie vor jedem Einstieg durchzugehen. Sie ersetzt kein Urteil, verhindert aber die meisten groben Fehler.",

    "q.l33#26.p" to "Jemand will bei der Knotenpassage «eine Steigklemme zuerst lösen und die andere gleich danach setzen». Was ist zu sagen?",
    "q.l33#26.o0" to "Zuerst muss eine PAS- oder Ankerverbindung stehen; eine Phase ohne Verbindung ist nicht zulässig",
    "q.l33#26.o1" to "Hauptsache schnell",
    "q.l33#26.o2" to "Tagsüber ist das in Ordnung",
    "q.l33#26.o3" to "Bei kurzen Knoten ist das in Ordnung",
    "q.l33#26.e" to "«Gleich danach» bedeutet bei einem Griffverlust null Fehlertoleranz. Die Toleranz der Knotenpassage entsteht nur durch eine dritte Verbindung.",

    "q.l33#27.p" to "An einer Umlenkung muss das Seil aus dem Karabiner genommen und wieder eingelegt werden. Wie ist vorzugehen?",
    "q.l33#27.o0" to "Erst in den Ankerpunkt einhängen, dann am Seil arbeiten, zuletzt das Backup lösen",
    "q.l33#27.o1" to "Erst das Seil herausnehmen, dann einhängen",
    "q.l33#27.o2" to "Jemanden das Seil halten lassen",
    "q.l33#27.o3" to "Einfach den Karabiner öffnen",
    "q.l33#27.e" to "Im Moment des Herausnehmens hängt man womöglich vollständig an der alten Verbindung. Erst eine unabhängige Verbindung macht die Arbeit sinnvoll.",

    "q.l33#28.p" to "Warum gilt der Seilwechsel als der unfallträchtigste Teil der Fixseilarbeit?",
    "q.l33#28.o0" to "Weil dabei zwischen dem Lösen des alten und dem Aufbauen des neuen Systems umgelastet wird – das Fehlertoleranzfenster ist am kleinsten",
    "q.l33#28.o1" to "Weil viel Ausrüstung nötig ist",
    "q.l33#28.o2" to "Weil es anstrengend ist",
    "q.l33#28.o3" to "Weil zwei Personen nötig sind",
    "q.l33#28.e" to "Die Knotenpassage fügt nur einen Punkt hinzu, der Seilwechsel tauscht das ganze System. Jeder Reihenfolgefehler führt direkt zum Verlust der Verbindung.",
    // ---------- l39 Führung und Rollen in der Gruppe ----------
    "q.l39#0.p" to "Wie ist Führung am treffendsten definiert?",
    "q.l39#0.o0" to "Verhalten, das andere beeinflusst und die Gruppe dazu bringt, ein Ziel gemeinsam erreichen zu wollen",
    "q.l39#0.o1" to "Was Personen mit Titel sagen",
    "q.l39#0.o2" to "Wer die beste Kondition hat, führt",
    "q.l39#0.o3" to "Wer die längste Erfahrung hat, entscheidet",
    "q.l39#0.e" to "Führt man Führung als Verhalten und nicht als Position auf, entstehen mehr Menschen, die etwas ansprechen – und das ist Teil der Sicherheitsreserve.",

    "q.l39#1.p" to "Wie teilen sich harte und weiche Fähigkeiten auf?",
    "q.l39#1.o0" to "Harte Fähigkeiten entscheiden, ob man es kann; weiche Fähigkeiten entscheiden, ob die Gruppe es gemeinsam tun will",
    "q.l39#1.o1" to "Harte Fähigkeiten sind wichtiger",
    "q.l39#1.o2" to "Weiche Fähigkeiten sind nur Höflichkeit",
    "q.l39#1.o3" to "Beide haben nichts miteinander zu tun",
    "q.l39#1.e" to "Technisch können, aber die Gruppe führt nicht aus – das ist wie nicht gekonnt. Im Hochgebirge entscheiden weiche Fähigkeiten oft über die Umsetzungsrate.",

    "q.l39#2.p" to "Was sind die «drei Ebenen der Verantwortung»?",
    "q.l39#2.o0" to "Verhalten, Denken, Fühlen",
    "q.l39#2.o1" to "Planen, Ausführen, Nachbesprechen",
    "q.l39#2.o2" to "Leitung, Co-Leitung, Teilnehmende",
    "q.l39#2.o3" to "Aufstieg, Gipfel, Abstieg",
    "q.l39#2.e" to "Nur das Verhalten zu betrachten lässt Beurteilungsweise und emotionalen Zustand aus. Bei vielen wiederkehrenden Problemen liegt die Ursache in der zweiten und dritten Ebene.",

    "q.l39#3.p" to "Was sagt das Eisbergmodell des Konflikts?",
    "q.l39#3.o0" to "Über Wasser steht die Position, unter Wasser das Bedürfnis",
    "q.l39#3.o1" to "Konflikte kommen immer aus dem Charakter",
    "q.l39#3.o2" to "Konflikte sind unlösbar",
    "q.l39#3.o3" to "Schweigen bedeutet, es gibt keinen Konflikt",
    "q.l39#3.e" to "«Ich muss auf den Gipfel» ist eine Position; darunter steht vielleicht «ich will die anderen nicht enttäuschen». Erst wenn das Bedürfnis angesprochen wird, bewegt sich die Position.",

    "q.l39#4.p" to "Worin liegt das Risiko des Expertenhalos?",
    "q.l39#4.o0" to "Selbstsicherheit und professionelle Ausrüstung werden für Können gehalten, und niemand wagt, einen offensichtlichen Fehler zu hinterfragen",
    "q.l39#4.o1" to "Experten sind zu teuer",
    "q.l39#4.o2" to "Experten sind nicht folgsam",
    "q.l39#4.o3" to "Experten haben schlechte Kondition",
    "q.l39#4.e" to "Der Halo unterdrückt Widerspruch. Der gefährlichste Zustand in einer Gruppe ist nicht, dass niemand etwas weiss, sondern dass niemand «Moment, hier stimmt etwas nicht» sagt.",

    "q.l39#5.p" to "Was ist die wichtigste Aufgabe von Mitgehenden?",
    "q.l39#5.o0" to "Fragen stellen, Rückmeldung geben und klar «Stopp» sagen, wenn gestoppt werden muss",
    "q.l39#5.o1" to "Vollständig gehorchen",
    "q.l39#5.o2" to "Nicht zur Last fallen",
    "q.l39#5.o3" to "Schweigen",
    "q.l39#5.e" to "«Stopp» ist eine Befugnis jeder Person, kein Vorrecht der Tourenleitung. Das muss vor dem Start ausdrücklich so vergeben werden.",

    "q.l39#6.p" to "Wann wird die Umkehrzeit (turnaround time) festgelegt?",
    "q.l39#6.o0" to "Vor dem Start, und die ganze Gruppe kennt sie",
    "q.l39#6.o1" to "Kurz vor dem Gipfel",
    "q.l39#6.o2" to "Nach Gefühl",
    "q.l39#6.o3" to "Von der schnellsten Person",
    "q.l39#6.e" to "Am Berg, unter Müdigkeit und Zieldruck, wird eine Frist fast zwangsläufig verschoben. Nur eine vor dem Start gesetzte Frist bindet.",

    "q.l39#7.p" to "Wie zeigt sich der Missbrauch der Rolle durch eine Tourenleitung typisch?",
    "q.l39#7.o0" to "Die Position überschreibt das Urteil, und Widerspruch wird als Ungehorsam gewertet",
    "q.l39#7.o1" to "Meinungen anhören",
    "q.l39#7.o2" to "Entscheidungsgrundlagen offenlegen",
    "q.l39#7.o3" to "Eigene Unsicherheit zugeben",
    "q.l39#7.e" to "Die direkte Folge von Unterdrückung ist, dass Informationen nicht mehr nach oben kommen. Die wichtigsten Eingaben einer Leitung kommen gerade von denen, die etwas sagen.",

    "q.l39#8.p" to "Jemand in der Gruppe schweigt dauerhaft. Was ist die wahrscheinlichste Ursache?",
    "q.l39#8.o0" to "Die Person glaubt, es nütze nichts, oder fürchtet um die Beziehung",
    "q.l39#8.o1" to "Die Person hat keine Meinung",
    "q.l39#8.o2" to "Fehlende Kondition",
    "q.l39#8.o3" to "Die Person versteht nicht",
    "q.l39#8.e" to "Schweigen ist meist das Ergebnis zu hoher Kosten für das Sprechen. Die Leitung sollte diese Kosten senken, indem sie zum Beispiel die Jüngsten zuerst fragt.",

    "q.l39#9.p" to "Was ist meist der erste Schritt zur Konfliktlösung?",
    "q.l39#9.o0" to "Vertrauen aufbauen: die andere Person zuerst spüren lassen, dass sie gehört wird",
    "q.l39#9.o1" to "Argumentieren",
    "q.l39#9.o2" to "Abstimmen",
    "q.l39#9.o3" to "Personen austauschen",
    "q.l39#9.e" to "Ohne Vertrauen wird Argumentieren als Vorwurf gehört. Erst die Emotion aufnehmen, dann über Fakten und Lösungen sprechen.",

    "q.l39#10.p" to "Wenn «das Ziel erreichen» und «alle kommen sicher zurück» kollidieren, was hat Vorrang?",
    "q.l39#10.o0" to "Die Sicherheit; das Ziel lässt sich ein anderes Mal erreichen",
    "q.l39#10.o1" to "Das Ziel",
    "q.l39#10.o2" to "Eine Abstimmung entscheidet",
    "q.l39#10.o3" to "Wer zahlt, entscheidet",
    "q.l39#10.e" to "Das Ziel ist wiederholbar, Menschen nicht. In kommerziellen Teams wird dieser Grundsatz besonders leicht durch Gewinndruck verbogen.",

    "q.l39#11.p" to "Was gehört zu den weichen Fähigkeiten?",
    "q.l39#11.o0" to "Entscheidungsgrundlagen klar benennen",
    "q.l39#11.o1" to "Unter Druck im Gespräch bleiben",
    "q.l39#11.o2" to "Schweigende aktiv nach ihrer Meinung fragen",
    "q.l39#11.o3" to "Am schnellsten auf dem Gipfel sein",
    "q.l39#11.e" to "Die ersten drei betreffen alle den Fluss von Informationen. Schnelligkeit ist Können, nicht Führung.",

    "q.l39#12.p" to "Was senkt das Risiko des Expertenhalos?",
    "q.l39#12.o0" to "Neue im Team ermutigen, Fragen zu stellen",
    "q.l39#12.o1" to "Bei Entscheidungen die Begründung nennen",
    "q.l39#12.o2" to "Eine Person bestimmen, die gezielt Gegenposition bezieht",
    "q.l39#12.o3" to "Nur die Erfahrensten sprechen lassen",
    "q.l39#12.e" to "Die ersten drei schaffen Legitimität für Widerspruch. Der vierte Punkt ist genau der Verstärker des Halos.",

    "q.l39#13.p" to "Was ist legitimes Verhalten von Mitgehenden?",
    "q.l39#13.o0" to "Eine abweichende Meinung äussern",
    "q.l39#13.o1" to "Eine Begründung für eine Entscheidung verlangen",
    "q.l39#13.o2" to "Weitergehen verweigern, wenn man es für unsicher hält",
    "q.l39#13.o3" to "Sich privat beschweren, aber nichts sagen",
    "q.l39#13.e" to "Private Beschwerde ändert keine Entscheidung, sie sammelt nur Misstrauen. Die ersten drei sind konstruktiver Ungehorsam.",

    "q.l39#14.p" to "Bringe die Behandlung eines Konflikts in die richtige Reihenfolge.",
    "q.l39#14.o0" to "Die andere Person ausreden lassen und zusammenfassen, was man gehört hat",
    "q.l39#14.o1" to "Position und Bedürfnis unterscheiden",
    "q.l39#14.o2" to "Optionen anbieten und jeweils den Preis benennen",
    "q.l39#14.o3" to "Einigung erzielen und zur Bestätigung wiederholen",
    "q.l39#14.e" to "Entscheidend ist der zweite Schritt: Wird das Bedürfnis nicht erkannt, bleibt die Lösung ein «jeder gibt etwas nach» und kommt bald wieder.",

    "q.l39#15.p" to "Bringe den Ablauf einer Entscheidung mit hohem Risiko in die richtige Reihenfolge.",
    "q.l39#15.o0" to "Ziel und nicht verhandelbare Grenzen festlegen",
    "q.l39#15.o1" to "Optionen und ihre jeweiligen Kosten auflisten",
    "q.l39#15.o2" to "Wahrscheinlichkeit und Ausmass der Folgen bewerten",
    "q.l39#15.o3" to "Umkehrzeit vorab setzen und einhalten",
    "q.l39#15.o4" to "Aufgrund neuer Informationen korrigieren",
    "q.l39#15.e" to "Das ist das Gerüst eines neunstufigen Verfahrens. Der eigentliche Wert liegt im vierten Schritt: aus «wann müssen wir umkehren» wird vorab eine Zahl.",

    "q.l39#16.p" to "Die vorab festgelegte Umkehrzeit heisst auf Englisch ______ time.",
    "q.l39#16.a0" to "turnaround",
    "q.l39#16.e" to "Sie ist das Werkzeug, um aus Entschlossenheit eine Regel zu machen. Nur aufgeschrieben und ausgesprochen bindet sie.",

    "q.l39#17.p" to "Die drei Ebenen der Verantwortung sind Verhalten, Denken und ______.",
    "q.l39#17.a0" to "Fühlen",
    "q.l39#17.a1" to "Gefühl",
    "q.l39#17.e" to "Am leichtesten übersehen wird die Ebene des Fühlens – und sie ist meist das erste Signal, wenn etwas schiefgeht.",

    "q.l39#18.p" to "Ordne Rolle und Kernaufgabe einander zu.",
    "q.l39#18.l0" to "Tourenleitung",
    "q.l39#18.l1" to "Co-Leitung / Bergführer",
    "q.l39#18.l2" to "Teilnehmende",
    "q.l39#18.l3" to "Sicherheitsbeobachter",
    "q.l39#18.r0" to "Ziel und Grenzen setzen und Entscheidungen nachvollziehbar machen",
    "q.l39#18.r1" to "Technisch arbeiten und Informationen aus dem Gelände zurückmelden",
    "q.l39#18.r2" to "Fragen, Rückmeldung geben, notfalls Stopp sagen",
    "q.l39#18.r3" to "Nur die Umgebungsrisiken beobachten und nicht in die Arbeit eingreifen",
    "q.l39#18.e" to "Die vier Rollen ergeben Information, Ausführung und Gegengewicht. Fehlt das Gegengewicht, wird die Entscheidung zur Ein-Mann-Sache.",

    "q.l39#19.p" to "Ordne das Konfliktverhalten dem Bedürfnis darunter zu.",
    "q.l39#19.l0" to "«Ich muss da unbedingt rauf»",
    "q.l39#19.l1" to "«Egal, entscheidet ihr»",
    "q.l39#19.l2" to "«Mir geht es gut»",
    "q.l39#19.l3" to "«Der bremst uns immer aus»",
    "q.l39#19.r0" to "Angst, vor den anderen schlecht dazustehen; braucht Anerkennung",
    "q.l39#19.r1" to "Will keine Verantwortung für die Entscheidung; braucht Absicherung",
    "q.l39#19.r2" to "Will niemandem zur Last fallen; braucht Zuwendung",
    "q.l39#19.r3" to "Sorge um den Fortschritt; braucht Verlässlichkeit",
    "q.l39#19.e" to "Vier Verhaltensweisen, vier Bedürfnisse. Erst wenn das Bedürfnis angesprochen wird, kann sich das Verhalten ändern.",

    "q.l39#20.p" to "Die erfahrenste Person sagt «diese Route bin ich gegangen, kein Problem», die Karte zeigt aber oben eine Eisfallzone. Was ist zu tun?",
    "q.l39#20.o0" to "Gemeinsam Karte und Gelände prüfen und die Erfahrung an den Fakten kalibrieren",
    "q.l39#20.o1" to "Einfach glauben",
    "q.l39#20.o2" to "Vor allen widersprechen",
    "q.l39#20.o3" to "Getrennt gehen",
    "q.l39#20.e" to "Erfahrung ist eine wertvolle Eingabe, kein Ergebnis. Mit Karte und Gelände zu kalibrieren respektiert die Person, ohne blind zu folgen.",

    "q.l39#21.p" to "Eine Person sagt wiederholt «mir ist alles recht». Was ist am sinnvollsten?",
    "q.l39#21.o0" to "Konkrete Optionen zur Auswahl geben statt offener Fragen",
    "q.l39#21.o1" to "Es wörtlich nehmen",
    "q.l39#21.o2" to "Nicht mehr fragen",
    "q.l39#21.o3" to "Selbst entscheiden und hinterher informieren",
    "q.l39#21.e" to "«Alles recht» heisst oft «ich will die Folgen der Wahl nicht tragen». Konkrete Optionen senken die Kosten des Sprechens und bringen die Information hervor.",

    "q.l39#22.p" to "Die Leitung entscheidet für den Rückzug. Was muss vor allem klar gesagt werden?",
    "q.l39#22.o0" to "Die Grundlage (was gesehen wurde), die Grenze (unter welchen Bedingungen neu bewertet wird) und das weitere Vorgehen",
    "q.l39#22.o1" to "Nur, dass es nicht anders geht",
    "q.l39#22.o2" to "Nur Gefühle",
    "q.l39#22.o3" to "Nichts erklären",
    "q.l39#22.e" to "Eine Begründung verwandelt Gehorsam in Verständnis. Wer versteht, liefert beim nächsten Mal von selbst Informationen.",

    "q.l39#23.p" to "Warum ist «per Abstimmung über den Weiteraufstieg entscheiden» fachlich unzuverlässig?",
    "q.l39#23.o0" to "Der Mehrheit fehlen womöglich die Informationen für das Urteil, und Druck verzerrt die Aussagen",
    "q.l39#23.o1" to "Weil Abstimmen zu lange dauert",
    "q.l39#23.o2" to "Weil die Gruppe zu klein ist",
    "q.l39#23.o3" to "Weil die Leitung dagegen ist",
    "q.l39#23.e" to "Eine Abstimmung macht aus der Entscheidung eine Verteilung von Meinungen; Bergentscheidungen hängen aber an Informationen und Kriterien. Meinungen darf man sammeln, das Urteil braucht eine Grundlage.",

    "q.l39#24.p" to "In der Gruppe entsteht ein Schweigen, weil niemand «der Böse» sein will. Was durchbricht es am wirksamsten?",
    "q.l39#24.o0" to "Die Leitung sagt ihre eigenen Bedenken zuerst offen und macht sie damit besprechbar",
    "q.l39#24.o1" to "Namentlich kritisieren",
    "q.l39#24.o2" to "Weiter abwarten",
    "q.l39#24.o3" to "Ohne Erklärung absteigen",
    "q.l39#24.e" to "Wer als Erster eine Sorge ausspricht, senkt die Kosten des Sprechens für alle anderen deutlich. Die Leitung ist dafür die naheliegendste Person.",

    "q.l39#25.p" to "Die Leitung hat sich geirrt und dadurch eine Gefahr erzeugt. Was ist jetzt am wichtigsten?",
    "q.l39#25.o0" to "Den Fehler offen nachbesprechen und benennen, was geändert wurde – nicht verharmlosen",
    "q.l39#25.o1" to "Nicht erwähnen",
    "q.l39#25.o2" to "Dem Wetter zuschreiben",
    "q.l39#25.o3" to "Thema wechseln",
    "q.l39#25.e" to "Einen Fehler zuzugeben stärkt das Vertrauen, statt es zu schwächen. Verharmlosen bringt die Gruppe dagegen dazu, Verschweigen zu lernen – und das ist die eigentliche Gefahr.",

    // ---------- l41 Expeditionslogistik und Genehmigungen ----------
    "q.l41#0.p" to "Was ist das Wesen der Expeditionslogistik?",
    "q.l41#0.o0" to "Transport in mehreren Abschnitten, jeder mit eigenen Gewichtslimits, Fristen und Risiken",
    "q.l41#0.o1" to "Alles auf einmal bis zum Bergfuss schicken",
    "q.l41#0.o2" to "Die teuerste Ausrüstung kaufen",
    "q.l41#0.o3" to "Den besten Bergführer finden",
    "q.l41#0.e" to "Nur wenn man Logistik als Kette und nicht als Punkt begreift, lassen sich pro Abschnitt die richtigen Kompromisse treffen. Reisst ein Glied, ist alles danach betroffen.",

    "q.l41#1.p" to "Nach welcher Logik wird Material verpackt?",
    "q.l41#1.o0" to "Nach Ankunftsreihenfolge packen, was zuerst ankommt, ist zuerst erreichbar",
    "q.l41#1.o1" to "Nach Kategorien",
    "q.l41#1.o2" to "Nach Preis",
    "q.l41#1.o3" to "Alles gemischt",
    "q.l41#1.e" to "Im Hochlager ist wenig Platz und das Wetter schlecht; Kisten zu durchwühlen kostet enorm. Verpacken nach Ankunftsreihenfolge spart viel Zeit in exponierter Lage.",

    "q.l41#2.p" to "Woran ist eine Bergsteigergenehmigung meist gebunden?",
    "q.l41#2.o0" to "Verbindungsbeamter, Route und Gültigkeitsdauer",
    "q.l41#2.o1" to "Nur an die Gebühren",
    "q.l41#2.o2" to "Nur an die Personenzahl",
    "q.l41#2.o3" to "Nur an die Jahreszeit",
    "q.l41#2.e" to "Alle drei sind Teil der Genehmigung. Routenwechsel, Überschreitung der Frist oder Personentausch können eine neue Meldung und zusätzliche Kosten bedeuten.",

    "q.l41#3.p" to "Wie lautet die übliche Regel beim Müllpfand?",
    "q.l41#3.o0" to "Es wird nur zurückgezahlt, wenn der gesamte Müll hinausgebracht wurde",
    "q.l41#3.o1" to "Einmal gezahlt, nie zurück",
    "q.l41#3.o2" to "Strafe nach Gewicht",
    "q.l41#3.o3" to "Freiwillige Zahlung",
    "q.l41#3.e" to "Die Regel dient nicht dem Kassieren, sondern macht «Müll mitnehmen» zu einer wirtschaftlichen Bedingung. In der Planung braucht es dafür Personal.",

    "q.l41#4.p" to "Warum darf die Last von Trägern und Co-Leitung nicht beliebig erhöht werden?",
    "q.l41#4.o0" to "Es gibt gesetzliche oder branchenübliche Obergrenzen; Überlast verlagert das Risiko auf sie und bremst die ganze Gruppe",
    "q.l41#4.o1" to "Weil sie sich beschweren",
    "q.l41#4.o2" to "Weil die Ausrüstung kaputtgeht",
    "q.l41#4.o3" to "Weil die Versicherung nicht zahlt",
    "q.l41#4.e" to "Überlast baut die eigene Effizienz auf der Schädigung anderer auf und verlangsamt die ganze Transportkette. Das ist eine ethische und eine organisatorische Frage.",

    "q.l41#5.p" to "Was bedeutet «Verbrauchsrate» im Versorgungsplan?",
    "q.l41#5.o0" to "Personen × Tage × Tagesbedarf, um Gesamtmenge und Nachschubpunkte zu berechnen",
    "q.l41#5.o1" to "Wie weit man pro Tag geht",
    "q.l41#5.o2" to "Wie viel Höhenmeter man pro Tag macht",
    "q.l41#5.o3" to "Wie viel jede Person trägt",
    "q.l41#5.e" to "Brennstoff, Gaskartuschen und Lebensmittel werden über die Rate gerechnet. Nach Gefühl geschätzt fehlt das Gas meist an den kältesten Tagen.",

    "q.l41#6.p" to "Die Genehmigung läuft ab, das Wetterfenster ist noch nicht da. Was ist am sinnvollsten?",
    "q.l41#6.o0" to "Kosten und Auflagen einer Verlängerung vorab prüfen und bei Bedarf verlängern oder verschieben",
    "q.l41#6.o1" to "Über die Frist hinaus weiterklettern",
    "q.l41#6.o2" to "Andere Route ohne Meldung",
    "q.l41#6.o3" to "Den Verbindungsbeamten um eine Ausnahme bitten",
    "q.l41#6.e" to "Klettern über die Frist setzt Genehmigung, Versicherung und Rettung gleichzeitig ausser Kraft. Eine Verlängerung ist teuer, aber billiger als «nach dem Unfall keine Rettung».",

    "q.l41#7.p" to "Warum braucht die Versorgung eine Reserve?",
    "q.l41#7.o0" to "Wetterverzögerungen, Materialverschleiss und der Zustand der Gruppe erhöhen den Verbrauch",
    "q.l41#7.o1" to "Um Vorräte zu verkaufen",
    "q.l41#7.o2" to "Um Gewicht zu sparen",
    "q.l41#7.o3" to "Um Vorschriften zu erfüllen",
    "q.l41#7.e" to "Der Verbrauch einer Expedition verläuft nie linear. Die Reserve ist der Platz für «ein paar Tage länger als geplant».",

    "q.l41#8.p" to "Was ist der Kern der Materialwirtschaft in Hochlagern?",
    "q.l41#8.o0" to "Ein klarer Zuteilungsplan mit Rotation, damit nicht ein Lager überläuft und ein anderes leer bleibt",
    "q.l41#8.o1" to "Je mehr, desto besser",
    "q.l41#8.o2" to "Wer zuerst kommt, nimmt",
    "q.l41#8.o3" to "Gleichmässig verteilen",
    "q.l41#8.e" to "Der Zuteilungsplan sagt jedem Lager, was es hat und wann nachgeliefert wird. Ohne Plan sammelt sich Material am falschen Ort.",

    "q.l41#9.p" to "Was wird für einen Gipfelnachweis üblicherweise gebraucht?",
    "q.l41#9.o0" to "Gipfelfoto oder Video, Erklärungsformular, Genehmigung und Ausweisdokumente",
    "q.l41#9.o1" to "Nur Fotos",
    "q.l41#9.o2" to "Nur die Bestätigung der Mitgehenden",
    "q.l41#9.o3" to "Nichts davon",
    "q.l41#9.e" to "Die Anforderungen unterscheiden sich je nach Berg, aber Foto, Erklärung und Genehmigung gelten fast überall. Nachträglich nachzureichen ist viel mühsamer, als es vorab vorzubereiten.",

    "q.l41#10.p" to "Das Gepäck kommt nicht mit demselben Flug an. Was ist zuerst zu sichern?",
    "q.l41#10.o0" to "Bergschuhe und persönliche technische Ausrüstung – sie lassen sich praktisch nicht kurzfristig ersetzen",
    "q.l41#10.o1" to "Wechselkleidung",
    "q.l41#10.o2" to "Snacks",
    "q.l41#10.o3" to "Souvenirs",
    "q.l41#10.e" to "Mit schlecht sitzenden Schuhen kann man nicht gehen, technische Ausrüstung betrifft die Sicherheit. Viele Teams verlangen, dass beides ins Handgepäck geht.",

    "q.l41#11.p" to "Was muss im Expeditionsplan Abschnitt für Abschnitt geklärt werden?",
    "q.l41#11.o0" to "Transportmittel und Alternativen",
    "q.l41#11.o1" to "Lasten und Kosten von Transport und Trägern",
    "q.l41#11.o2" to "Zeiten und Kontrollpunkte je Abschnitt",
    "q.l41#11.o3" to "Die Social-Media-Konten der Teilnehmenden",
    "q.l41#11.e" to "Die ersten drei entscheiden, ob der Plan überhaupt umsetzbar ist. Der vierte Punkt gehört nicht zur Logistik.",

    "q.l41#12.p" to "Welche Kosten entstehen typischerweise durch Genehmigungen und Auflagen?",
    "q.l41#12.o0" to "Genehmigungsgebühr und Kosten für den Verbindungsbeamten",
    "q.l41#12.o1" to "Müllpfand",
    "q.l41#12.o2" to "Verlängerungsgebühren",
    "q.l41#12.o3" to "Abschreibung der Ausrüstung",
    "q.l41#12.e" to "Die ersten drei sind Auflagenkosten und gehören als eigene Position ins Budget. Die Abschreibung ist ein persönlicher Posten.",

    "q.l41#13.p" to "Welche Zustände soll die Materialwirtschaft im Lager vermeiden?",
    "q.l41#13.o0" to "Ein Lager hat Überschuss, ein anderes nichts zu essen",
    "q.l41#13.o1" to "Brennstoff und Lebensmittel werden so gelagert, dass sie sich gegenseitig verunreinigen",
    "q.l41#13.o2" to "Kein Zuteilungsplan, alles aus dem Gedächtnis",
    "q.l41#13.o3" to "Rotation nach Plan",
    "q.l41#13.e" to "Die ersten drei sind Anzeichen fehlender Organisation. Der vierte Punkt ist genau das richtige Vorgehen.",

    "q.l41#14.p" to "Bringe die Planung einer Expedition in die richtige Reihenfolge.",
    "q.l41#14.o0" to "Route, Genehmigung und Fristen klären",
    "q.l41#14.o1" to "Transportmittel und Zeitfenster je Abschnitt festlegen",
    "q.l41#14.o2" to "Nach Ankunftsreihenfolge packen und einen Zuteilungsplan erstellen",
    "q.l41#14.o3" to "Reserve und Verlängerungsbudget einplanen",
    "q.l41#14.e" to "Die Reihenfolge folgt «erst Auflagen, dann Logistik, dann Details». Transport zu buchen, bevor die Genehmigung steht, verdoppelt die Kosten einer Verschiebung.",

    "q.l41#15.p" to "Bringe die Ankunft des Materials in den Hochlagern in die richtige Reihenfolge.",
    "q.l41#15.o0" to "Transport auf der Strasse zum Basislager",
    "q.l41#15.o1" to "Lastentransport oder Tragen zum Zwischenlager",
    "q.l41#15.o2" to "Verteilung nach Zuteilungsplan auf die Hochlager",
    "q.l41#15.o3" to "Vor dem Gipfelversuch Schlüsselmaterial zählen (Gas, Lebensmittel, Batterien)",
    "q.l41#15.e" to "Der letzte Schritt wird am häufigsten ausgelassen. Ohne Zählung vor dem Gipfelversuch fehlt im Hochlager regelmässig das Gas.",

    "q.l41#16.p" to "Die Gesamtversorgung wird meist über «Personen × Tage × ______» berechnet.",
    "q.l41#16.a0" to "Tagesbedarf",
    "q.l41#16.a1" to "Verbrauch pro Tag",
    "q.l41#16.a2" to "Bedarf pro Tag",
    "q.l41#16.e" to "Nur wenn die Rate im Plan steht, lassen sich Nachschubpunkte und Reserve berechnen.",

    "q.l41#17.p" to "Viele Berge zahlen das ______ nur zurück, wenn der gesamte Müll hinausgebracht wurde.",
    "q.l41#17.a0" to "Müllpfand",
    "q.l41#17.a1" to "Pfand",
    "q.l41#17.e" to "Betrachtet man das Pfand als Kostenposition, merkt man nicht erst am letzten Tag, dass Personal zum Tragen fehlt.",

    "q.l41#18.p" to "Ordne Logistikabschnitt und Hauptrisiko einander zu.",
    "q.l41#18.l0" to "Strassentransport",
    "q.l41#18.l1" to "Lastentransport / Träger",
    "q.l41#18.l2" to "Zuteilung in den Hochlagern",
    "q.l41#18.l3" to "Genehmigungsfrist",
    "q.l41#18.r0" to "Strasse unterbrochen, Erdrutsch, Fahrzeugverspätung",
    "q.l41#18.r1" to "Überlast, Zustand der Personen, Wetter",
    "q.l41#18.r2" to "Falsche Verteilung, kein Essen, kein Gas",
    "q.l41#18.r3" to "Fristüberschreitung macht Genehmigung und Rettung unwirksam",
    "q.l41#18.e" to "Die vier Abschnitte haben völlig verschiedene Risikotypen, deshalb werden die Notfallpläne getrennt geschrieben.",

    "q.l41#19.p" to "Ordne Dokument und Verwendungszweck einander zu.",
    "q.l41#19.l0" to "Genehmigung und Verbindungsbeamten-Unterlagen",
    "q.l41#19.l1" to "Müllpfandbeleg",
    "q.l41#19.l2" to "Gipfelfoto / Erklärungsformular",
    "q.l41#19.l3" to "Versicherung und Rettungsnummer",
    "q.l41#19.r0" to "Zutritts- und Auflagenkontrolle",
    "q.l41#19.r1" to "Grundlage für die Rückzahlung beim Verlassen des Berges",
    "q.l41#19.r2" to "Antrag auf Gipfelanerkennung",
    "q.l41#19.r3" to "Kontakt und Schadensabwicklung im Notfall",
    "q.l41#19.e" to "Vier Dokumente für vier Zeitpunkte: Anreise, Abreise, Anerkennung, Notfall. Fehlt eines, stockt genau dieser Zeitpunkt.",

    "q.l41#20.p" to "Die Gruppe will ausserhalb des genehmigten Bereichs ein weiteres Fixseil einrichten. Was ist zuerst zu tun?",
    "q.l41#20.o0" to "Prüfen, ob das gegen Genehmigung und Schutzgebietsregeln verstösst, und gegebenenfalls melden",
    "q.l41#20.o1" to "Erst einrichten, dann sehen",
    "q.l41#20.o2" to "Nachts heimlich einrichten",
    "q.l41#20.o3" to "Jemand anderen einrichten lassen",
    "q.l41#20.e" to "Fixseile gelten in Schutzgebieten oft als dauerhafte Einrichtung und können ohne Genehmigung unzulässig sein. Erst klären, dann handeln.",

    "q.l41#21.p" to "Das Co-Team meldet einen Arbeitsaufwand über den Vertrag hinaus. Wie ist am sinnvollsten zu reagieren?",
    "q.l41#21.o0" to "Auf Basis von Vertrag und tatsächlichem Aufwand neu verhandeln und die Änderung dokumentieren",
    "q.l41#21.o1" to "Das Gespräch verweigern",
    "q.l41#21.o2" to "Die Erfüllung erzwingen",
    "q.l41#21.o3" to "Privat mehr zahlen, ohne es zu notieren",
    "q.l41#21.e" to "Änderungen beim Personal sind auf Expeditionen normal. Neu verhandeln und dokumentieren schützt beide Seiten.",

    "q.l41#22.p" to "Warum braucht eine Expedition ein eigenes Budget für Verlängerungen?",
    "q.l41#22.o0" to "Wetterfenster und Logistikverzögerungen sind normal; eine Verlängerung bedeutet zusätzliche Kosten für Unterkunft, Personal und Genehmigung",
    "q.l41#22.o1" to "Zum Einkaufen",
    "q.l41#22.o2" to "Für Trinkgelder",
    "q.l41#22.o3" to "Wegen des Wechselkurses",
    "q.l41#22.e" to "Ein Verlängerungsbudget ist keine Verschwendung, sondern verhindert, dass aus Geldgründen gefährliche Entscheidungen fallen.",

    "q.l41#23.p" to "Wie ist der Müll beim Verlassen des Berges richtig zu behandeln?",
    "q.l41#23.o0" to "Wie in der Genehmigung verlangt vollständig getrennt hinausbringen und die Belege aufbewahren",
    "q.l41#23.o1" to "Im Schnee vergraben",
    "q.l41#23.o2" to "Verbrennen",
    "q.l41#23.o3" to "Der nächsten Gruppe übergeben",
    "q.l41#23.e" to "Vergraben und Verbrennen verstossen gegen die Regeln und verschmutzen das Wasser. Hinausbringen plus Beleg ist der einzige Weg, das Pfand zurückzubekommen.",

    "q.l41#24.p" to "Was muss eine Transportversicherung für Expeditionsmaterial vor allem abdecken?",
    "q.l41#24.o0" to "Kosten für einen Reiseabbruch durch Verlust oder Verzögerung der Ausrüstung",
    "q.l41#24.o1" to "Nur die Frachtkosten",
    "q.l41#24.o2" to "Nur Personen",
    "q.l41#24.o3" to "Nichts davon",
    "q.l41#24.e" to "Verspätete Ausrüstung kann die ganze Reise beenden. Die Versicherung muss «Verzögerung und Abbruch» decken, nicht nur «Verlust».",

    "q.l41#25.p" to "Wie lässt sich der Arbeitsumfang mit dem Co-Team am wirksamsten klären?",
    "q.l41#25.o0" to "Vor dem Start Lasten, Anzahl der Transporte und Kosten schriftlich bestätigen, Änderungen laufend dokumentieren",
    "q.l41#25.o1" to "Mündlich vereinbaren",
    "q.l41#25.o2" to "Vor Ort klären",
    "q.l41#25.o3" to "Das Team entscheiden lassen",
    "q.l41#25.e" to "Änderungen sind auf Expeditionen die Regel. Schriftliche Bestätigung und Änderungsprotokoll verhindern Streit über Kosten am letzten Tag.",

    "q.l41#26.p" to "Was gehört in eine Bestandsliste des Basislager-Materials?",
    "q.l41#26.o0" to "Bezeichnung, Menge, Lagerort, Anbruchsdatum und verantwortliche Person",
    "q.l41#26.o1" to "Nur die Gesamtmenge",
    "q.l41#26.o2" to "Nur die Kategorien",
    "q.l41#26.o3" to "Nichts davon",
    "q.l41#26.e" to "Wo, wie viel ist noch da, wer nutzt es – das sind die drei Elemente einer Bestandsliste. Ohne sie sammelt sich Material sicher am falschen Ort.",

    "q.l41#27.p" to "Wenn die Genehmigung «gesamten Müll hinausbringen» verlangt, was muss zusätzlich eingeplant werden?",
    "q.l41#27.o0" to "Personal und Transportkapazität für den Rückweg sowie Wiegen und Belege",
    "q.l41#27.o1" to "Nur Müllsäcke",
    "q.l41#27.o2" to "Nur ein Budget für Strafen",
    "q.l41#27.o3" to "Nichts weiter",
    "q.l41#27.e" to "Auf dem Rückweg ist die Gruppe am müdesten und die Zeit am knappsten – der Müll aber am schwersten. Steht das im Transportplan, gerät der letzte Tag nicht ausser Kontrolle.",
    // ---------- l40 Ernährung und Versorgung über 8.000 m ----------
    "q.l40#0.p" to "Was ist das erste Prinzip der Ernährung in grosser Höhe?",
    "q.l40#0.o0" to "Kohlenhydrate sichern; Hauptsache, es geht überhaupt etwas hinein",
    "q.l40#0.o1" to "Protein zuerst",
    "q.l40#0.o2" to "Fett zuerst",
    "q.l40#0.o3" to "Wenig essen, um Gewicht zu sparen",
    "q.l40#0.e" to "Kohlenhydrate liefern schnell Energie und brauchen wenig Sauerstoff – in der Höhe die «günstigste» Energiequelle. Wenn nichts geht, zuerst die Kohlenhydrate hineinbringen.",

    "q.l40#1.p" to "Welcher der drei Energieträger hat die höchste Energiedichte?",
    "q.l40#1.o0" to "Fett",
    "q.l40#1.o1" to "Kohlenhydrate",
    "q.l40#1.o2" to "Protein",
    "q.l40#1.o3" to "Alle gleich",
    "q.l40#1.e" to "Fett liefert etwa 9 kcal/g, mehr als das Doppelte von Kohlenhydraten und Protein. Deshalb enthalten Höhenproviantpackungen bevorzugt Nüsse und Ölpackungen.",

    "q.l40#2.p" to "Was ist das Problem an der Idee, «am Berg einfach auf Fettstoffwechsel umzuschalten»?",
    "q.l40#2.o0" to "Der Fettanteil an der Energiebereitstellung lässt sich nur über lange Zeit trainieren, kurzfristig schaltet man nicht um",
    "q.l40#2.o1" to "Fett schmeckt nicht",
    "q.l40#2.o2" to "Fett ist zu schwer",
    "q.l40#2.o3" to "Fett macht kalt",
    "q.l40#2.e" to "Die metabolische Anpassung dauert Wochen bis Monate. Training vor der Reise erhöht die Fettnutzung, aber sie passiert nicht spontan am Berg.",

    "q.l40#3.p" to "Was ist die wirksamste Strategie bei nachlassendem Appetit in der Höhe?",
    "q.l40#3.o0" to "Kleine Portionen häufig, energiedichte und leicht essbare Lebensmittel",
    "q.l40#3.o1" to "Sich zu drei grossen Mahlzeiten zwingen",
    "q.l40#3.o2" to "Nur Sportgetränke",
    "q.l40#3.o3" to "Erst essen, wenn der Hunger kommt",
    "q.l40#3.e" to "Bei nachlassendem Appetit ist «einmal viel» praktisch unmöglich. Die Gesamtmenge auf viele kleine Portionen zu verteilen ist die einzige durchhaltbare Lösung.",

    "q.l40#4.p" to "Wozu dient in der Marschverpflegung die Kategorie «im Gehen essbar» vor allem?",
    "q.l40#4.o0" to "Den Rhythmus zu halten, ohne für Energiezufuhr anhalten zu müssen",
    "q.l40#4.o1" to "Sättigung zu erzeugen",
    "q.l40#4.o2" to "Protein zu ergänzen",
    "q.l40#4.o3" to "Mahlzeiten zu ersetzen",
    "q.l40#4.e" to "Sobald man anhalten muss, um zu essen, bricht der Rhythmus. Der Wert von Gel, Fruchtgummi und Riegeln liegt darin, die Bewegung nicht zu unterbrechen.",

    "q.l40#5.p" to "Wie wirkt Dehydratation auf das Essen?",
    "q.l40#5.o0" to "Sie schwächt Appetit und Urteilsvermögen zugleich und macht das Energiedefizit noch schwerer zu schliessen",
    "q.l40#5.o1" to "Sie hat keinen Einfluss",
    "q.l40#5.o2" to "Sie steigert den Appetit",
    "q.l40#5.o3" to "Sie betrifft nur den Durst",
    "q.l40#5.e" to "Wassermangel macht appetitlos und lässt einen schlecht einschätzen, wie viel noch fehlt. Trinken und Essen müssen gemeinsam geplant werden.",

    "q.l40#6.p" to "Wie ist mit verzweigtkettigen Aminosäuren (BCAA) richtig umzugehen?",
    "q.l40#6.o0" to "Es gibt Hinweise auf einen Zusammenhang mit dem Ammoniakstoffwechsel, die Evidenz ist aber begrenzt; die Gesamtkalorien ersetzt das nicht",
    "q.l40#6.o1" to "Sie können Nahrung vollständig ersetzen",
    "q.l40#6.o2" to "Je mehr, desto besser",
    "q.l40#6.o3" to "Sie sind völlig nutzlos",
    "q.l40#6.e" to "Supplemente sind marginale Optimierung. Fehlt die Gesamtenergie, gleicht kein Supplement das aus.",

    "q.l40#7.p" to "Warum ist der tägliche Energiebedarf in grosser Höhe sogar höher?",
    "q.l40#7.o0" to "Kälte, Lastentragen und Sauerstoffmangel erhöhen Ruheumsatz und Atemarbeit",
    "q.l40#7.o1" to "Weil die Schwerkraft mit der Höhe zunimmt",
    "q.l40#7.o2" to "Weil man schlecht schläft",
    "q.l40#7.o3" to "Weil man angespannt ist",
    "q.l40#7.e" to "Steigender Bedarf bei sinkendem Appetit – daraus entsteht das Höhen-Energiedefizit. Jede Strategie muss um diesen Widerspruch herum gebaut werden.",

    "q.l40#8.p" to "Wie ist die Verpflegung am Gipfeltag sinnvoll zu planen?",
    "q.l40#8.o0" to "Vor dem Start eine warme, kohlenhydratbetonte Mahlzeit, unterwegs alle 45–60 Minuten eine kleine Portion",
    "q.l40#8.o1" to "Vor dem Start nichts essen, um Gewicht zu sparen",
    "q.l40#8.o2" to "Erst nach dem Gipfel essen",
    "q.l40#8.o3" to "Den ganzen Tag mit Kaffee bestreiten",
    "q.l40#8.e" to "Nüchtern zu starten leert die Glykogenspeicher schon in den ersten zwei Stunden. Kleine, häufige Portionen sind die einzige Möglichkeit, zehn Stunden und mehr durchzuhalten.",

    "q.l40#9.p" to "Welche Bedeutung hat warme Nahrung in grosser Höhe?",
    "q.l40#9.o0" to "Sie liefert Wärme, Flüssigkeit und psychologische Stütze und wird leichter angenommen",
    "q.l40#9.o1" to "Sie ist nur ein Ritual",
    "q.l40#9.o2" to "Sie ergänzt Protein",
    "q.l40#9.o3" to "Sie hilft bei der Verdauung von Ballaststoffen",
    "q.l40#9.e" to "Warme Nahrung löst drei Probleme gleichzeitig: Energie, Flüssigkeit, Moral. Deshalb lässt sich das Kochen im Lager nicht durch «nur Trockenfutter» ersetzen.",

    "q.l40#10.p" to "Eine Person isst zwei Tage lang kaum etwas. Worauf ist am meisten zu achten?",
    "q.l40#10.o0" to "Energieverlust führt zu Unterkühlung und sinkendem Urteilsvermögen – und kann ein Zeichen zunehmender Höhenkrankheit sein",
    "q.l40#10.o1" to "Die Person nimmt ab",
    "q.l40#10.o2" to "Verstopfung",
    "q.l40#10.o3" to "Vitaminmangel",
    "q.l40#10.e" to "«Isst nicht» ist in der Höhe Ursache und Symptom zugleich. Hält es an, gehört es als Höhenkrankheit abgeklärt – nicht mit gutem Zureden behandelt.",

    "q.l40#11.p" to "Welche Kriterien gelten für Höhenproviant?",
    "q.l40#11.o0" to "Hohe Energiedichte",
    "q.l40#11.o1" to "Wird bei Kälte nicht hart und lässt sich gut kauen",
    "q.l40#11.o2" to "Braucht nicht viel Wasser zum Hinunterschlucken",
    "q.l40#11.o3" to "Je grösser das Volumen, desto besser",
    "q.l40#11.e" to "Kälte macht Schokolade und Riegel steinhart; bei -20 °C ist Gefrorenes praktisch nicht essbar. Grosses Volumen belegt Platz und wird nicht aufgegessen.",

    "q.l40#12.p" to "Wie sind Trinken und Energiezufuhr richtig zu gestalten?",
    "q.l40#12.o0" to "Vor dem Start ausreichend trinken",
    "q.l40#12.o1" to "Unterwegs in kleinen Schlucken häufig trinken",
    "q.l40#12.o2" to "Elektrolyte und Energiezufuhr gemeinsam einsetzen",
    "q.l40#12.o3" to "Erst im Lager alles auf einmal nachholen",
    "q.l40#12.e" to "Einmalig viel zu trinken belastet den Magen-Darm-Trakt und schliesst das Tagesdefizit nicht. Verteiltes Trinken ist wirksam.",

    "q.l40#13.p" to "Was erhöht die tatsächlich gegessene Menge am Berg?",
    "q.l40#13.o0" to "Geschmacksrichtungen mitnehmen, die man auch zu Hause gern isst",
    "q.l40#13.o1" to "Essen in kleine Portionen teilen und griffbereit verstauen",
    "q.l40#13.o2" to "Mehrere unterschiedliche Konsistenzen zum Wechseln vorbereiten",
    "q.l40#13.o3" to "Nur ein einziges Lebensmittel mit maximaler Kalorienzahl",
    "q.l40#13.e" to "«Food aversion» ist in der Höhe häufig: Derselbe Geschmack geht nach einigen Tagen nicht mehr. Vielfalt und vertraute Aromen sind praktikabel.",

    "q.l40#14.p" to "Bringe den Verpflegungsrhythmus eines Tages in eine sinnvolle Reihenfolge.",
    "q.l40#14.o0" to "Nach dem Aufstehen zuerst trinken, Frühstück kohlenhydratbetont",
    "q.l40#14.o1" to "Nach dem Start alle 45–60 Minuten eine kleine Portion",
    "q.l40#14.o2" to "Vor langen Anstiegen eine zusätzliche Portion",
    "q.l40#14.o3" to "Im Lager warme Nahrung und Flüssigkeit nachholen",
    "q.l40#14.e" to "Der Kern des Rhythmus ist «nicht auf den Hunger warten». Hunger heisst, die Glykogenspeicher sind leer – dann braucht es 20–30 Minuten, bis etwas wirkt.",

    "q.l40#15.p" to "Wie ist die Reihenfolge beim Umgang mit «isst nicht» richtig?",
    "q.l40#15.o0" to "Zuerst Flüssigkeit geben und auf Dehydratation prüfen",
    "q.l40#15.o1" to "Auf leicht essbare, energiedichte Nahrung wechseln, kleine Portionen häufig",
    "q.l40#15.o2" to "Auf Symptome der Höhenkrankheit untersuchen",
    "q.l40#15.o3" to "Bei fehlender Besserung den Abstieg erwägen",
    "q.l40#15.e" to "Dehydratation ist der reversible erste Schritt. Isst die Person danach weiterhin nicht, gehört das medizinisch abgeklärt – nicht weiter zugeredet.",

    "q.l40#16.p" to "Die Energiedichte von Fett liegt bei etwa ______ kcal/g.",
    "q.l40#16.a0" to "9",
    "q.l40#16.e" to "Kohlenhydrate und Protein liegen bei etwa 4 kcal/g. Dieser Unterschied erklärt die Vorliebe für Nüsse, Ölpackungen und Schokolade in der Höhe.",

    "q.l40#17.p" to "Unterwegs wird eine Portion etwa alle ______ Minuten empfohlen (eine Zahl).",
    "q.l40#17.a0" to "45–60",
    "q.l40#17.a1" to "45-60",
    "q.l40#17.a2" to "45",
    "q.l40#17.a3" to "60",
    "q.l40#17.a4" to "50",
    "q.l40#17.e" to "Kleine Portionen in kurzen Abständen wirken besser als grosse in langen und belasten den Magen weniger.",

    "q.l40#18.p" to "Ordne Energieträger und Rolle einander zu.",
    "q.l40#18.l0" to "Kohlenhydrate",
    "q.l40#18.l1" to "Fett",
    "q.l40#18.l2" to "Protein",
    "q.l40#18.l3" to "Wasser und Elektrolyte",
    "q.l40#18.r0" to "Am schnellsten verfügbar, erste Wahl in der Höhe",
    "q.l40#18.r1" to "Höchste Energiedichte, langfristige Versorgung",
    "q.l40#18.r2" to "Reparatur und Erhaltung, nicht Hauptenergieträger",
    "q.l40#18.r3" to "Erhält Kreislauf und Wärmeregulation",
    "q.l40#18.e" to "Die Anteile lassen sich verschieben, aber die Grundrolle der Kohlenhydrate ist nicht ersetzbar.",

    "q.l40#19.p" to "Ordne Versorgungssituation und passende Wahl einander zu.",
    "q.l40#19.l0" to "Langer Anstieg",
    "q.l40#19.l1" to "Warten bei extremer Kälte",
    "q.l40#19.l2" to "Zwei Stunden vor dem Gipfelversuch",
    "q.l40#19.l3" to "Zurück im Lager",
    "q.l40#19.r0" to "Gel und Fruchtgummi – Kohlenhydrate, die man im Gehen isst",
    "q.l40#19.r1" to "Fett- und kalorienreich und nicht leicht gefrierend",
    "q.l40#19.r2" to "Eine warme Mahlzeit, überwiegend Kohlenhydrate",
    "q.l40#19.r3" to "Warme Nahrung plus Flüssigkeit und Elektrolyte",
    "q.l40#19.e" to "Dieselben Lebensmittel wirken je nach Situation unterschiedlich. Nach Situation zusammenzustellen ist wirksamer als «einen Haufen Riegel kaufen».",

    "q.l40#20.p" to "Jemand nimmt aus Gewichtsgründen nur Proteinpulver mit. Wie ist das zu beurteilen?",
    "q.l40#20.o0" to "So geht es nicht: Protein ist kein Hauptenergieträger, in der Höhe braucht es ausreichend Kohlenhydrate",
    "q.l40#20.o1" to "In Ordnung, Protein ist reiner",
    "q.l40#20.o2" to "In Ordnung, Protein ist leichter",
    "q.l40#20.o3" to "Geschmackssache",
    "q.l40#20.e" to "Protein ist ein ineffizienter Weg der Energiebereitstellung und erhöht Nierenbelastung und Dehydratationsrisiko. Die Hauptenergie in der Höhe müssen Kohlenhydrate und Fett liefern.",

    "q.l40#21.p" to "Essen gefriert bei Kälte. Was ist die praktischste Gegenmassnahme?",
    "q.l40#21.o0" to "Den zu essenden Teil am Körper tragen und mit Körperwärme warm halten",
    "q.l40#21.o1" to "Mit heissem Wasser übergiessen",
    "q.l40#21.o2" to "Mit den Zähnen bearbeiten",
    "q.l40#21.o3" to "Aufgeben und nichts essen",
    "q.l40#21.e" to "Am Körper zu tragen ist die einfachste wirksame Lösung. Ein Riegel im Rucksack ist bei -20 °C etwa so weich wie ein Stein.",

    "q.l40#22.p" to "Warum ist «Essen» selbst eine Höhenfähigkeit?",
    "q.l40#22.o0" to "Die Aufnahme trotz Sauerstoffmangel und Appetitlosigkeit aufrechtzuerhalten entscheidet direkt über Kraft und Urteilsvermögen",
    "q.l40#22.o1" to "Weil essen können ein Glück ist",
    "q.l40#22.o2" to "Weil Essen teuer ist",
    "q.l40#22.o3" to "Wegen der Fotos",
    "q.l40#22.e" to "Ein Energiedefizit zeigt sich nicht sofort als Hunger, sondern als langsamere Bewegung, Frieren und schlechteres Urteil. Dauerhaft essen zu können ist ein Trainingsergebnis.",

    "q.l40#23.p" to "Was ist über Koffein in grosser Höhe richtig?",
    "q.l40#23.o0" to "In Massen brauchbar, aber kein Ersatz für Ruhe und Flüssigkeit",
    "q.l40#23.o1" to "Je mehr, desto besser",
    "q.l40#23.o2" to "Völlig unzulässig",
    "q.l40#23.o3" to "Nur, um mit Müdigkeit Strecke zu machen",
    "q.l40#23.e" to "Koffein hilft ein wenig gegen Kopfschmerz, aber Müdigkeit damit zu überdecken verschiebt das Problem in einen gefährlicheren Moment.",

    // ---------- m18 Zielberg: Muztagh Ata und Ama Dablam ----------
    "q.m18#16.p" to "Wie hoch und wo liegt der Muztagh Ata?",
    "q.m18#16.o0" to "7.509 m, Akto in Xinjiang, Ostrand des Pamir",
    "q.m18#16.o1" to "6.812 m, Nepal",
    "q.m18#16.o2" to "7.134 m, Kirgisistan",
    "q.m18#16.o3" to "8.163 m, Nepal",
    "q.m18#16.e" to "Der «Vater des Eisbergs» ist einer der ersten 7.000er in China: endlose Schneehänge, hohe Ansprüche an Akklimatisierung und Kondition.",

    "q.m18#17.p" to "Worin liegt die Hauptschwierigkeit des Muztagh Ata?",
    "q.m18#17.o0" to "Akklimatisierung in grosser Höhe und der Kräfteverschleiss auf endlosen Schneehängen, nicht die Technik",
    "q.m18#17.o1" to "Senkrechte Felswände",
    "q.m18#17.o2" to "Dichte Gletscherspalten",
    "q.m18#17.o3" to "Technisches Eisklettern",
    "q.m18#17.e" to "Technisch ist er verhältnismässig mild, aber die drei Faktoren lang, hoch und kalt verstärken jede Schwäche bei Kondition und Akklimatisierung.",

    "q.m18#18.p" to "In welchem Land beziehungsweise an welcher Grenze liegt der Lenin-Pik?",
    "q.m18#18.o0" to "An der Grenze zwischen Kirgisistan und Tadschikistan",
    "q.m18#18.o1" to "Nepal",
    "q.m18#18.o2" to "Xinjiang, China",
    "q.m18#18.o3" to "Pakistan",
    "q.m18#18.e" to "Der Lenin-Pik im Pamir gilt oft als erster 7.000er, verlangt aber trotzdem den Umgang mit grosser Höhe und Gletschergelände.",

    "q.m18#19.p" to "Wie hoch ist der Ama Dablam?",
    "q.m18#19.o0" to "6.812 m",
    "q.m18#19.o1" to "7.509 m",
    "q.m18#19.o2" to "7.126 m",
    "q.m18#19.o3" to "6.189 m",
    "q.m18#19.e" to "Unter 7.000 m, aber die steile Mischung aus Fels und Schnee und die starke Exposition lassen seine technischen Anforderungen denen eines 7.000ers entsprechen.",

    "q.m18#20.p" to "Als Prüfstein wofür gilt der Ama Dablam häufig?",
    "q.m18#20.o0" to "Für die technische und psychische Vorbereitung auf 8.000er",
    "q.m18#20.o1" to "Für den ersten Schneeberg",
    "q.m18#20.o2" to "Als Skiroute",
    "q.m18#20.o3" to "Als Wanderweg",
    "q.m18#20.e" to "Seine Exposition und die Kombination der Techniken prüfen, ob man unter Druck noch die richtige Bewegung hinbekommt.",

    "q.m18#21.p" to "Wie ist das Saisonfenster bei 7.000ern meist?",
    "q.m18#21.o0" to "Enger als bei 5.000ern und 6.000ern; Höhenwind und Schneefall bestimmen das Fenster",
    "q.m18#21.o1" to "Ganzjährig offen",
    "q.m18#21.o2" to "Nur im Winter",
    "q.m18#21.o3" to "Wie im Tiefland",
    "q.m18#21.e" to "Je höher, desto stärker hängt das Fenster von Höhenwind und Monsun ab. Ein enges Fenster verlangt entschlosseneres Warten und entschlosseneren Rückzug.",

    "q.m18#22.p" to "Was ist bei der Wahl eines 7.000ers zuerst zu prüfen?",
    "q.m18#22.o0" to "Ob man auf 6.000ern bereits mehrfach lange Schneehänge und Selbstmanagement stabil bewältigt hat",
    "q.m18#22.o1" to "Die Kletterschwierigkeit",
    "q.m18#22.o2" to "Laufzeiten",
    "q.m18#22.o3" to "Die Menge der Ausrüstung",
    "q.m18#22.e" to "Die Schwelle zum 7.000er ist Ausdauer und Selbstständigkeit, nicht eine einzelne Technik. Zuerst die eigene 6.000er-Bilanz ansehen.",

    "q.m18#23.p" to "Was braucht es für Genehmigungen und Logistik an diesen Bergen in der Regel?",
    "q.m18#23.o0" to "Genehmigungen Wochen im Voraus beantragen und Bergführer, Lastentransport und Lagermaterial organisieren",
    "q.m18#23.o1" to "Alles vor Ort erledigen",
    "q.m18#23.o2" to "Keine Genehmigung",
    "q.m18#23.o3" to "Nur ein Ticket kaufen",
    "q.m18#23.e" to "Je abgelegener die Route, desto länger die Logistikkette. Genehmigung und Logistik als Teil der technischen Vorbereitung zu behandeln ist viel billiger als kurzfristige Reparaturen.",

    // ---------- m19 Physiologische Grenzen über 8.000 m ----------
    "q.m19#19.p" to "Ab welcher Höhe spricht man üblicherweise von der Todeszone?",
    "q.m19#19.o0" to "8.000 m",
    "q.m19#19.o1" to "6.000 m",
    "q.m19#19.o2" to "7.000 m",
    "q.m19#19.o3" to "5.000 m",
    "q.m19#19.e" to "Über 8.000 m liegt der Luftdruck bei etwa einem Drittel des Meeresspiegels; der Körper kann das Gleichgewicht nicht halten und verbraucht nur noch.",

    "q.m19#20.p" to "Warum erholt man sich auf 8.000 m auch mit «Ruhe» nicht wirklich?",
    "q.m19#20.o0" to "Die Sauerstoffversorgung reicht nicht für die Regeneration; der Körper befindet sich im Nettoverbrauch",
    "q.m19#20.o1" to "Weil es zu kalt ist",
    "q.m19#20.o2" to "Weil man schlecht schläft",
    "q.m19#20.o3" to "Wegen Dehydratation",
    "q.m19#20.e" to "Das ist die physiologische Grundlage für «Aufenthaltsdauer so kurz wie möglich». Jede Taktik wird um die Verkürzung der Exposition herum gebaut.",

    "q.m19#21.p" to "Was ist die gefährlichste Ausprägung nachlassender kognitiver Leistung in der Höhe?",
    "q.m19#21.o0" to "Dass man selbst nicht bemerkt, wie schlecht das Urteilsvermögen geworden ist",
    "q.m19#21.o1" to "Schlechtes Gedächtnis",
    "q.m19#21.o2" to "Langsame Reaktion",
    "q.m19#21.o3" to "Fehlende Konzentration",
    "q.m19#21.e" to "Sauerstoffmangel schwächt zuerst die Fähigkeit zur Selbsteinschätzung. Deshalb werden Entscheidungen externalisiert: Checklisten, Gegenprüfung durch andere.",

    // ---------- m20 Sauerstoffsystem und Versorgung ----------
    "q.m20#20.p" to "Warum unterscheidet sich die nutzbare Kapazität einer Sauerstoffflasche von der Nennkapazität?",
    "q.m20#20.o0" to "Ein Restdruck in der Flasche macht den letzten Teil unbrauchbar, und Kälte senkt den Druck",
    "q.m20#20.o1" to "Wegen Undichtigkeit",
    "q.m20#20.o2" to "Weil falsch etikettiert wurde",
    "q.m20#20.o3" to "Wegen Verschleiss der Maske",
    "q.m20#20.e" to "Kalkuliert wird mit der nutzbaren Menge. Den Nennwert als nutzbar anzunehmen ist die häufige Ursache dafür, dass am Gipfeltag «der Sauerstoff zu früh leer» ist.",

    "q.m20#21.p" to "Was kostet ein höherer Sauerstofffluss?",
    "q.m20#21.o0" to "Die Reichweite verkürzt sich proportional; es braucht mehr Reserveflaschen",
    "q.m20#21.o1" to "Es kostet nichts",
    "q.m20#21.o2" to "Die Maske geht kaputt",
    "q.m20#21.o3" to "Die Flasche friert ein",
    "q.m20#21.e" to "Fluss und Reichweite verhalten sich umgekehrt proportional. Wird der Fluss erhöht, müssen Gesamtbedarf und Reserve neu gerechnet werden.",
    // ---------- m21 Die 14 Achttausender (1): Himalaya ----------
    "q.m21#18.p" to "Wie lautet die neueste offizielle Höhe des Mount Everest?",
    "q.m21#18.o0" to "8.848,86 m (gemeinsame chinesisch-nepalesische Messung 2020)",
    "q.m21#18.o1" to "8.848 m",
    "q.m21#18.o2" to "8.850 m",
    "q.m21#18.o3" to "8.846 m",
    "q.m21#18.e" to "8.848,86 m ist der 2020 gemeinsam veröffentlichte Wert. Die 8.848 m aus älteren Lehrbüchern sind der klassische Wert; beide sind gebräuchlich.",

    "q.m21#19.p" to "Wie liegt der Lhotse zum Mount Everest?",
    "q.m21#19.o0" to "Unmittelbar südlich des Everest; oft wird er in derselben Tour bestiegen",
    "q.m21#19.o1" to "Nördlich des Everest",
    "q.m21#19.o2" to "Im Westen Nepals",
    "q.m21#19.o3" to "Im Karakorum",
    "q.m21#19.e" to "Beide Berge teilen einen Teil der Route über das Südjoch, deshalb wird «Everest plus Lhotse» häufig in einer Expedition geplant.",

    "q.m21#20.p" to "Wo liegt der Kangchendzönga?",
    "q.m21#20.o0" to "An der Grenze zwischen Nepal und Indien",
    "q.m21#20.o1" to "An der Grenze zwischen China und Nepal",
    "q.m21#20.o2" to "In Pakistan",
    "q.m21#20.o3" to "In Bhutan",
    "q.m21#20.e" to "Der dritthöchste Berg der Welt liegt an der Grenze zwischen Nepal und Indien (Sikkim); Genehmigungen und Logistik sind dort verhältnismässig aufwendig.",

    "q.m21#21.p" to "Was zeichnet die Annapurna I aus?",
    "q.m21#21.o0" to "Relativ hohe Sterblichkeit; die Route ist steil, Lawinen- und Steinschlagrisiko treten hervor",
    "q.m21#21.o1" to "Sie ist die einfachste",
    "q.m21#21.o2" to "Sie ist die höchste",
    "q.m21#21.o3" to "Sie ist ganzjährig besteigbar",
    "q.m21#21.e" to "Sie gehört zu den riskantesten Achttausendern. Die Zahlen erinnern daran: Höhenrang ist nicht Schwierigkeitsrang.",

    // ---------- m22 Die 14 Achttausender (2): Karakorum und Überblick ----------
    "q.m22#17.p" to "Wie hoch ist der K2, und wie lautet sein Beiname?",
    "q.m22#17.o0" to "8.611 m, «wilder Berg»",
    "q.m22#17.o1" to "8.586 m, «Schneeleopard»",
    "q.m22#17.o2" to "8.126 m, «nackter Berg»",
    "q.m22#17.o3" to "8.080 m, «Hidden Peak»",
    "q.m22#17.e" to "Der K2 ist der zweithöchste Berg der Welt; bei technischer Schwierigkeit und Sterblichkeit liegt er unter den Achttausendern seit langem vorn.",

    "q.m22#18.p" to "Wie lautet der Beiname des Nanga Parbat, und was ist sein Hauptrisiko?",
    "q.m22#18.o0" to "«Nackter Berg»; der gewaltige Höhenunterschied bringt Lawinen- und Steinschlagrisiko",
    "q.m22#18.o1" to "«Vater des Eisbergs»",
    "q.m22#18.o2" to "«Hidden Peak»",
    "q.m22#18.o3" to "«Menschenfresser»",
    "q.m22#18.e" to "Seine Südwand ist einer der grössten Felsabstürze der Welt. Die Route ist exponiert, das Wetter wechselhaft, der Rückzug schwierig.",

    "q.m22#19.p" to "Wie hoch sind Gasherbrum I und II?",
    "q.m22#19.o0" to "8.080 m und 8.035 m",
    "q.m22#19.o1" to "8.051 m und 8.080 m",
    "q.m22#19.o2" to "8.611 m und 8.586 m",
    "q.m22#19.o3" to "8.188 m und 8.167 m",
    "q.m22#19.e" to "GI 8.080 m, GII 8.035 m. Beide werden oft zusammen genannt, unterscheiden sich aber stark in Route und Schwierigkeit.",

    "q.m22#20.p" to "Wie hoch ist der Broad Peak?",
    "q.m22#20.o0" to "8.051 m",
    "q.m22#20.o1" to "8.035 m",
    "q.m22#20.o2" to "8.080 m",
    "q.m22#20.o3" to "8.126 m",
    "q.m22#20.e" to "Der Broad Peak liegt bei 8.051 m und gilt als einer der technisch einfacheren Achttausender – mit langen Schneehängen und den Risiken grosser Höhe bleibt er dennoch anspruchsvoll.",

    "q.m22#21.p" to "Wie viele Achttausender liegen in Pakistan?",
    "q.m22#21.o0" to "Fünf",
    "q.m22#21.o1" to "Drei",
    "q.m22#21.o2" to "Vier",
    "q.m22#21.o3" to "Zwei",
    "q.m22#21.e" to "K2, Nanga Parbat, Gasherbrum I und II sowie Broad Peak – insgesamt fünf.",

    // ---------- m23 Abschlussprüfung Teil 1 ----------
    "q.m23#18.p" to "Szenario: Eine Person zeigt auf 7.500 m Ataxie, der Sauerstoff reicht noch für zwei Stunden. Was ist zuerst zu tun?",
    "q.m23#18.o0" to "Sofort absteigen und Sauerstoff geben, parallel das Basislager für die Übernahme verständigen",
    "q.m23#18.o1" to "Erst ausruhen und beobachten",
    "q.m23#18.o2" to "Erst Medikamente geben",
    "q.m23#18.o3" to "Bis zum Lager weitergehen und dort behandeln",
    "q.m23#18.e" to "Ataxie deutet auf HACE. Der Abstieg ist die einzige sicher wirksame Massnahme; Sauerstoff dient dazu, Zeit zu gewinnen.",

    "q.m23#19.p" to "Szenario: Am Gipfeltag ist das Fixseil der Vorausgegangenen an einer Stelle aufgeraut. Wie ist vorzugehen?",
    "q.m23#19.o0" to "Diesen Abschnitt nicht mehr benutzen, Route ändern oder umkehren",
    "q.m23#19.o1" to "Weiterbenutzen, aber vorsichtig",
    "q.m23#19.o2" to "Nur die Nachfolgenden warnen",
    "q.m23#19.o3" to "Dokumentieren und weiterbenutzen",
    "q.m23#19.e" to "Die Restfestigkeit eines aufgerauten Seils lässt sich nicht abschätzen. Ein Fixseil ist die Lebenslinie aller – Vorsicht ist kein Ersatz dafür.",

    "q.m23#20.p" to "Szenario: Die Gruppe gerät auf 6.500 m in einen Schneesturm, Sichtweite fünf Meter. Was ist die sinnvollste Wahl?",
    "q.m23#20.o0" to "In der Nähe einen Windschutz bauen und warten oder mit GPS auf der aufgezeichneten Spur zurückgehen",
    "q.m23#20.o1" to "Weiter nach dem Weg suchen",
    "q.m23#20.o2" to "Sich aufteilen und suchen",
    "q.m23#20.o3" to "Sich hinsetzen und auf Aufklaren warten",
    "q.m23#20.e" to "Bei Whiteout führt «den Weg suchen» fast zwangsläufig vom Kurs ab. Anhalten und Schutz bauen oder auf der aufgezeichneten Spur zurück – mehr Optionen gibt es nicht.",

    "q.m23#21.p" to "Szenario: Alle wollen weiter, nur eine Person hat ein schlechtes Gefühl, kann es aber nicht begründen. Was ist zu tun?",
    "q.m23#21.o0" to "Offen sagen «ich fühle mich nicht wohl damit» und die Gruppe bitten, die Schlüsselinformationen gemeinsam zu prüfen",
    "q.m23#21.o1" to "Der Mehrheit folgen",
    "q.m23#21.o2" to "Schweigend mitgehen",
    "q.m23#21.o3" to "Allein umkehren",
    "q.m23#21.e" to "Intuition ist oft ein Signal, das wahrgenommen, aber noch nicht in Worte gefasst wurde. Es auszusprechen lässt die Gruppe die Fakten gemeinsam prüfen.",

    // ---------- m24 Abschlussprüfung Teil 2 ----------
    "q.m24#18.p" to "Szenario: Am Gipfeltag liegt die Gruppe vier Stunden hinter dem Plan, der Wind nimmt zu, eine Person wird langsam. Wie ist zu urteilen?",
    "q.m24#18.o0" to "Nach den vorab festgelegten Umkehrbedingungen absteigen und die auslösenden Gründe dokumentieren",
    "q.m24#18.o1" to "Bis zum Gipfel weitergehen und dann sehen",
    "q.m24#18.o2" to "Die langsame Person allein zurückgehen lassen",
    "q.m24#18.o3" to "Tempo erhöhen, um Zeit aufzuholen",
    "q.m24#18.e" to "Wenn drei Signale gleichzeitig auftreten, kommt das «weiter» meist aus dem Zieldruck und nicht aus den Fakten. Genau dafür sind Umkehrbedingungen da.",

    "q.m24#19.p" to "Szenario: Eine Person hat Atemnot in Ruhe, die Sauerstoffsättigung liegt aber noch bei 80 %. Was ist zu tun?",
    "q.m24#19.o0" to "Wie HAPE behandeln: Ruhe, Sauerstoff, Abstieg vorbereiten",
    "q.m24#19.o1" to "Weiter beobachten",
    "q.m24#19.o2" to "Viel trinken lassen",
    "q.m24#19.o3" to "Schmerzmittel geben",
    "q.m24#19.e" to "Symptome haben Vorrang vor Zahlen. Atemnot in Ruhe ist das Kernsymptom von HAPE; der Abstieg ist die sicherste Massnahme.",

    "q.m24#20.p" to "Szenario: In einem Fixseilabschnitt erweist sich ein Ankerpunkt als fragwürdig, die Gruppe ist bereits über die Hälfte hinaus. Was ist zu tun?",
    "q.m24#20.o0" to "Den Abschnitt nicht mehr benutzen, einen Backup setzen oder die Route ändern, die Personen zuerst in sichere Position bringen",
    "q.m24#20.o1" to "Schnell durchsteigen",
    "q.m24#20.o2" to "Nur die Nachfolgenden warnen",
    "q.m24#20.o3" to "Weiterbenutzen",
    "q.m24#20.e" to "«Wir sind schon über der Hälfte» ist kein Grund weiterzumachen. Der Ausfall eines Ankers wirkt systemisch, nicht individuell.",

    "q.m24#21.p" to "Szenario: Die Tour ist zu Ende. Was lohnt es sich am meisten mitzunehmen?",
    "q.m24#21.o0" to "Eine Nachbesprechung mit Zeitleiste, Entscheidungsgrundlagen und Fehlerstellen",
    "q.m24#21.o1" to "Fotos",
    "q.m24#21.o2" to "Die Ausrüstungsliste",
    "q.m24#21.o3" to "Die Rechnung",
    "q.m24#21.e" to "Eine Nachbesprechung verwandelt Erlebnis in Erfahrung. Aufzuschreiben, an welchem Punkt eine Entscheidung früher möglich gewesen wäre, macht sie beim nächsten Mal früher möglich.",

    // ---------- t01 Routenschwierigkeit und Selbsteinschätzung ----------
    "q.t01#0.p" to "Welche Informationen reichen am ehesten aus, um die Schwierigkeit einer Wanderroute zu beurteilen?",
    "q.t01#0.o0" to "Die Kilometerzahl",
    "q.t01#0.o1" to "Distanz, Gesamtaufstieg, Wegbeschaffenheit, Versorgung und Ausstiegspunkte",
    "q.t01#0.o2" to "Die höchste Höhe",
    "q.t01#0.o3" to "Wie lange andere gebraucht haben",
    "q.t01#0.e" to "Die Kilometerzahl ist nur ein Faktor. Bei denselben 10 km können 80 m und 800 m Aufstieg die Zeit um das Zwei- bis Dreifache unterscheiden; und ob der Weg Feldweg, Schotter oder nasse Felsplatte ist, entscheidet über das Umknickrisiko.",

    "q.t01#1.p" to "Zwei Routen sind je 10 km lang, A hat 80 m, B 800 m Gesamtaufstieg. Was ist der wesentliche Unterschied?",
    "q.t01#1.o0" to "Die Aussicht",
    "q.t01#1.o1" to "Zeitbedarf und Krafteinsatz; B liegt etwa beim Zwei- bis Dreifachen von A",
    "q.t01#1.o2" to "Die Höhenlage",
    "q.t01#1.o3" to "Kaum ein Unterschied",
    "q.t01#1.e" to "Der Aufstieg ist die am leichtesten übersehene Variable. Faustregel: 100 m Aufstieg entsprechen etwa 500 m Flachstrecke – 800 m Aufstieg sind also rechnerisch 4 km zusätzlich.",

    "q.t01#2.p" to "Welche Bedingungen sollte eine Route für die erste Wanderung erfüllen?",
    "q.t01#2.o0" to "In unter 3 Stunden machbar",
    "q.t01#2.o1" to "Gesamtaufstieg unter 300 m",
    "q.t01#2.o2" to "Unterwegs Strasse oder Dorf für einen Abbruch",
    "q.t01#2.o3" to "Durchgehend voller Handyempfang",
    "q.t01#2.e" to "Die ersten drei sind kontrollierbare Risikogrenzen. Empfang ist Glückssache und gehört nicht in die Planung – in vielen Tälern gibt es schlicht keinen.",

    "q.t01#3.p" to "Warum sollte man Ausstiegspunkte vor der Aussicht klären?",
    "q.t01#3.o0" to "Dort gibt es meist Toiletten",
    "q.t01#3.o1" to "Damit man bei Wetter- oder Kraftproblemen nahe absteigen kann, statt die ganze Strecke durchzuziehen",
    "q.t01#3.o2" to "Für bessere Fotos",
    "q.t01#3.o3" to "Weil die Versicherung es verlangt",
    "q.t01#3.e" to "Ausstiegspunkte verwandeln «ich muss durch» in «ich kann anhalten». Für jeden Abschnitt sollte klar sein, wo der nächste Ausstieg liegt und wie lange man dorthin braucht.",

    "q.t01#4.p" to "Dieselbe Route wird nach Regen deutlich schwieriger. Was ist der Hauptgrund?",
    "q.t01#4.o0" to "Die Temperatur sinkt",
    "q.t01#4.o1" to "Der Weg ist nass und schlammig, eventuell mit Furten; Zeitbedarf und Umknickrisiko steigen zugleich",
    "q.t01#4.o2" to "Die Aussicht wird schlechter",
    "q.t01#4.o3" to "Es sind weniger Leute unterwegs",
    "q.t01#4.e" to "Nässe verlängert die Zeit und erhöht Rutsch- und Verletzungsrisiko. Aus einer Vier-Stunden-Route werden nach Regen eher fünf bis sechs Stunden – und einige steile Abstiege müssen neu beurteilt werden.",

    "q.t01#5.p" to "Jemand sagt «diese Route bin ich in vier Stunden gegangen». Wie ist das zu verstehen?",
    "q.t01#5.o0" to "Dann schaffe ich das auch in vier Stunden",
    "q.t01#5.o1" to "Das ist das Tempo einer erfahrenen Person; die Gruppe sollte mit dem Langsamsten und dem 1,3- bis 1,5-Fachen rechnen",
    "q.t01#5.o2" to "Die Route ist also einfach",
    "q.t01#5.o3" to "Das ist als Referenz völlig unbrauchbar",
    "q.t01#5.e" to "Fremde Zeiten beruhen auf Kondition, Gepäck und Ortskenntnis. Erst mit dem Langsamsten rechnen und dann Zeit für Pausen, Fotos und Wegsuche zugeben – so kommt man der Realität näher.",

    "q.t01#6.p" to "Wie wird der Zeitbedarf einer Wanderung üblicherweise grob geschätzt?",
    "q.t01#6.o0" to "Grundzeit nach Distanz, plus 30 Minuten je 300–500 m Aufstieg",
    "q.t01#6.o1" to "Nur nach Distanz",
    "q.t01#6.o2" to "Nur nach Aufstieg",
    "q.t01#6.o3" to "Nach Körpergewicht",
    "q.t01#6.e" to "Reine Distanz unterschätzt den Aufwand des Aufstiegs. Distanzzeit und Aufstiegszeit getrennt rechnen und dann mit einem Gruppenfaktor multiplizieren – so wird der Fehler viel kleiner.",

    "q.t01#7.p" to "Warum müssen Ausstiegspunkte vor dem Start geklärt sein?",
    "q.t01#7.o0" to "Nur mit einem möglichen Abstieg gibt es Sicherheit und Anpassungsspielraum",
    "q.t01#7.o1" to "Für Fotos",
    "q.t01#7.o2" to "Um Eintritt zu sparen",
    "q.t01#7.o3" to "Um leichter zu packen",
    "q.t01#7.e" to "Der Ausstiegspunkt ist das Sicherheitsventil der Tour. Ohne ihn bleibt nur, den Weg bis zum Ende durchzuziehen.",

    // ---------- t02 Schuhe, Socken und Füsse ----------
    "q.t02#0.p" to "Was ist das entscheidende Kriterium für die Passform von Wanderschuhen?",
    "q.t02#0.o0" to "Je enger, desto stabiler",
    "q.t02#0.o1" to "Die Ferse rutscht nicht, und beim Abstieg stossen die Zehen nicht vor",
    "q.t02#0.o2" to "Je grösser, desto bequemer",
    "q.t02#0.o3" to "Marke und Preis",
    "q.t02#0.e" to "Anprobieren am Nachmittag, mit Wandersocken, und ein Stück bergab gehen. Rutscht der Fuss im Schuh, reibt beim Aufstieg die Achillessehne und beim Abstieg stossen die Zehen – in beiden Richtungen entstehen Blasen.",

    "q.t02#1.p" to "Was ist die unmittelbarste Ursache von Blasen?",
    "q.t02#1.o0" to "Die Schuhe sind zu neu",
    "q.t02#1.o1" to "Nässe, Reibung und örtlicher Druck zusammen",
    "q.t02#1.o2" to "Zu langes Gehen",
    "q.t02#1.o3" to "Die Sockenfarbe",
    "q.t02#1.e" to "Ein einzelner Faktor wirkt selten allein. Sand im Schuh erzeugt örtlichen Druck, Schweiss macht die Haut weich – und nach einer halben Stunde ist die Blase da.",

    "q.t02#2.p" to "Was ist die wirksamste Kombination zur Blasenvorbeugung?",
    "q.t02#2.o0" to "Vor dem Start Tape auf bekannte Reibstellen, Socken trocken halten, unterwegs wechseln",
    "q.t02#2.o1" to "Zwei Paar Baumwollsocken tragen",
    "q.t02#2.o2" to "Vorher ein Fussbad nehmen",
    "q.t02#2.o3" to "Ohne Pause durchgehen, um An- und Ausziehen zu sparen",
    "q.t02#2.e" to "Tape verlagert die Reibung von der Haut auf das Pflaster, der Sockenwechsel löst die Nässe. Beides zusammen verhindert die meisten Blasen.",

    "q.t02#3.p" to "Wie sind die Schnürsenkel bei langem Abstieg zu behandeln?",
    "q.t02#3.o0" to "Fester schnüren, damit der Fuss weniger nach vorn rutscht",
    "q.t02#3.o1" to "Völlig öffnen",
    "q.t02#3.o2" to "Wie beim Aufstieg lassen",
    "q.t02#3.o3" to "Nur den Knöchelbereich schnüren",
    "q.t02#3.e" to "Beim Abstieg schiebt sich der Fuss nach vorn. Mittelteil und Knöchel fest, den Rist etwas lockerer: Das hält die Ferse und drückt nicht auf den Spann.",

    "q.t02#4.p" to "Am Fuss entsteht ein Hotspot – gerötet, warm, auf Druck leicht schmerzhaft. Was ist zu tun?",
    "q.t02#4.o0" to "Sofort anhalten und behandeln",
    "q.t02#4.o1" to "Tape oder Pflaster aufkleben",
    "q.t02#4.o2" to "Schuhe und Socken auf Falten und Sand prüfen",
    "q.t02#4.o3" to "Weitergehen, bis es sich aufreibt",
    "q.t02#4.e" to "Ein Hotspot ist ein reversibles Stadium und in zwei Minuten behandelt. Ist die Haut erst offen, wird die Wunde bei jedem Schritt grösser und kann sich entzünden.",

    "q.t02#5.p" to "Warum sind Baumwollsocken auf langen Strecken ungeeignet?",
    "q.t02#5.o0" to "Baumwolle nimmt Schweiss auf, gibt ihn aber nicht weiter; nass erhöht sie Reibung und verliert die Wärmewirkung",
    "q.t02#5.o1" to "Baumwollsocken sind zu teuer",
    "q.t02#5.o2" to "Sie sind nicht atmungsaktiv und riechen",
    "q.t02#5.o3" to "Sie färben ab",
    "q.t02#5.e" to "Baumwollfasern legen sich nass auf die Haut, der Reibungskoeffizient steigt; fällt die Temperatur, entzieht die nasse Socke schnell Wärme. Wolle oder Synthetik leiten Feuchtigkeit ab und wärmen auch nass noch etwas.",

    "q.t02#6.p" to "Wozu dient die Fersenschnürung («Heel Lock»)?",
    "q.t02#6.o0" to "Die Ferse im Schuhfersenbereich zu fixieren, damit beim Abstieg die Zehen weniger anstossen",
    "q.t02#6.o1" to "Den Schuh enger zu machen",
    "q.t02#6.o2" to "Schneller hineinzukommen",
    "q.t02#6.o3" to "Den Verschleiss zu verringern",
    "q.t02#6.e" to "Beim Abstieg rutscht der Fuss nach vorn; wiederholtes Anstossen der Zehen ist die Hauptursache von blauen Nägeln und Blasen. Die Fersenschnürung löst genau das.",

    "q.t02#7.p" to "Wie viel Spielraum sollte ein Wanderschuh vor den Zehen lassen?",
    "q.t02#7.o0" to "Etwa eine Fingerbreite, weil der Fuss auf langen Strecken anschwillt",
    "q.t02#7.o1" to "Genau passend",
    "q.t02#7.o2" to "Eine Nummer grösser",
    "q.t02#7.o3" to "Zwei Nummern grösser",
    "q.t02#7.e" to "Nach langem Gehen schwillt der Fuss leicht an. Eine Fingerbreite verhindert das Anstossen beim Abstieg, ohne dass der Schuh so locker wird, dass er reibt.",

    // ---------- t03 Rucksack und Last ----------
    "q.t03#0.p" to "Wie hoch ist die übliche Obergrenze für das Traggewicht beim Wandern?",
    "q.t03#0.o0" to "10–20 % des Körpergewichts, Anfänger an der unteren Grenze",
    "q.t03#0.o1" to "Je schwerer, desto sicherer",
    "q.t03#0.o2" to "30 % des Körpergewichts",
    "q.t03#0.o3" to "Es gibt keine Obergrenze",
    "q.t03#0.e" to "Gewicht wird direkt zu Gelenkbelastung und Sauerstoffverbrauch. Für die erste Mehrtagestour den Rucksack bei 12–15 % des Körpergewichts halten – wer danach noch Reserven hat, hat die Menge richtig gewählt.",

    "q.t03#1.p" to "Wo gehören schwere Gegenstände im Rucksack hin?",
    "q.t03#1.o0" to "Nah am Rücken, zwischen Schulterblättern und Taille",
    "q.t03#1.o1" to "Ganz nach unten",
    "q.t03#1.o2" to "Ganz nach aussen",
    "q.t03#1.o3" to "Ins Deckelfach",
    "q.t03#1.e" to "Schweres nah am Rücken und auf Höhe des Körperschwerpunkts schwankt beim Gehen am wenigsten. Ganz unten zieht es nach unten und drückt ins Kreuz; aussen verschiebt es den Schwerpunkt nach hinten, und Schultern und Nacken kompensieren.",

    "q.t03#2.p" to "Wie teilen sich Schultergurte und Hüftgurt richtig auf?",
    "q.t03#2.o0" to "Die Schultergurte tragen",
    "q.t03#2.o1" to "Der Hüftgurt trägt den grössten Teil, die Schultergurte halten und stabilisieren",
    "q.t03#2.o2" to "Der Hüftgurt ist nur Dekoration",
    "q.t03#2.o3" to "Beides beliebig",
    "q.t03#2.e" to "Der Hüftgurt leitet das Gewicht auf das Becken – den tragfähigsten Teil des Körpers. Zu feste Schultergurte drücken auf die Gefässe, nach einiger Zeit schlafen die Arme ein.",

    "q.t03#3.p" to "Was gehört ins Deckelfach oder aussen an den Rucksack?",
    "q.t03#3.o0" to "Regenjacke, Karte, Stirnlampe",
    "q.t03#3.o1" to "Wasser und Verpflegung für den Tag",
    "q.t03#3.o2" to "Zeltstangen quer aussen",
    "q.t03#3.o3" to "Die schwerste Trinkflasche",
    "q.t03#3.e" to "Deckelfach und Aussenbefestigung sind für Dinge, die man ständig braucht, oder für unförmige Teile. Schweres aussen zerstört den Schwerpunkt und bleibt an Ästen und Fels hängen.",

    "q.t03#4.p" to "Was folgt daraus, wenn der Rucksack nicht am Rücken anliegt?",
    "q.t03#4.o0" to "Der Schwerpunkt wandert nach hinten, Schultern und Nacken kompensieren, der Abstieg wird unsicherer",
    "q.t03#4.o1" to "Es sieht nur unschön aus",
    "q.t03#4.o2" to "Das Volumen wird kleiner",
    "q.t03#4.o3" to "Es hat keinen Einfluss",
    "q.t03#4.e" to "Bleibt zwischen Rückenplatte und Rücken ein Spalt, pendelt der Rucksack mit jedem Schritt. Um ihn zu stabilisieren, lehnt man sich vor und zieht die Schultern hoch – nach einigen Stunden schmerzt der Rücken zuerst.",

    "q.t03#5.p" to "Warum sollte der Rucksack vor dem Start gewogen werden?",
    "q.t03#5.o0" to "Nur mit einem Referenzgewicht lässt sich beurteilen, was überflüssig ist",
    "q.t03#5.o1" to "Der Flughafen kontrolliert es",
    "q.t03#5.o2" to "Für soziale Medien",
    "q.t03#5.o3" to "Es hat keinen praktischen Nutzen",
    "q.t03#5.e" to "Wiegen verwandelt «fühlt sich schwer an» in eine Zahl. Doppeltes Geschirr, überzählige Kleidung und volle Flaschen kosten bei demselben Rucksack oft zwei bis drei Kilogramm.",

    "q.t03#6.p" to "Welcher Anteil des Körpergewichts wird als Obergrenze für Wanderrucksäcke häufig empfohlen?",
    "q.t03#6.o0" to "20–25 %",
    "q.t03#6.o1" to "10 %",
    "q.t03#6.o2" to "40 %",
    "q.t03#6.o3" to "Es gibt keine Obergrenze",
    "q.t03#6.e" to "Darüber steigen Energieaufwand beim Aufstieg und Verletzungsrisiko deutlich. Leichter werden beginnt bei der Ausrüstung, die man nicht mitnimmt.",

    "q.t03#7.p" to "Wozu dienen Trekkingstöcke beim Abstieg vor allem?",
    "q.t03#7.o0" to "Die Knie zu entlasten und einen zusätzlichen Stützpunkt zu geben",
    "q.t03#7.o1" to "Schneller zu sein",
    "q.t03#7.o2" to "Das Rucksackgewicht zu verringern",
    "q.t03#7.o3" to "Zur Selbstverteidigung",
    "q.t03#7.e" to "Beim Abstieg wirken ein Vielfaches der Kräfte des Aufstiegs auf die Knie. Stöcke verlagern einen Teil der Last auf den Oberkörper und geben einen dritten Kontaktpunkt.",
    // ---------- t04 Tempo, Flüssigkeit und Energie ----------
    "q.t04#0.p" to "Wie hält man am Anstieg ein durchhaltbares Tempo?",
    "q.t04#0.o0" to "Mit einer Intensität, bei der man noch ganze Sätze sprechen kann, und Pausen vor der Erschöpfung",
    "q.t04#0.o1" to "In einem Zug bis oben durchgehen und dann pausieren",
    "q.t04#0.o2" to "Bei der schnellsten Person mitgehen",
    "q.t04#0.o3" to "Durchgehend sehr langsam gehen",
    "q.t04#0.e" to "Der Sprechtest ist das einfachste Intensitätsmass. Wer keinen ganzen Satz mehr herausbringt, sollte Tempo herausnehmen; wer erst pausiert, wenn er nach Luft ringt, braucht viel länger zur Erholung.",

    "q.t04#1.p" to "Wie ist der richtige Rhythmus beim Trinken?",
    "q.t04#1.o0" to "Trinken, wenn man Durst hat",
    "q.t04#1.o1" to "Alle 20–30 Minuten kleine Schlucke, bei Hitze mit Elektrolyten",
    "q.t04#1.o2" to "Einmal einen Liter trinken",
    "q.t04#1.o3" to "Möglichst wenig trinken, um Toilettengänge zu sparen",
    "q.t04#1.e" to "Wenn Durst auftritt, fehlen bereits etwa 1–2 % des Körpergewichts an Wasser, und Urteilsvermögen wie Ausdauer lassen nach. Regelmässige kleine Schlucke werden besser aufgenommen als ein Liter auf einmal.",

    "q.t04#2.p" to "Wie ist Energie unterwegs wirksamer zuzuführen?",
    "q.t04#2.o0" to "30–60 g Kohlenhydrate pro Stunde, in kleinen Portionen",
    "q.t04#2.o1" to "Erst bei Hunger eine grosse Mahlzeit",
    "q.t04#2.o2" to "Nur Sportgetränke",
    "q.t04#2.o3" to "Mit Willenskraft bis ins Lager durchhalten",
    "q.t04#2.e" to "Der Körper kann pro Stunde nur begrenzt Kohlenhydrate aufnehmen; zu viel auf einmal bläht nur den Magen. Im Gehen zu essen – Nüsse, Riegel, Brot – ist verlässlicher als eine grosse Pause mit viel Essen.",

    "q.t04#3.p" to "Welche frühen Anzeichen einer Unterzuckerung gibt es?",
    "q.t04#3.o0" to "Zitternde Hände, kalter Schweiss",
    "q.t04#3.o1" to "Plötzliche Gereiztheit oder verlangsamte Reaktion",
    "q.t04#3.o2" to "Weisse, flimmernde Sicht",
    "q.t04#3.o3" to "Plötzlich viel mehr Energie",
    "q.t04#3.e" to "Treten diese Zeichen auf, sofort anhalten und 15–20 g schnell verfügbare Kohlenhydrate essen (Zucker, Saft); binnen zehn Minuten bessert es sich deutlich. Weiterzudrücken kann zum Kollaps führen.",

    "q.t04#4.p" to "Warum sollten Pausen nicht länger als zehn Minuten dauern?",
    "q.t04#4.o0" to "Der Körper kühlt aus, die Muskeln werden steif, der Wiedereinstieg kostet mehr Kraft",
    "q.t04#4.o1" to "Die Mitgehenden beschweren sich",
    "q.t04#4.o2" to "Es kostet Zeit",
    "q.t04#4.o3" to "Dafür gibt es keinen Grund",
    "q.t04#4.e" to "Nach langem Stillstand sinken Herzfrequenz und Muskelwärme; der erste Kilometer danach fühlt sich besonders schwer an. Mehrere kurze Pausen kosten in Summe weniger Zeit als eine lange.",

    "q.t04#5.p" to "Wann kommt es beim Wandern typischerweise zum «Man-with-the-Hammer»-Einbruch?",
    "q.t04#5.o0" to "Nach zwei bis drei Stunden, wenn die Glykogenspeicher leer sind und vorher kaum etwas zugeführt wurde",
    "q.t04#5.o1" to "Am ersten Tag vor dem Start",
    "q.t04#5.o2" to "Beim Abstieg",
    "q.t04#5.o3" to "Bei Schlafmangel",
    "q.t04#5.e" to "Die Glykogenspeicher reichen etwa 90–120 Minuten mittlerer Belastung. Wer danach keine Kohlenhydrate zuführt, erlebt plötzlichen Kraftverlust, Schwindel und Sprachlosigkeit.",

    "q.t04#6.p" to "Was ist der praktischste subjektive Massstab für das richtige Tempo?",
    "q.t04#6.o0" to "Der Sprechtest – man kann noch ganze Sätze sprechen",
    "q.t04#6.o1" to "Die Herzfrequenzzahl",
    "q.t04#6.o2" to "Die Menge des Schweisses",
    "q.t04#6.o3" to "Die Schrittfrequenz",
    "q.t04#6.e" to "Ganze Sätze bedeuten, dass man noch im aeroben Bereich ist. Wer nicht mehr sprechen kann, ist zu intensiv unterwegs und läuft auf langen Strecken früher leer.",

    "q.t04#7.p" to "Wann werden Elektrolyte bei Hitze am häufigsten vergessen?",
    "q.t04#7.o0" to "Vor dem Start und in der ersten Hälfte der Tour – nicht erst, wenn Krämpfe auftreten",
    "q.t04#7.o1" to "Nach dem Abstieg",
    "q.t04#7.o2" to "Vor dem Schlafen",
    "q.t04#7.o3" to "Beim Essen",
    "q.t04#7.e" to "Krämpfe zeigen, dass das Defizit schon besteht. Wenig, früh und über die ganze Strecke verteilt ist wirksamer als nachträglich viel zu trinken.",

    // ---------- t15 Karte und Navigation in der Praxis ----------
    "q.t15#0.p" to "Was ist vor dem Aufbruch in die Berge bei Handykarten am wichtigsten?",
    "q.t15#0.o0" to "Offline-Karten herunterladen und prüfen, ob die Positionsbestimmung offline funktioniert",
    "q.t15#0.o1" to "Den Cache leeren",
    "q.t15#0.o2" to "Auf Nachtmodus umstellen",
    "q.t15#0.o3" to "Energiesparmodus einschalten",
    "q.t15#0.e" to "Offline-Karte plus Offline-Track ist die einzige Lösung, die bei «Akku da, kein Netz» noch funktioniert.",

    "q.t15#1.p" to "Auf einer Karte 1:50.000 entsprechen 2 cm wie vielen Metern in der Natur?",
    "q.t15#1.o0" to "1.000 m",
    "q.t15#1.o1" to "100 m",
    "q.t15#1.o2" to "500 m",
    "q.t15#1.o3" to "2.000 m",
    "q.t15#1.e" to "1 cm entspricht 500 m, also 2 cm gleich 1.000 m. Ein Rechenfehler im Massstab zieht alle weiteren Fehler nach sich.",

    "q.t15#2.p" to "Was bedeutet es, wenn Höhenlinien enger zusammenrücken?",
    "q.t15#2.o0" to "Der Hang ist steiler",
    "q.t15#2.o1" to "Der Hang ist flacher",
    "q.t15#2.o2" to "Die Höhe ist grösser",
    "q.t15#2.o3" to "Der Weg ist breiter",
    "q.t15#2.e" to "Enger bedeutet mehr Höhenunterschied auf derselben Horizontalstrecke. Daran erkennt man, ob ein Abschnitt anstrengend wird.",

    "q.t15#3.p" to "Wie bestimmt man im Gelände am zuverlässigsten die Richtung, ohne Elektronik?",
    "q.t15#3.o0" to "Kompass plus Karte",
    "q.t15#3.o1" to "Am Wuchs der Bäume",
    "q.t15#3.o2" to "An der Zugrichtung der Wolken",
    "q.t15#3.o3" to "Nach Gefühl",
    "q.t15#3.e" to "Vegetation und Wolken taugen nur als Zusatzhinweis und sind fehleranfällig. Kompass und Karte sind die einzige stabile Kombination.",

    "q.t15#4.p" to "Man vermutet, sich verlaufen zu haben. Was ist der erste Schritt?",
    "q.t15#4.o0" to "Anhalten und über drei markante Geländepunkte die eigene Position prüfen",
    "q.t15#4.o1" to "Weitergehen und den Weg suchen",
    "q.t15#4.o2" to "Das Tempo erhöhen",
    "q.t15#4.o3" to "Freunde anrufen",
    "q.t15#4.e" to "Anhalten und zurückblicken ist die einzige Möglichkeit, aus «ich glaube, wir sind falsch» ein «wir sind falsch» zu machen. Weiterzugehen vergrössert nur den Fehler.",

    "q.t15#5.p" to "Was gehört vorab in ein Offline-Navigationspaket?",
    "q.t15#5.o0" to "Offline-Karte",
    "q.t15#5.o1" to "Routentrack (GPX)",
    "q.t15#5.o2" to "Ersatzstrom",
    "q.t15#5.o3" to "Social-Media-Apps",
    "q.t15#5.e" to "Die ersten drei sichern, dass es «ohne Netz» funktioniert. Social-Media-Apps helfen in den Bergen ohne Netz nicht.",

    "q.t15#6.p" to "Bringe eine Standortbestimmung in die richtige Reihenfolge.",
    "q.t15#6.o0" to "Offline-Karte öffnen und die aktuelle Position bestimmen",
    "q.t15#6.o1" to "Mit dem Gelände abgleichen: welche Hangseite, welcher Verlauf der Höhenlinien",
    "q.t15#6.o2" to "Den nächsten markanten Geländepunkt festlegen",
    "q.t15#6.o3" to "Richtung und Restdistanz bestimmen",
    "q.t15#6.e" to "Standortbestimmung heisst nicht «auf den blauen Punkt schauen», sondern «blauer Punkt passt zum Gelände». Der zweite Schritt ist der entscheidende.",

    "q.t15#7.p" to "Jemand sagt «einfach den Leuten nachlaufen, dann kann nichts schiefgehen». Was ist die beste Antwort?",
    "q.t15#7.o0" to "Die Leute können ein anderes Ziel haben – erst die Route prüfen, dann folgen",
    "q.t15#7.o1" to "Nachlaufen ist am einfachsten",
    "q.t15#7.o2" to "Viele Leute bedeuten Sicherheit",
    "q.t15#7.o3" to "Kurz nachfragen genügt",
    "q.t15#7.e" to "An Wegkreuzungen sind die «Leute» oft auf einer anderen Route. Einmal auf die Karte zu schauen kostet zehn Sekunden.",

    // ---------- t05 Mehrtagestouren planen ----------
    "q.t05#0.p" to "Was wird bei der Planung einer Mehrtagestour zuerst festgelegt?",
    "q.t05#0.o0" to "Die Obergrenzen für Tagesdistanz und Aufstieg sowie Versorgungs- und Ausstiegspunkte",
    "q.t05#0.o1" to "Welche Sehenswürdigkeiten an der Strecke liegen",
    "q.t05#0.o2" to "In welchem Gasthof man übernachtet",
    "q.t05#0.o3" to "Welche Fotos man macht",
    "q.t05#0.e" to "Erst die Linie «wie viel ist pro Tag maximal machbar» ziehen, dann die Route hineinlegen. Umgekehrt entstehen Pläne, die man nicht schafft – und dann nachts weiterlaufen muss.",

    "q.t05#1.p" to "Wozu dient ein Reservetag?",
    "q.t05#1.o0" to "Damit Verzögerungen durch Wetter oder Verletzungen nicht in Nachtmärsche umgewandelt werden",
    "q.t05#1.o1" to "Um länger zu schlafen",
    "q.t05#1.o2" to "Für Fotos",
    "q.t05#1.o3" to "Er hat keinen praktischen Nutzen",
    "q.t05#1.e" to "Auf Mehrtagestouren kommt es fast immer zu Verzögerungen. Mit Reservetag fällt ein Abschnitt weg; ohne Reservetag wird daraus ein Nachtmarsch oder ein erzwungener Durchstieg durch gefährliches Gelände.",

    "q.t05#2.p" to "Welche Zeitposten werden am leichtesten unterschätzt?",
    "q.t05#2.o0" to "Wegsuche und Kurskorrekturen",
    "q.t05#2.o1" to "Wasserholen und Filtern",
    "q.t05#2.o2" to "Zeltaufbau, Kochen, Packen",
    "q.t05#2.o3" to "Gehen auf flachem Weg",
    "q.t05#2.e" to "Die Kartendistanz deckt nur das Gehen ab. Tatsächlich kommen pro Tag Wegsuche, Wasserholen, Zeltaufbau, Kochen und Packen dazu – zusammen meist 1,5–2 Stunden.",

    "q.t05#3.p" to "Wie dicht sollten Ausstiegspunkte liegen?",
    "q.t05#3.o0" to "Mindestens ein möglicher Abstieg oder ein Dorf pro Tag",
    "q.t05#3.o1" to "Einer für die ganze Tour genügt",
    "q.t05#3.o2" to "Nicht nötig",
    "q.t05#3.o3" to "Einer alle fünf Tage",
    "q.t05#3.e" to "Zu weit auseinanderliegende Ausstiege schreiben «du musst durchhalten» in den Plan. Nur wenn für jeden Abschnitt der nächste Abstieg bekannt ist, gibt es echte Wahlfreiheit.",

    "q.t05#4.p" to "Warum sollte der längste Tag nicht der erste sein?",
    "q.t05#4.o0" to "Am ersten Tag sind Zustand und Urteilsvermögen am schlechtesten; Rucksackgewicht und Höhe sind noch ungewohnt",
    "q.t05#4.o1" to "Am ersten Tag ist die Aussicht schlechter",
    "q.t05#4.o2" to "Am ersten Tag regnet es meist",
    "q.t05#4.o3" to "Es macht keinen Unterschied",
    "q.t05#4.e" to "Der Körper braucht ein bis zwei Tage Anpassung: Schultern an das Gewicht, Füsse an die Schuhe, der Mensch an den Rhythmus. Den härtesten Tag in die Mitte zu legen erhöht die Erfolgsquote und senkt das Verletzungsrisiko.",

    "q.t05#5.p" to "Im Plan steht «voraussichtliche Ankunft in 6 Stunden». Was fehlt?",
    "q.t05#5.o0" to "Eine späteste Ankunftszeit, ab der der Alternativplan greift",
    "q.t05#5.o1" to "Die erwartete Temperatur",
    "q.t05#5.o2" to "Die Telefonnummer der Mitgehenden",
    "q.t05#5.o3" to "Nichts weiter",
    "q.t05#5.e" to "Die erwartete Zeit ist eine Erwartung, die späteste Zeit eine Entscheidungslinie. Ist sie überschritten, wird das Reservecamp genutzt oder umgekehrt – statt weiter zu hoffen.",

    "q.t05#6.p" to "Warum braucht eine Mehrtagestour Reservetage?",
    "q.t05#6.o0" to "Wetter, Verletzungen und Transportverzögerungen kosten Zeit; ohne Reservetag wird die Sicherheitsreserve zusammengestrichen",
    "q.t05#6.o1" to "Zum Ausruhen",
    "q.t05#6.o2" to "Für Fotos",
    "q.t05#6.o3" to "Um Geld zu sparen",
    "q.t05#6.e" to "Der Reservetag ist Teil des Plans. Wer ihn für Verschwendung hält, streicht am Ende die Pausen und die Sicherheit.",

    "q.t05#7.p" to "Wann sollte man auf einer Mehrtagestour am Lager ankommen?",
    "q.t05#7.o0" to "Mit 1–2 Stunden Tageslicht für Zeltaufbau und Kochen",
    "q.t05#7.o1" to "Kurz vor Einbruch der Dunkelheit",
    "q.t05#7.o2" to "Je später, desto kühler",
    "q.t05#7.o3" to "Das ist egal",
    "q.t05#7.e" to "Im Dunkeln aufzubauen ist sehr ineffizient und lässt Gefahren am Lagerplatz übersehen. Die Ankunftszeit im Plan festzuhalten ist Disziplin.",

    // ---------- t06 Lagerplatz und Zelten ----------
    "q.t06#0.p" to "Wie weit sollte ein Lagerplatz mindestens vom Wasser entfernt sein?",
    "q.t06#0.o0" to "5 m",
    "q.t06#0.o1" to "60 m",
    "q.t06#0.o2" to "200 m",
    "q.t06#0.o3" to "Je näher, desto besser",
    "q.t06#0.e" to "60 m ist die Mindestanforderung in den meisten Schutzgebieten. Zu nah bedeutet Verunreinigung und Begegnungen mit Tieren, die nachts zur Tränke kommen. Waschen und Abspülen ebenfalls mindestens 60 m vom Wasser entfernt.",

    "q.t06#1.p" to "Welche Plätze sind für ein Lager zu meiden?",
    "q.t06#1.o0" to "Steinschlagbereich direkt unter einem Steilhang",
    "q.t06#1.o1" to "Ausgetrocknetes Flussbett",
    "q.t06#1.o2" to "Unter einem einzelnstehenden grossen Baum",
    "q.t06#1.o3" to "Stellen, die ein Wildwechsel quert",
    "q.t06#1.e" to "Alle vier sind Plätze, an denen «normalerweise nichts passiert» – und wenn, dann schwer: Steinschlag, Sturzflut, Blitzschlag, Tiere. Ein Lager steht die ganze Nacht still, hier gibt es keinen Spielraum.",

    "q.t06#2.p" to "Warum sollte der Lagerboden leicht geneigt sein?",
    "q.t06#2.o0" to "Damit Wasser abläuft und sich bei Regen keine Pfütze bildet",
    "q.t06#2.o1" to "Weil man besser schläft",
    "q.t06#2.o2" to "Weil es ordentlicher aussieht",
    "q.t06#2.o3" to "Damit sich das Zelt nicht verformt",
    "q.t06#2.e" to "Völlig ebene Flächen sammeln bei Starkregen Wasser. Bei 2–3° Gefälle läuft es ab, und mit dem Kopf etwas höher liegt man stabil, ohne nach unten zu rutschen.",

    "q.t06#3.p" to "Wie wird das Zelt am stabilsten ausgerichtet?",
    "q.t06#3.o0" to "Eingang im Windschatten, Längsseite im Wind",
    "q.t06#3.o1" to "Eingang gegen den Wind",
    "q.t06#3.o2" to "Beliebig",
    "q.t06#3.o3" to "Zur Sonne ausgerichtet",
    "q.t06#3.e" to "Eingang im Windschatten verhindert, dass beim Ein- und Aussteigen Wind und Regen hineinschlagen. Steht die Längsseite im Wind, ist die Angriffsfläche am kleinsten und die Gestängebögen werden gleichmässiger belastet.",

    "q.t06#4.p" to "Warum zeltet man nicht auf einem Grat?",
    "q.t06#4.o0" to "Starker Wind und hohes Blitzschlagrisiko",
    "q.t06#4.o1" to "Die Aussicht ist zu offen",
    "q.t06#4.o2" to "Der Boden ist zu hart",
    "q.t06#4.o3" to "Zu nah am Wasser",
    "q.t06#4.e" to "Ein Grat ist der höchste Punkt im Gelände: Wind hat keine Deckung, und bei Gewitter ist es die exponierteste Stelle. Das Lager gehört auf die windabgewandte, etwas tiefere Seite.",

    "q.t06#5.p" to "Was ist nach dem Abbau des Lagers zu tun?",
    "q.t06#5.o0" to "Den Boden wiederherstellen, allen Abfall mitnehmen und prüfen, ob etwas liegen bleibt",
    "q.t06#5.o1" to "Einfach gehen",
    "q.t06#5.o2" to "Abfall im Boden vergraben",
    "q.t06#5.o3" to "Feuerholz für die nächsten liegen lassen",
    "q.t06#5.e" to "Der Platz wird auch von anderen genutzt. Heringe, Verpackungen und Essensreste zu kontrollieren und niedergetretenes Gras möglichst zu richten ist das Minimum an Anstand.",

    // ---------- t07 Kochen und Essensplanung ----------
    "q.t07#0.p" to "Wie wird der Brennstoffbedarf grob geschätzt?",
    "q.t07#0.o0" to "30–50 g Gaskartusche pro Person und Tag",
    "q.t07#0.o1" to "200 g pro Person und Tag",
    "q.t07#0.o2" to "50 g pro Gruppe und Tag",
    "q.t07#0.o3" to "Eine Schätzung ist nicht nötig",
    "q.t07#0.e" to "Für übliche Touren, bei denen vor allem Wasser gekocht wird, sind 30–50 g pro Person und Tag verlässlich. Kälte, Schneeschmelzen und viel Kochen erhöhen den Bedarf – besser eine Reservekartusche mitnehmen.",

    "q.t07#1.p" to "Welche Eigenschaften stehen bei der Essensplanung vorn?",
    "q.t07#1.o0" to "Hohe Energiedichte",
    "q.t07#1.o1" to "Gut haltbar, verdirbt nicht",
    "q.t07#1.o2" to "Wenig Waschen, wenig Topfschrubben",
    "q.t07#1.o3" to "Braucht langes Schmoren",
    "q.t07#1.e" to "Jedes Gramm im Rucksack kostet Kraft, jede Minute im Topf kostet Brennstoff. Trekkingnahrung, Nüsse, Haferflocken und Brot – «Wasser dazu, fertig» – ist am günstigsten.",

    "q.t07#2.p" to "Warum sind in der Höhe Kohlenhydrate zu bevorzugen?",
    "q.t07#2.o0" to "Sie brauchen bei der Verdauung wenig Sauerstoff, werden schnell umgesetzt und liefern rasch nutzbare Energie",
    "q.t07#2.o1" to "Sie sind billiger",
    "q.t07#2.o2" to "Sie sind leichter",
    "q.t07#2.o3" to "Es gibt keinen Unterschied",
    "q.t07#2.e" to "Fett hat pro Gramm mehr Energie, braucht im Stoffwechsel aber mehr Sauerstoff. Bei Sauerstoffmangel sind Kohlenhydrate der «sauerstoffsparende» Brennstoff.",

    "q.t07#3.p" to "Was ist beim Kocher im Zelt am wichtigsten?",
    "q.t07#3.o0" to "Für Lüftung sorgen und einer Kohlenmonoxidvergiftung vorbeugen",
    "q.t07#3.o1" to "Die Flamme klein halten",
    "q.t07#3.o2" to "Nicht sprechen",
    "q.t07#3.o3" to "Erst mit einer Kerze vorheizen",
    "q.t07#3.e" to "Die Frühsymptome einer CO-Vergiftung – Kopfschmerz, Müdigkeit – sind von Höhenkrankheit und Erschöpfung kaum zu unterscheiden, und es passiert meist im Schlaf. Das Zelt braucht zwingend eine Lüftungsöffnung.",

    "q.t07#4.p" to "Wie wird Wasser aus dem Gelände am zuverlässigsten aufbereitet?",
    "q.t07#4.o0" to "Eine Minute abkochen",
    "q.t07#4.o1" to "Durch ein Tuch filtern",
    "q.t07#4.o2" to "Absetzen lassen",
    "q.t07#4.o3" to "Zucker zugeben",
    "q.t07#4.e" to "Abkochen tötet Bakterien, Viren und Parasiten. Filter wirken gegen Viren nur begrenzt, chemische Tabletten brauchen Wartezeit. In der Höhe ist der Siedepunkt niedriger, dort die Kochzeit entsprechend verlängern.",

    "q.t07#5.p" to "Wie wird Essen am besten portioniert?",
    "q.t07#5.o0" to "Tageweise abpacken und beschriften, damit beim Herausnehmen nicht der ganze Sack durchwühlt wird",
    "q.t07#5.o1" to "Alles in einen grossen Sack",
    "q.t07#5.o2" to "Originalverpackt in den Rucksack stopfen",
    "q.t07#5.o3" to "Nach Geschmack sortieren",
    "q.t07#5.e" to "Tagesportionen kontrollieren den Verbrauch und verhindern «vorne zu gut, hinten zu wenig». Die Beschriftung sagt zusätzlich, welches Päckchen zuerst dran ist.",

    // ---------- t08 Wetter: Grundlagen ----------
    "q.t08#0.p" to "Welche drei Wetterinformationen sind vor dem Start am wichtigsten?",
    "q.t08#0.o0" to "Trend der nächsten 24–48 Stunden, Niederschlagswahrscheinlichkeit, Wind und gefühlte Temperatur",
    "q.t08#0.o1" to "Die Tageshöchsttemperatur",
    "q.t08#0.o2" to "Das Wetter von gestern",
    "q.t08#0.o3" to "Die Luftfeuchtigkeit",
    "q.t08#0.e" to "«Wie viel Grad heute» sagt wenig. Der Trend entscheidet, ob der Plan geändert wird, die Niederschlagswahrscheinlichkeit, was eingepackt wird, und der Wind bestimmt gefühlte Temperatur und Standfestigkeit im offenen Gelände.",

    "q.t08#1.p" to "Was bedeutet es, wenn der Cumulonimbus oben zu einer Ambossform ausläuft?",
    "q.t08#1.o0" to "Das Gewitter ist ausgereift, mit Starkregen, Hagel und Blitzen",
    "q.t08#1.o1" to "Das Wetter klart auf",
    "q.t08#1.o2" to "Nur hohe Wolken, ohne Wirkung",
    "q.t08#1.o3" to "Es schneit gleich",
    "q.t08#1.e" to "Der Amboss zeigt, dass die Aufwinde die Tropopause erreicht haben und die Wolke ihre stärkste Phase hat. Jetzt gilt es, Grat, offenes Gelände und Einzelbäume zu verlassen.",

    "q.t08#2.p" to "Welche Anzeichen können einem Gewitter vorausgehen?",
    "q.t08#2.o0" to "Ferner Donner",
    "q.t08#2.o1" to "Schwarze, absinkende Wolkenbasis",
    "q.t08#2.o2" to "Plötzliche Winddrehung und schneller Temperaturabfall",
    "q.t08#2.o3" to "Aufgestellte Haare, kribbelnde Haut",
    "q.t08#2.e" to "Der letzte Punkt zeigt eine bereits starke Ladung: Ein Einschlag ist nahe. Sofort Höhe verlieren, mit geschlossenen Füssen in die Hocke gehen, nicht flach hinlegen.",

    "q.t08#3.p" to "Was ist bei Gewitter richtig?",
    "q.t08#3.o0" to "Grat und Einzelbäume verlassen, Höhe verlieren, etwa 50 m Abstand zwischen den Personen",
    "q.t08#3.o1" to "Unter den höchsten Baum stellen",
    "q.t08#3.o2" to "Schnell über den Grat weitergehen",
    "q.t08#3.o3" to "Zusammenrücken und sich gegenseitig wärmen",
    "q.t08#3.e" to "Blitze treffen bevorzugt den höchsten Punkt. Der Abstand dient dazu, dass bei einem Treffer die anderen noch helfen können; Zusammenrücken macht aus einem Einschlag mehrere Verletzte.",

    "q.t08#4.p" to "Was ist das früheste und verlässlichste Zeichen einer Unterkühlung?",
    "q.t08#4.o0" to "Anhaltendes Zittern, ungeschickte Bewegungen, verwaschene Sprache",
    "q.t08#4.o1" to "Gerötete Haut",
    "q.t08#4.o2" to "Starkes Schwitzen",
    "q.t08#4.o3" to "Langsamer Herzschlag",
    "q.t08#4.e" to "Zittern ist die Selbstrettung des Körpers über Wärmeproduktion. Dass das Zittern aufhört, ist keine Besserung, sondern kann ein schwereres Zeichen sein. Reihenfolge: Windschutz, trockene Kleidung, Isolation, warmes Getränk.",

    "q.t08#5.p" to "Warum fühlt sich dieselbe Temperatur mit Wind kälter an?",
    "q.t08#5.o0" to "Der Wind beschleunigt den Wärmeverlust an der Hautoberfläche; die gefühlte Temperatur liegt deutlich unter der Lufttemperatur",
    "q.t08#5.o1" to "Der Wind bläst kalte Luft in die Kleidung",
    "q.t08#5.o2" to "Reine Psychologie",
    "q.t08#5.o3" to "Veränderte Luftfeuchtigkeit",
    "q.t08#5.e" to "Das ist der Windchill-Effekt. 0 °C bei 40 km/h fühlen sich etwa wie -10 °C an. Wie viel man anzieht, richtet sich nach der gefühlten Temperatur, nicht nach der Zahl auf dem Thermometer.",
    // ---------- t16 Lagerleben und Hygiene im Gelände ----------
    "q.t16#0.p" to "Wie werden die drei Zonen eines Lagers grundsätzlich geteilt?",
    "q.t16#0.o0" to "Schlafen, Kochen und Toilette getrennt",
    "q.t16#0.o1" to "Männer, Frauen, gemeinsam",
    "q.t16#0.o2" to "Zelt, Fahrzeug, Feuer",
    "q.t16#0.o3" to "Eine Teilung ist nicht nötig",
    "q.t16#0.e" to "Die Zonenteilung löst drei Probleme: Brandgefahr durch offenes Feuer, Gerüche, die Tiere anziehen, und hygienische Kreuzkontamination.",

    "q.t16#1.p" to "Welche Tiefe und welcher Abstand zum Wasser sind für ein Katzengrab angemessen?",
    "q.t16#1.o0" to "15–20 cm tief, mindestens 60 m vom Wasser entfernt",
    "q.t16#1.o1" to "5 cm tief, 5 m vom Wasser",
    "q.t16#1.o2" to "Je tiefer und je weiter, desto besser",
    "q.t16#1.o3" to "Graben ist nicht nötig",
    "q.t16#1.e" to "Zu flach zersetzt sich nichts, zu nah wird das Wasser verunreinigt. 60 m ist der übliche Abstand.",

    "q.t16#2.p" to "Wie ist Toilettenpapier richtig zu behandeln?",
    "q.t16#2.o0" to "In einen Beutel und mitnehmen",
    "q.t16#2.o1" to "Verbrennen",
    "q.t16#2.o2" to "Mit in das Katzengrab legen",
    "q.t16#2.o3" to "Ins Gras werfen",
    "q.t16#2.e" to "Papier zu verbrennen birgt in der Trockenzeit Brandgefahr; vergraben kommt es beim Abschmelzen oder durch wühlende Tiere wieder hervor. Mitnehmen ist am saubersten.",

    "q.t16#3.p" to "Wie ist Abwaschwasser richtig zu entsorgen?",
    "q.t16#3.o0" to "Reste herausfiltern und mitnehmen, das Wasser breitflächig ausgiessen",
    "q.t16#3.o1" to "Direkt in den Bach schütten",
    "q.t16#3.o2" to "Neben das Zelt giessen",
    "q.t16#3.o3" to "In das Katzengrab giessen",
    "q.t16#3.e" to "Reste verunreinigen und locken Tiere an, also herausfiltern und mitnehmen; das restliche Wasser breit verteilt ausgiessen, nicht an einer Stelle sammeln.",

    "q.t16#4.p" to "Was sind die drei wichtigsten Punkte der Fusspflege beim Wandern?",
    "q.t16#4.o0" to "Täglich Füsse waschen, trockene Socken anziehen, Schuhe lüften",
    "q.t16#4.o1" to "Viel gehen",
    "q.t16#4.o2" to "Dicke Socken tragen",
    "q.t16#4.o3" to "Salbe auftragen",
    "q.t16#4.e" to "Blasen und Aufweichungen entstehen aus Nässe plus Reibung. Trockenheit hilft mehr als jede Salbe.",

    "q.t16#5.p" to "Was ist bei der Lagerhygiene zu vermeiden?",
    "q.t16#5.o0" to "Im Zelt essen",
    "q.t16#5.o1" to "Essensreste im Lager liegen lassen",
    "q.t16#5.o2" to "Geschirr am Wasser spülen",
    "q.t16#5.o3" to "Schuhe über Nacht in die Apsis stellen",
    "q.t16#5.e" to "Die ersten drei bringen Tiere und Verunreinigung in den Schlafbereich. Schuhe in die Apsis ist üblich – vorher aber ausschütteln.",

    "q.t16#6.p" to "Bringe das morgendliche Lagerabräumen in die richtige Reihenfolge.",
    "q.t16#6.o0" to "Zuerst den Schlafsack einpacken und in den Packsack",
    "q.t16#6.o1" to "Kleinteile und Abfall im Zelt einsammeln",
    "q.t16#6.o2" to "Zelt abbauen, Tau und Reif abschütteln",
    "q.t16#6.o3" to "Den Platz kontrollieren und sicherstellen, dass nichts zurückbleibt",
    "q.t16#6.e" to "Der letzte Schritt wird am häufigsten ausgelassen: liegen gelassene Dinge sind der häufigste Minuspunkt beim Thema Spurenfreiheit.",

    "q.t16#7.p" to "In der Nähe des Lagers finden sich Tierspuren (Losung, Wühlstellen). Was ist zu tun?",
    "q.t16#7.o0" to "Essen hoch aufhängen oder dicht verschlossen und weit weg vom Schlafbereich lagern",
    "q.t16#7.o1" to "Einfach weiter dort kochen",
    "q.t16#7.o2" to "Dem Tier etwas zu fressen geben",
    "q.t16#7.o3" to "Das Essen ins Zelt stellen",
    "q.t16#7.e" to "Tiere werden vom Geruch angezogen. Essen ins Zelt zu nehmen ist die gefährlichste Variante – es lockt das Tier direkt dorthin, wo man schläft.",

    // ---------- t18 Flussquerung: Beurteilung und Stellenwahl ----------
    "q.t18#0.p" to "Welche Grössenkombination entscheidet am stärksten, ob eine Furt machbar ist?",
    "q.t18#0.o0" to "Wassertiefe × Fliessgeschwindigkeit",
    "q.t18#0.o1" to "Die Wassertiefe",
    "q.t18#0.o2" to "Die Flussbreite",
    "q.t18#0.o3" to "Die Wassertemperatur",
    "q.t18#0.e" to "Bei gleicher Tiefe bedeutet doppelte Geschwindigkeit doppelte Kraftwirkung. Nur die Tiefe zu messen ist die häufigste Fehleinschätzung beim Wandern.",

    "q.t18#1.p" to "Wo liegt die technische Sicherheitsgrenze für eine Furt?",
    "q.t18#1.o0" to "Tiefe × Geschwindigkeit über 1,0 Quadratmeter pro Sekunde gilt als nicht mehr begehbar",
    "q.t18#1.o1" to "Tiefe über 0,5 m",
    "q.t18#1.o2" to "Geschwindigkeit über 3 m/s",
    "q.t18#1.o3" to "Breite über 20 m",
    "q.t18#1.e" to "1,0 gilt für gesunde Erwachsene, kurze Strecken, ohne schwere Last. Teams können intern bei 0,8 bleiben – das ist aber konservative Praxis, kein Standard.",

    "q.t18#2.p" to "Wie wird die Fliessgeschwindigkeit mit einem Ast abgeschätzt?",
    "q.t18#2.o0" to "Wenn man am Ufer traben muss, um mitzukommen, ist sie schneller als Schrittgeschwindigkeit",
    "q.t18#2.o1" to "Ob der Ast untergeht",
    "q.t18#2.o2" to "Ob sich der Ast dreht",
    "q.t18#2.o3" to "Ob es Schaum auf dem Wasser gibt",
    "q.t18#2.e" to "Am Ufer mitzugehen ist die direkteste Messmethode. Muss man traben, ist die Strömung bereits zu stark.",

    "q.t18#3.p" to "Ab welcher Tiefe sollte eine andere Stelle gesucht werden?",
    "q.t18#3.o0" to "Oberschenkelhöhe der kleinsten Person im Team",
    "q.t18#3.o1" to "Hüfthöhe der Tourenleitung",
    "q.t18#3.o2" to "Kniehöhe",
    "q.t18#3.o3" to "Brusthöhe",
    "q.t18#3.e" to "Gerechnet wird nach der kleinsten Person, nicht nach der stärksten. Das Team wird von der schwächsten Person begrenzt – das ist die eherne Regel bei Flussquerungen.",

    "q.t18#4.p" to "Was ist der «Run-out»?",
    "q.t18#4.o0" to "Der Bereich flussabwärts, in den die Strömung eine gestürzte Person treiben würde",
    "q.t18#4.o1" to "Der Steilhang am Ufer",
    "q.t18#4.o2" to "Das Gefälle des Flussbetts",
    "q.t18#4.o3" to "Das Einzugsgebiet flussaufwärts",
    "q.t18#4.e" to "Gibt es im Run-out Wasserfälle, Treibholz oder Steilufer, ist diese Stelle unbrauchbar – selbst wenn das Wasser vor einem flach wirkt.",

    "q.t18#5.p" to "Wonach sucht man bei der Wahl einer Furt zuerst?",
    "q.t18#5.o0" to "Breite, flache Flussabschnitte",
    "q.t18#5.o1" to "Enge, tiefe Abschnitte",
    "q.t18#5.o2" to "Die Aussenseite einer Kurve",
    "q.t18#5.o3" to "Die Nähe von Treibholz",
    "q.t18#5.e" to "Je breiter der Fluss, desto flacher und langsamer ist er meist; an der Kurvenaussenseite ist es tief und schnell, und Treibholz ist eine tödliche Falle.",

    "q.t18#6.p" to "Wie viel Wasserstandsanstieg genügt, um eine vorher sichere Stelle gefährlich zu machen?",
    "q.t18#6.o0" to "15 cm",
    "q.t18#6.o1" to "1 m",
    "q.t18#6.o2" to "50 cm",
    "q.t18#6.o3" to "So wenig ändert nichts",
    "q.t18#6.e" to "15 cm verändern Tiefe und Geschwindigkeit bereits deutlich – besonders im Bereich von Gletscherschmelzwasser.",

    "q.t18#7.p" to "In welchen Fällen ist die Furtstelle sofort aufzugeben?",
    "q.t18#7.o0" to "Der Grund ist nicht sichtbar, das Wasser trüb",
    "q.t18#7.o1" to "Flussabwärts liegen Treibholz oder Steilufer",
    "q.t18#7.o2" to "Flussaufwärts hat es gerade stark geregnet",
    "q.t18#7.o3" to "Das Flussbett ist eine flache Kiesbank",
    "q.t18#7.e" to "Die ersten drei bedeuten «nicht beurteilbar» oder «ein Fehler ist nicht verkraftbar». Eine Kiesbank ist dagegen genau das gute Flussbett.",

    "q.t18#8.p" to "Was muss vor der Querung an der Ausrüstung erledigt werden?",
    "q.t18#8.o0" to "Brustgurt öffnen",
    "q.t18#8.o1" to "Schultergurte lockern",
    "q.t18#8.o2" to "Aussenbefestigungen straffen, damit nichts Wasser fängt",
    "q.t18#8.o3" to "Handy und Medikamente wasserdicht verpacken",
    "q.t18#8.e" to "Die ersten beiden ermöglichen, den Rucksack abzuwerfen, die letzten beiden sichern kritisches Material. Alle vier Punkte werden vor dem Einstieg erledigt.",

    "q.t18#9.p" to "Bringe die Entscheidungsfolge bei einer Flussquerung in die richtige Reihenfolge.",
    "q.t18#9.o0" to "Zuerst fragen: Muss ich überhaupt queren? (Umweg, Brücke, Wasserstand abwarten)",
    "q.t18#9.o1" to "Stelle wählen und Tiefe sowie Geschwindigkeit messen",
    "q.t18#9.o2" to "Einheitliches Vorgehen für Rucksack und Kleidung im Team festlegen",
    "q.t18#9.o3" to "In Formation oder einzeln queren",
    "q.t18#9.e" to "Die erste Frage eliminiert den grössten Teil des Risikos. Viele überspringen sie und beginnen sofort mit der Frage, wie man hinüberkommt.",

    "q.t18#10.p" to "Der Fluss führt nachmittags deutlich mehr Wasser als am Morgen. Woran liegt das vor allem?",
    "q.t18#10.o0" to "Am Tagesgang des Gletscherschmelzwassers mit dem Höchstwert am Nachmittag",
    "q.t18#10.o1" to "Weil es nachmittags mehr regnet",
    "q.t18#10.o2" to "Wegen Wasserablass aus einem Speicher weiter oben",
    "q.t18#10.o3" to "Wegen Verdunstung",
    "q.t18#10.e" to "Schmelzwasserflüsse haben einen sehr regelmässigen Tagesgang: morgens am niedrigsten, nachmittags am höchsten. Querungen möglichst am Vormittag legen.",

    // ---------- t19 Formation und Sturzbehandlung ----------
    "q.t19#0.p" to "Wie wird die Dreiecksformation richtig gebildet?",
    "q.t19#0.o0" to "Drei Personen einander zugewandt, an Schulter oder Rucksack gefasst, jeweils nur eine Person und ein Bein in Bewegung",
    "q.t19#0.o1" to "Drei Personen nebeneinander, Hand in Hand, gemeinsam gehend",
    "q.t19#0.o2" to "Drei Personen hintereinander",
    "q.t19#0.o3" to "Zwei tragen eine Person",
    "q.t19#0.e" to "Gleichzeitiges Ausschreiten lässt die ganze Formation den Halt verlieren. An den Armen zu fassen ist kräfteraubend und rutscht leicht – gefasst wird an Schulter oder Rucksack.",

    "q.t19#1.p" to "Wo stehen in der Querformation die stärksten Personen?",
    "q.t19#1.o0" to "An den Enden, besonders stromaufwärts",
    "q.t19#1.o1" to "In der Mitte",
    "q.t19#1.o2" to "Ganz hinten",
    "q.t19#1.o3" to "Beliebig",
    "q.t19#1.e" to "Das stromaufwärtige Ende nimmt den Hauptstrom auf, das stromabwärtige Ende sichert ab. Unerfahrene stehen in der Mitte, aussen je eine starke Person.",

    "q.t19#2.p" to "Wie lautet der Kommandorhythmus in der Formation?",
    "q.t19#2.o0" to "«Ein Schritt, Stopp, ein Schritt»",
    "q.t19#2.o1" to "«Eins-zwei, eins-zwei» durchgehend",
    "q.t19#2.o2" to "Ohne Kommandos",
    "q.t19#2.o3" to "Jeder geht für sich",
    "q.t19#2.e" to "Der gemeinsame Rhythmus sorgt dafür, dass sich immer nur eine Person bewegt. Gleichzeitiges Ausschreiten ist der häufigste Fehler in der Formation.",

    "q.t19#3.p" to "Was ist die erste Regel nach einem Sturz ins Wasser?",
    "q.t19#3.o0" to "Nicht aufstehen",
    "q.t19#3.o1" to "Sofort aufstehen",
    "q.t19#3.o2" to "Nach dem Seil greifen",
    "q.t19#3.o3" to "Nach Treibholz greifen",
    "q.t19#3.e" to "Der Fuss kann in einer Felsspalte oder unter Treibholz eingeklemmt werden, und die Strömung drückt den Körper unter Wasser («foot entrapment») – der typische Mechanismus tödlicher Flussunfälle.",

    "q.t19#4.p" to "Wie ist die richtige Körperlage nach einem Sturz?",
    "q.t19#4.o0" to "Rückenlage, Füsse flussabwärts und nah an der Oberfläche, Kopf hoch",
    "q.t19#4.o1" to "Bauchlage und schwimmen",
    "q.t19#4.o2" to "Aufrecht Wasser treten",
    "q.t19#4.o3" to "Knie an den Körper ziehen",
    "q.t19#4.e" to "Rückenlage mit Füssen flussabwärts erlaubt, Hindernisse mit den Füssen wegzustossen statt aufzusetzen, und schützt den Kopf.",

    "q.t19#5.p" to "Was gilt für den Hüftgurt des Rucksacks bei einer Flussquerung?",
    "q.t19#5.o0" to "Die US-amerikanische Schule öffnet ihn zum Abwerfen, Neuseeland (MSC) schliesst ihn als Auftrieb – entscheidend ist, dass das ganze Team gleich verfährt",
    "q.t19#5.o1" to "Er muss geöffnet sein",
    "q.t19#5.o2" to "Er muss geschlossen sein",
    "q.t19#5.o3" to "Das spielt keine Rolle",
    "q.t19#5.e" to "Beide Schulen haben ihre Voraussetzungen. Wirklich gefährlich ist «die Hälfte offen, die Hälfte geschlossen» – dann funktioniert bei einer Rettung nichts zusammen.",

    "q.t19#6.p" to "Der Rucksack bleibt an einem Stein hängen. Was ist zu tun?",
    "q.t19#6.o0" to "Beide Arme heben und aus den Schultergurten schlüpfen; lieber den Rucksack verlieren",
    "q.t19#6.o1" to "Kräftig daran ziehen",
    "q.t19#6.o2" to "Tauchen und ihn lösen",
    "q.t19#6.o3" to "Auf die anderen warten",
    "q.t19#6.e" to "Hängt der Rucksack, drückt die Strömung die Person nieder. Arme heben und ausschlüpfen ist die schnellste Befreiung.",

    "q.t19#7.p" to "Wie ist kurz vor dem Ufer richtig vorzugehen?",
    "q.t19#7.o0" to "Erst den Hüftgurt öffnen, dann den stromaufwärtigen Schultergurt abnehmen und den Rucksack als Auftrieb vor den Körper nehmen, um aufzustehen",
    "q.t19#7.o1" to "Erst aufstehen, dann den Rucksack lösen",
    "q.t19#7.o2" to "Den Rucksack ans Ufer werfen",
    "q.t19#7.o3" to "Einfach hochklettern",
    "q.t19#7.e" to "Der Auftrieb des Rucksacks kann helfen, aber in falscher Reihenfolge verliert man den Halt. Erst Hüftgurt, dann der stromaufwärtige Schultergurt – das ist die Standardreihenfolge.",

    "q.t19#8.p" to "Was gehört zur Vorbereitung einer Querung in Formation?",
    "q.t19#8.o0" to "Griffe und Kommandos an Land üben",
    "q.t19#8.o1" to "Festlegen, wer stromaufwärts steht",
    "q.t19#8.o2" to "Einheitliches Vorgehen für Hüft- und Brustgurt",
    "q.t19#8.o3" to "Jeder entscheidet selbst über sein Vorgehen",
    "q.t19#8.e" to "Eine Formation lebt von Abstimmung, und Abstimmung gibt es nur, wenn sie vorher hergestellt wurde. Jeder für sich lässt die Formation im Wasser zerfallen.",

    "q.t19#9.p" to "Was ist über die Sicherung mit Seil bei einer Flussquerung richtig?",
    "q.t19#9.o0" to "Die meisten Teams sind darin nicht geübt; das Risiko kann den Nutzen übersteigen",
    "q.t19#9.o1" to "Das Seil wird nur am Ufer befestigt und niemals am Körper",
    "q.t19#9.o2" to "Man quert auf der stromabwärtigen Seite des Seils",
    "q.t19#9.o3" to "Ein straff gespanntes Querseil über die Strömung ist am sichersten",
    "q.t19#9.e" to "Ein straffes Querseil drückt einen unter Wasser. Seilsicherung ist eine eigene Technik und lässt sich nicht vor Ort erfinden.",

    "q.t19#10.p" to "Bringe eine Querung in Formation in die richtige Reihenfolge.",
    "q.t19#10.o0" to "Stelle wählen und Run-out prüfen",
    "q.t19#10.o1" to "Im Team Brustgurt öffnen und einheitliches Vorgehen beim Hüftgurt festlegen",
    "q.t19#10.o2" to "Formation und Kommandos an Land üben",
    "q.t19#10.o3" to "Nach Kommando gemeinsam seitwärts gehen, jeweils nur eine Person einen Schritt",
    "q.t19#10.o4" to "Am Ufer trockene Kleidung anziehen und heiss trinken",
    "q.t19#10.e" to "Der letzte Schritt wird am leichtesten vergessen: Unterkühlung im kalten Wasser ist oft häufiger als ein Sturz.",

    "q.t19#11.p" to "Eine Person bleibt im Wasser plötzlich stehen. Was ist am wahrscheinlichsten?",
    "q.t19#11.o0" to "Der Fuss ist eingeklemmt; sofort helfen und dafür sorgen, dass sie in Rückenlage bleibt",
    "q.t19#11.o1" to "Sie ruht sich aus",
    "q.t19#11.o2" to "Sie schaut sich die Aussicht an",
    "q.t19#11.o3" to "Sie wartet auf ein Kommando",
    "q.t19#11.e" to "Plötzliches Verharren ist typisch für foot entrapment. In diesem Moment braucht sie vor allem: nicht kämpfen, Rückenlage halten, und jemanden, der von stromaufwärts kommt.",

    // ---------- t21 Nachtmarsch und Gewitter ----------
    "q.t21#0.p" to "Wie ist die vernünftigste Haltung zum Nachtmarsch?",
    "q.t21#0.o0" to "Nur wenn nötig; wenn nötig, langsamer und mit strengerer Gruppenführung",
    "q.t21#0.o1" to "Nachts ist es kühler, gut zum Strecke machen",
    "q.t21#0.o2" to "Nachts ist es sicherer",
    "q.t21#0.o3" to "Hauptsache eine Stirnlampe",
    "q.t21#0.e" to "Nachts steigen Geländebeurteilung und Navigationsschwierigkeit um ein Vielfaches, auch die Unfallrate. Nachtmarsch ist die Wahl, wenn es keine andere gibt – keine Strategie.",

    "q.t21#1.p" to "Wie ist die Beleuchtung für einen Nachtmarsch richtig zusammengestellt?",
    "q.t21#1.o0" to "Stirnlampe, Ersatzbatterien und eine zweite Lichtquelle (kleine Taschenlampe oder zweite Stirnlampe)",
    "q.t21#1.o1" to "Nur die Handy-Taschenlampe",
    "q.t21#1.o2" to "Nur eine Stirnlampe",
    "q.t21#1.o3" to "Eine Kerze",
    "q.t21#1.e" to "Fällt das Licht nachts aus, ist man handlungsunfähig. Die zweite Lichtquelle ist Redundanz – nach derselben Logik wie beim Seilsystem.",

    "q.t21#2.p" to "Wie ist der Abstand in der Gruppe bei einem Nachtmarsch zu handhaben?",
    "q.t21#2.o0" to "Abstand verkleinern, die Spitze bestätigt regelmässig, dass die Nachhut folgt, an Abzweigungen bleibt jemand stehen",
    "q.t21#2.o1" to "Abstand vergrössern und jeder für sich",
    "q.t21#2.o2" to "Nach Kondition auseinanderziehen",
    "q.t21#2.o3" to "Die Nachhut sucht selbst den Weg",
    "q.t21#2.e" to "Nachts ist das Blickfeld eng, ein Abgehängter wird kaum bemerkt. An Abzweigungen jemanden stehen zu lassen ist die billigste Versicherung.",

    "q.t21#3.p" to "Welches ist kein frühes Anzeichen eines nahenden Gewitters?",
    "q.t21#3.o0" to "Die Temperatur steigt allmählich",
    "q.t21#3.o1" to "Der Cumulonimbus wächst schnell",
    "q.t21#3.o2" to "Ferner, dumpfer Donner",
    "q.t21#3.o3" to "Aufgestellte Haare, kribbelnde Haut",
    "q.t21#3.e" to "Bei aufziehendem Gewitter fällt die Temperatur meist. Aufgestellte Haare zeigen eine starke Ladung – sofort den höchsten Punkt verlassen.",

    "q.t21#4.p" to "Was ist bei Gewitter in den Bergen am wichtigsten?",
    "q.t21#4.o0" to "Zügig tiefer gehen und Grat, Gewässer und Einzelbäume verlassen",
    "q.t21#4.o1" to "Unter einem grossen Felsblock am Gipfel Schutz suchen",
    "q.t21#4.o2" to "Unter einen Baum stellen",
    "q.t21#4.o3" to "Weitergehen",
    "q.t21#4.e" to "Höhepunkte, Gewässer, Einzelbäume und Metall sind die bevorzugten Wege eines Blitzes. Tiefer gehen und sich verteilen ist die einzige wirksame Massnahme.",

    "q.t21#5.p" to "Wie ist die richtige Haltung bei Gewitter?",
    "q.t21#5.o0" to "Verteilt in die Hocke, Füsse geschlossen, nicht hinlegen",
    "q.t21#5.o1" to "Flach auf den Boden legen",
    "q.t21#5.o2" to "Aufrecht stehen",
    "q.t21#5.o3" to "Einen Baum umarmen",
    "q.t21#5.e" to "Geschlossene Füsse verringern die Schrittspannung; flach liegend vergrössert man die Kontaktfläche zum Boden und wird dadurch gefährdeter.",

    "q.t21#6.p" to "Wovor ist bei Gewitterwetter zusätzlich zu warnen?",
    "q.t21#6.o0" to "Unterkühlung durch starken Temperaturabfall",
    "q.t21#6.o1" to "Sturzfluten durch Starkregen",
    "q.t21#6.o2" to "Orientierungsverlust durch plötzlich schlechte Sicht",
    "q.t21#6.o3" to "UV-Verbrennung",
    "q.t21#6.e" to "Gewitter bringen meist Kälteeinbruch, Starkregen und Nebel. Es ist eine Risikogruppe, kein einzelnes Risiko.",

    "q.t21#7.p" to "Wozu dient es bei Nachtmarsch oder Gewitter, den Tourenplan bei einer Kontaktperson zu hinterlegen?",
    "q.t21#7.o0" to "Damit von aussen rechtzeitig eine Suche angestossen werden kann, wenn die Gruppe nicht ankommt",
    "q.t21#7.o1" to "Aus Höflichkeit",
    "q.t21#7.o2" to "Für die Versicherung",
    "q.t21#7.o3" to "Es hat keinen Zweck",
    "q.t21#7.e" to "Nachts und bei schlechtem Wetter ist die Fehlertoleranz am kleinsten. Der Tourenplan ist die Voraussetzung dafür, dass jemand nach einem sucht.",

    // ---------- t09 Höhenkrankheit und Aufstiegsrhythmus ----------
    "q.t09#0.p" to "Wie schnell sollte die Schlafhöhe über 3.000 m ansteigen?",
    "q.t09#0.o0" to "Höchstens 500 m pro Tag",
    "q.t09#0.o1" to "1.000 m pro Tag",
    "q.t09#0.o2" to "1.500 m pro Tag",
    "q.t09#0.o3" to "Ohne Begrenzung",
    "q.t09#0.e" to "«Hoch gehen, tief schlafen» ist die übliche Strategie: tagsüber darf man höher steigen, aber die Schlafhöhe steigt pro Tag nicht über 500 m. Zu schneller Aufstieg ist die wichtigste Ursache von AMS.",

    "q.t09#1.p" to "Welche Konstellation ist für die akute Bergkrankheit (AMS) am typischsten?",
    "q.t09#1.o0" to "Kopfschmerz mit Übelkeit oder Appetitlosigkeit sowie Schwindel und Schwäche",
    "q.t09#1.o1" to "Gelenkschmerzen und Hautausschlag",
    "q.t09#1.o2" to "Anhaltender Husten mit Blut",
    "q.t09#1.o3" to "Fieber bis 39 °C",
    "q.t09#1.e" to "Erst die Kombination zählt: Kopfschmerz allein kann auch von Wassermangel oder Müdigkeit kommen; mit Appetitlosigkeit und Schwäche wird es wahrscheinlicher AMS.",

    "q.t09#2.p" to "Wie ist bei AMS-Symptomen richtig vorzugehen?",
    "q.t09#2.o0" to "Aufstieg stoppen, vor Ort akklimatisieren oder absteigen",
    "q.t09#2.o1" to "Medikament nehmen und planmässig weiter aufsteigen",
    "q.t09#2.o2" to "Viel trinken, weitergehen und durchbeissen",
    "q.t09#2.o3" to "Schneller zum Lager gehen und dort ausruhen",
    "q.t09#2.e" to "Der Kern ist «nicht mit Symptomen nach oben». Sind sie leicht und die Umstände es zulassen, hilft ein zusätzlicher Tag vor Ort; verschlechtern sie sich, muss abgestiegen werden.",

    "q.t09#3.p" to "Welche Signale erfordern sofortigen Abstieg?",
    "q.t09#3.o0" to "Atemnot bereits in Ruhe",
    "q.t09#3.o1" to "Unsicherer, betrunkener Gang",
    "q.t09#3.o2" to "Verwirrtheit oder auffälliges Verhalten",
    "q.t09#3.o3" to "Leichter Kopfschmerz",
    "q.t09#3.e" to "Diese drei deuten auf HAPE oder HACE. Die Behandlung hat nur eine Richtung: absteigen, Sauerstoff geben, medizinische Hilfe anfordern.",

    "q.t09#4.p" to "Warum wird empfohlen, «tiefer zu schlafen»?",
    "q.t09#4.o0" to "Nachts wird die Atmung flacher und der Sauerstoffmangel am grössten; tiefer zu schlafen verringert die nächtliche Hypoxie",
    "q.t09#4.o1" to "Unten ist es ruhiger",
    "q.t09#4.o2" to "Unten ist es wärmer",
    "q.t09#4.o3" to "Unten ist die Aussicht besser",
    "q.t09#4.e" to "Im Schlaf sinkt die Ventilation, die Sauerstoffsättigung fällt tiefer als im Wachzustand. Das Lager einige hundert Meter unter dem Tageshöchstpunkt anzulegen ist eine Reserve für die Nacht.",

    "q.t09#5.p" to "Sind körperlich fitte Menschen weniger anfällig für Höhenkrankheit?",
    "q.t09#5.o0" to "Nicht unbedingt; entscheidend sind Aufstiegsgeschwindigkeit und individuelle Veranlagung",
    "q.t09#5.o1" to "Ja, je fitter, desto sicherer",
    "q.t09#5.o2" to "Nein, je fitter, desto anfälliger",
    "q.t09#5.o3" to "Es hängt nur vom Alter ab",
    "q.t09#5.e" to "Fitte Menschen gehen oft schneller und höher und bekommen dadurch häufiger Probleme. Kondition und Akklimatisierungsfähigkeit getrennt zu betrachten ist in der Höhe zentral.",

    // ---------- t10 Wärme und Sonnenschutz in der Höhe ----------
    "q.t10#0.p" to "Aus wie vielen Schichten besteht das Bekleidungssystem in der Höhe üblicherweise?",
    "q.t10#0.o0" to "Funktionsschicht, Wärmeschicht, Windschicht",
    "q.t10#0.o1" to "Unterwäsche, Jacke",
    "q.t10#0.o2" to "Baumwollhemd, Pullover, Regenjacke",
    "q.t10#0.o3" to "Je mehr, desto besser",
    "q.t10#0.e" to "Schichten sind nicht zum Viel-Anziehen da, sondern zum Regulieren. Beim Gehen die Aussenschicht weg, beim Anhalten sofort wieder an – die Auskühlung passiert meist in den zehn Minuten Pause.",

    "q.t10#1.p" to "Um wie viel nimmt die UV-Intensität pro 1.000 Höhenmeter etwa zu?",
    "q.t10#1.o0" to "10–12 %",
    "q.t10#1.o1" to "2 %",
    "q.t10#1.o2" to "50 %",
    "q.t10#1.o3" to "Sie bleibt gleich",
    "q.t10#1.e" to "Die Luft wird dünner und filtert weniger UV. Zusammen mit rund 80 % Reflexion an der Schneeoberfläche liegt die tatsächliche Belastung von Gesicht und Nase fast bei «zweimal Sonne».",

    "q.t10#2.p" to "Was gehört zum Sonnenschutz in der Höhe?",
    "q.t10#2.o0" to "UV400-Sonnenbrille",
    "q.t10#2.o1" to "Sonnencreme SPF50+, alle 2–3 Stunden nachcremen",
    "q.t10#2.o2" to "Lippenpflege mit Lichtschutz",
    "q.t10#2.o3" to "Sonnenhut oder Kopftuch",
    "q.t10#2.e" to "Vier Dinge für vier Stellen: Augen, Haut, Lippen, Gesicht. Lippen haben kein Melanin und reissen am ehesten auf – und werden am leichtesten vergessen.",

    "q.t10#3.p" to "Warum frieren Hände und Füsse immer zuerst?",
    "q.t10#3.o0" to "Der Körper sichert zuerst die Kerntemperatur und verengt die Gefässe in den Extremitäten",
    "q.t10#3.o1" to "Sie haben wenig Fett",
    "q.t10#3.o2" to "Sie werden wenig bewegt",
    "q.t10#3.o3" to "Reine Einbildung",
    "q.t10#3.e" to "Das ist ein normaler Überlebensmechanismus. Wärmen muss deshalb am Rumpf ansetzen: Ist der Kern warm, bekommen Hände und Füsse wieder Durchblutung. Nur Handschuhe anzuziehen hilft wenig.",

    "q.t10#4.p" to "Handschuhe und Socken sind nass. Was ist zu tun?",
    "q.t10#4.o0" to "Sofort wechseln; nasse Schichten entziehen laufend Wärme",
    "q.t10#4.o1" to "Anlassen, beim Gehen trocknet es von selbst",
    "q.t10#4.o2" to "Auswringen genügt",
    "q.t10#4.o3" to "Erst am nächsten Tag wechseln",
    "q.t10#4.e" to "Nasse Textilien leiten Wärme um ein Vielfaches schneller als trockene. Sind Hände und Füsse erst steif, werden Bewegungen langsamer – und Fehler beim Bedienen der Ausrüstung und beim Gehen häufiger.",

    "q.t10#5.p" to "Was ist Schneeblindheit?",
    "q.t10#5.o0" to "Eine UV-Verbrennung der Hornhaut, meist 6–12 Stunden später mit starken Schmerzen, Lichtscheu und Tränen",
    "q.t10#5.o1" to "Ermüdung der Augen durch reflektiertes Licht",
    "q.t10#5.o2" to "Erfrierung des Augapfels",
    "q.t10#5.o3" to "Vitamin-A-Mangel",
    "q.t10#5.e" to "Schneeblindheit tritt verzögert auf: tagsüber nichts, abends Schmerzen. Vorbeugung läuft fast vollständig über die Brille – auch bei Bewölkung und im Schneetreiben.",

    // ---------- t11 Essen und Schlafen in der Höhe ----------
    "q.t11#0.p" to "Was tun, wenn in der Höhe kein Appetit aufkommt?",
    "q.t11#0.o0" to "Aktiv in kleinen Portionen häufig essen, vor allem Kohlenhydrate",
    "q.t11#0.o1" to "Nichts essen und auf Appetit warten",
    "q.t11#0.o2" to "Nur heisses Wasser trinken",
    "q.t11#0.o3" to "Mit Kaffee durchhalten",
    "q.t11#0.e" to "Ein Energiedefizit bremst die Akklimatisierung direkt. Eine grosse Mahlzeit in mehrere kleine Snacks zu zerlegen ist leichter umzusetzen, als sich zum Aufessen zu zwingen.",

    "q.t11#1.p" to "Was ist der einfachste Indikator für ausreichendes Trinken?",
    "q.t11#1.o0" to "Der Urin bleibt hellgelb",
    "q.t11#1.o1" to "Täglich 3 Liter trinken",
    "q.t11#1.o2" to "Kein Durstgefühl",
    "q.t11#1.o3" to "Gleichbleibendes Gewicht",
    "q.t11#1.e" to "Die Urinfarbe ist der direkteste Hydratationsindikator. Dunkelgelb bedeutet zu wenig; völlig klar kann zu viel bedeuten, dann etwas Elektrolyte ergänzen.",

    "q.t11#2.p" to "Was ist die häufigste Ursache schlechten Schlafs in der Höhe?",
    "q.t11#2.o0" to "Periodische Atmung durch Sauerstoffmangel, die einen immer wieder aus dem leichten Schlaf reisst",
    "q.t11#2.o1" to "Das Zelt ist unbequem",
    "q.t11#2.o2" to "Es ist zu ruhig",
    "q.t11#2.o3" to "Man ist tagsüber zu wenig gelaufen",
    "q.t11#2.e" to "Das ist physiologisch; man muss sich nicht sorgen, «keine acht Stunden» geschlafen zu haben. Alarmierend ist Schlaflosigkeit mit Kopfschmerz und Übelkeit – das kann AMS sein.",

    "q.t11#3.p" to "Was hilft, in der Höhe besser zu schlafen?",
    "q.t11#3.o0" to "Abends nicht zu üppig essen",
    "q.t11#3.o1" to "Keinen Alkohol trinken",
    "q.t11#3.o2" to "Vor dem Schlafen angemessen trinken",
    "q.t11#3.o3" to "Acetazolamid nach ärztlicher Anleitung",
    "q.t11#3.e" to "Die ersten drei kann man selbst umsetzen, der letzte Punkt braucht ärztliche Beurteilung. Medikation ist eine medizinische Entscheidung und gehört nicht in gegenseitige Empfehlungen im Team.",

    "q.t11#4.p" to "Warum ist Alkohol in der Höhe gefährlicher als im Flachland?",
    "q.t11#4.o0" to "Er dämpft die Atmung, verstärkt den Sauerstoffmangel und verdeckt AMS-Symptome",
    "q.t11#4.o1" to "Er entwässert",
    "q.t11#4.o2" to "Er verhindert das Einschlafen",
    "q.t11#4.o3" to "Er hat zu viele Kalorien",
    "q.t11#4.e" to "In der Höhe ist der Atemantrieb ohnehin geschwächt, Alkohol unterdrückt ihn zusätzlich. Erschwerend kommt hinzu, dass ein alkoholisiertes Bild dem frühen HACE stark ähnelt.",

    "q.t11#5.p" to "Ist Koffein in der Höhe vertretbar?",
    "q.t11#5.o0" to "In Massen ja, aber nicht als Ersatz für Ruhe und Flüssigkeit",
    "q.t11#5.o1" to "Überhaupt nicht",
    "q.t11#5.o2" to "Je mehr, desto besser",
    "q.t11#5.o3" to "Nur morgens",
    "q.t11#5.e" to "Eine Tasse Kaffee verursacht keine Höhenkrankheit und heilt keine Erschöpfung. Gegen Kopfschmerz hilft sie etwas, aber damit durchzuhalten verschiebt das Problem nur.",

    // ---------- t12 Gruppe und mentale Vorbereitung ----------
    "q.t12#0.p" to "Was ist die wichtigste mentale Vorbereitung vor der Tour?",
    "q.t12#0.o0" to "Akzeptieren, dass das Ziel möglicherweise nicht erreicht wird, und den Rückzug als Teil des Plans behandeln",
    "q.t12#0.o1" to "Sich entschliessen, nie aufzugeben",
    "q.t12#0.o2" to "Das Ziel auf den Handrücken schreiben",
    "q.t12#0.o3" to "Der Familie die Route nicht sagen",
    "q.t12#0.e" to "Ist der Rückzug eingeplant, stoppt man, wenn gestoppt werden muss. Ist «durchziehen» das Ziel, werden Warnsignale oft übersehen, um es zu schaffen.",

    "q.t12#1.p" to "Man merkt, dass man mit dem Tempo der Gruppe nicht mithält. Was ist am besten?",
    "q.t12#1.o0" to "Es offen sagen und die Gruppe bitten, das Tempo der langsamsten Person zu gehen",
    "q.t12#1.o1" to "Zähne zusammenbeissen, um nicht zu bremsen",
    "q.t12#1.o2" to "Still langsamer werden und zurückfallen",
    "q.t12#1.o3" to "Allein umkehren, ohne es jemandem zu sagen",
    "q.t12#1.e" to "Mitbeissen führt binnen Stunden in den Überziehungszustand, danach passieren eher Fehler und Verletzungen. Nach der langsamsten Person zu gehen ist effizient und sicher.",

    "q.t12#2.p" to "Was hilft gegen Exposition und Höhenangst?",
    "q.t12#2.o0" to "Auf die Füsse schauen, abschnittsweise, nicht in die Ferne starren",
    "q.t12#2.o1" to "Langsam atmen und die Aufmerksamkeit auf die Bewegung richten",
    "q.t12#2.o2" to "Drei Kontaktpunkte halten und die Bewegungen klein machen",
    "q.t12#2.o3" to "Mit geschlossenen Augen schnell durchgehen",
    "q.t12#2.e" to "Angst macht die Atmung flach und die Bewegung steif – und Steifheit ist die Quelle von Fehlern. Die Aufmerksamkeit auf den nächsten Tritt zurückzuholen ist am wirksamsten.",

    "q.t12#3.p" to "Was ist das Problem an «wir sind schon so weit gekommen, das darf nicht umsonst gewesen sein»?",
    "q.t12#3.o0" to "Es macht die bereits investierte Zeit zum Grund, weiter zu riskieren",
    "q.t12#3.o1" to "Es ist nicht positiv genug",
    "q.t12#3.o2" to "Es lässt einen zu langsam gehen",
    "q.t12#3.o3" to "Es gibt kein Problem",
    "q.t12#3.e" to "Die investierte Zeit kommt durch Weitergehen nicht zurück, aber Weitergehen kann neue, unwiderrufliche Kosten erzeugen. Beurteilt wird nach vorn, nicht nach hinten.",

    "q.t12#4.p" to "Was sollte die Gruppe vor dem Start verbindlich klären?",
    "q.t12#4.o0" to "Wer «Stopp» sagen darf, wo man sich bei Trennung trifft und ab wann ohne Meldung der Notfallplan greift",
    "q.t12#4.o1" to "Wer fotografiert",
    "q.t12#4.o2" to "Wer am schnellsten geht",
    "q.t12#4.o3" to "Wer am meisten trägt",
    "q.t12#4.e" to "«Stopp» wird zu einer vorab vergebenen Befugnis statt zu einer Frage persönlichen Mutes – dann traut man sich, im richtigen Moment zu sprechen. Dasselbe gilt für Treffpunkt und Notfallplan.",

    "q.t12#5.p" to "Jemand wird plötzlich bedrückt, spricht wenig und bewegt sich langsamer. Woran ist zuerst zu denken?",
    "q.t12#5.o0" to "An Energiemangel oder Flüssigkeitsmangel, aber auch an frühe Zeichen von Höhenkrankheit oder Unterkühlung",
    "q.t12#5.o1" to "Nur an schlechte Laune",
    "q.t12#5.o2" to "An einen Charakterzug",
    "q.t12#5.o3" to "Die Person braucht einfach Ruhe",
    "q.t12#5.e" to "Im Gelände ist eine Stimmungsänderung oft das erste Gesicht eines körperlichen Problems. Erst Essen, Wasser, wärmere Kleidung und Zustandsprüfung – dann über die Stimmung sprechen.",

    // ---------- t13 Langstreckenplanung und Versorgung ----------
    "q.t13#0.p" to "Wie dicht sollten Versorgungspunkte auf einer Langstrecke liegen?",
    "q.t13#0.o0" to "Alle 3–5 Tage",
    "q.t13#0.o1" to "Einer für die ganze Strecke",
    "q.t13#0.o2" to "Täglich einer",
    "q.t13#0.o3" to "Versorgung ist nicht nötig",
    "q.t13#0.e" to "Versorgungspunkte teilen die lange Strecke in Abschnitte, die sich einzeln beurteilen und verlassen lassen. Zu grosse Abstände lassen eine Wetterverzögerung die ganze Route mitreissen.",

    "q.t13#1.p" to "Wie viel wiegt Trekkingnahrung pro Tag etwa?",
    "q.t13#1.o0" to "600–800 g",
    "q.t13#1.o1" to "200 g",
    "q.t13#1.o2" to "1,5 kg",
    "q.t13#1.o3" to "3 kg",
    "q.t13#1.e" to "600–800 g getrocknete Hauptnahrung liefern etwa 2.500–3.000 kcal. Mit Nüssen und Ölpackungen als energiereicher Ergänzung wird das Gesamtgewicht etwas höher.",

    "q.t13#2.p" to "Welche Regelungen müssen vor einer Langstrecke geklärt sein?",
    "q.t13#2.o0" to "Genehmigung für Park oder Schutzgebiet",
    "q.t13#2.o1" to "Ob offenes Feuer erlaubt ist",
    "q.t13#2.o2" to "Ob der gesamte Müll mitgenommen werden muss",
    "q.t13#2.o3" to "Ob Drohnen fliegen dürfen",
    "q.t13#2.e" to "Das sind keine Kleinigkeiten: Ohne Genehmigung wird man zurückgeschickt, unerlaubtes Feuer löst in der Trockenzeit leicht einen Waldbrand aus, und in vielen Schutzgebieten ist Drohnenflug komplett verboten.",

    "q.t13#3.p" to "Warum sollte man Bargeld mitnehmen?",
    "q.t13#3.o0" to "Versorgungspunkte, Dörfer und Transport akzeptieren oft nur Bargeld, und das Netz kann fehlen",
    "q.t13#3.o1" to "Es wirkt professionell",
    "q.t13#3.o2" to "Man kann einen Tisch damit unterlegen",
    "q.t13#3.o3" to "Zum Abwiegen",
    "q.t13#3.e" to "Je abgelegener, desto stärker hängt alles an Bargeld. Kleine Scheine sind am praktischsten; ein Notgroschen gehört separat verwahrt und nicht zum Alltagsgeld.",

    "q.t13#4.p" to "Wie ist die Notfallkommunikation auf einer Langstrecke vorzubereiten?",
    "q.t13#4.o0" to "Satellitenkommunikationsgerät oder Notrufsender, dazu eine Papierkarte und ein Tourenplan bei der Kontaktperson",
    "q.t13#4.o1" to "Nur das Handy",
    "q.t13#4.o2" to "Nur eine Pfeife",
    "q.t13#4.o3" to "Nichts davon",
    "q.t13#4.e" to "Auf vielen Langstrecken gibt es durchgehend keinen Empfang. Das Gerät kann Nachrichten senden; Karte und Tourenplan sagen den Daheimgebliebenen, wohin man geht und wann Alarm ausgelöst werden soll.",

    "q.t13#5.p" to "Was bedeutet eine Reserve von 20 % im Plan konkret?",
    "q.t13#5.o0" to "Essen, Brennstoff, Zeit und Bargeld je etwa ein Fünftel über dem theoretischen Bedarf",
    "q.t13#5.o1" to "Nur mehr Wasser mitnehmen",
    "q.t13#5.o2" to "Nur Zeit reservieren",
    "q.t13#5.o3" to "Das ist nicht nötig",
    "q.t13#5.e" to "Die Reserve ist Raum für Unvorhergesehenes. Ein Tag Wetterverzögerung, zwei zusätzliche Kochergänge, eine unerwartete Fahrt – das darf die Tour nicht sofort in Bedrängnis bringen.",

    // ---------- t14 Häufige Notfälle und Hilferuf ----------
    "q.t14#0.p" to "Was ist die Grundregel der Erstversorgung bei einer Sprunggelenkverstauchung?",
    "q.t14#0.o0" to "Ruhe, Kühlung, Kompression, Hochlagern (RICE)",
    "q.t14#0.o1" to "Sofort wärmen und massieren",
    "q.t14#0.o2" to "Weitergehen, bis es sich löst",
    "q.t14#0.o3" to "Den Bluterguss kräftig ausstreichen",
    "q.t14#0.e" to "Wärme und Massage in der Akutphase verstärken Blutung und Schwellung. In den ersten 48 Stunden kühlen, komprimieren, hochlagern; danach je nach Verlauf schrittweise belasten.",

    "q.t14#1.p" to "Wie lautet die richtige Reihenfolge bei Unterkühlung?",
    "q.t14#1.o0" to "Windschutz, trockene Kleidung, Isolation zum Boden, wachen Personen warme Getränke, langsam wiedererwärmen",
    "q.t14#1.o1" to "Erst heisses Wasser geben, dann umziehen",
    "q.t14#1.o2" to "Hände und Füsse reiben, um die Durchblutung anzuregen",
    "q.t14#1.o3" to "Die Person schnell gehen lassen, um Wärme zu erzeugen",
    "q.t14#1.e" to "Erst den weiteren Wärmeverlust stoppen, dann über Wiedererwärmung sprechen. Reiben der Extremitäten und erzwungenes Gehen können kaltes Blut zum Kern zurückführen und die Lage verschlimmern.",

    "q.t14#2.p" to "Was ist bei Verdacht auf Hitzschlag zuerst zu tun?",
    "q.t14#2.o0" to "Zügig in den Schatten bringen, Kleidung öffnen und mit physikalischer Kühlung beginnen",
    "q.t14#2.o1" to "Viel Leitungswasser einflössen",
    "q.t14#2.o2" to "Weitergehen lassen, Schwitzen hilft",
    "q.t14#2.o3" to "Zudecken, damit die Person nicht auskühlt",
    "q.t14#2.e" to "Beim Hitzschlag versagt die Wärmeabgabe; erst kühlen, dann Flüssigkeit. Bei getrübtem Bewusstsein nicht einflössen, um Aspiration zu vermeiden.",

    "q.t14#3.p" to "Welche Angaben muss eine Notfallmeldung enthalten?",
    "q.t14#3.o0" to "Genaue Position oder Koordinaten",
    "q.t14#3.o1" to "Personenzahl und Verletzungen",
    "q.t14#3.o2" to "Vorhandene Ausrüstung und Versorgung",
    "q.t14#3.o3" to "Kontaktmöglichkeit und Akkustand",
    "q.t14#3.e" to "Die Rettung muss zuerst wissen: wo, wie viele, wie schwer verletzt, wie lange durchhaltbar. Unvollständige Angaben kosten oft Stunden des Nachfragens.",

    "q.t14#4.p" to "Wie ist ein Plan für den Fall fehlender Meldung aufzustellen?",
    "q.t14#4.o0" to "Feste Kontrollzeiten vereinbaren: ab wann wer wen anruft und wann Alarm ausgelöst wird",
    "q.t14#4.o1" to "Das ergibt sich dann",
    "q.t14#4.o2" to "Der Familie nur grob sagen, wohin es geht",
    "q.t14#4.o3" to "Ein solcher Plan ist nicht nötig",
    "q.t14#4.e" to "Der Plan muss Zeit und Handlung enthalten: Ab welcher Uhrzeit wird telefoniert, nach wie vielen weiteren Stunden die örtliche Rettung kontaktiert. Ein vages «meldet euch, falls etwas ist» ist kein Plan.",

    "q.t14#5.p" to "Wann muss Hilfe gerufen werden, statt weiter selbst zu behandeln?",
    "q.t14#5.o0" to "Wenn die Person nicht mehr gehen kann, das Bewusstsein verändert ist oder sich der Zustand laufend verschlechtert",
    "q.t14#5.o1" to "Bei leichter Müdigkeit",
    "q.t14#5.o2" to "Bei drückenden Schuhen",
    "q.t14#5.o3" to "Wenn man zwei Stunden hinter dem Plan liegt",
    "q.t14#5.e" to "Die Schwelle muss vorher klar sein: gehfähig, wach, besser werdend – selbst absteigen; nicht gehfähig, bewusstseinsgetrübt, schlechter werdend – früh Hilfe rufen.",

    // ---------- t17 Dehydratation, Hitze und häufige Verletzungen ----------
    "q.t17#0.p" to "Was ist der praktischste Indikator für ausreichendes Trinken beim Wandern?",
    "q.t17#0.o0" to "Der Urin bleibt hellgelb",
    "q.t17#0.o1" to "Das Durstgefühl",
    "q.t17#0.o2" to "Die Menge des Schweisses",
    "q.t17#0.o3" to "Das Körpergewicht",
    "q.t17#0.e" to "Durst zeigt bereits einen Mangel an. Die Urinfarbe ist die billigste tägliche Selbstkontrolle.",

    "q.t17#1.p" to "Was ist das Kernkriterium des Hitzschlags?",
    "q.t17#1.o0" to "Kerntemperatur über 40 °C mit Bewusstseinsveränderung",
    "q.t17#1.o1" to "Starkes Schwitzen",
    "q.t17#1.o2" to "Gerötete Haut",
    "q.t17#1.o3" to "Schneller Herzschlag",
    "q.t17#1.e" to "Die Bewusstseinsveränderung ist das entscheidende Signal. Ohne Thermometer vor Ort wird nach dem Bewusstseinszustand beurteilt und sofort gekühlt.",

    "q.t17#2.p" to "Wie lautet die richtige Reihenfolge bei Hitzeerschöpfung?",
    "q.t17#2.o0" to "In den Schatten, Kleidung öffnen, kühlen, Elektrolyte zuführen",
    "q.t17#2.o1" to "Erst Flüssigkeit, dann kühlen",
    "q.t17#2.o2" to "Erst die Extremitäten massieren",
    "q.t17#2.o3" to "Erst Wasser einflössen",
    "q.t17#2.e" to "Kühlen hat Vorrang. Flüssigkeit braucht Zeit, bis sie wirkt; die Organschädigung durch Hitze tritt sofort ein.",

    "q.t17#3.p" to "Was ist in den ersten 48 Stunden nach einer Sprunggelenkverstauchung richtig?",
    "q.t17#3.o0" to "Kühlen, komprimieren, hochlagern; Wärme und kräftiges Massieren vermeiden",
    "q.t17#3.o1" to "Wärmen und massieren",
    "q.t17#3.o2" to "Weitergehen",
    "q.t17#3.o3" to "Den Bluterguss ausstreichen",
    "q.t17#3.e" to "Wärme und Reiben in der Akutphase verstärken Blutung und Schwellung. Bei RICE fehlt keiner der vier Schritte.",

    "q.t17#4.p" to "Was ist zu tun, wenn eine überhitzte Person bewusstseinsgetrübt ist?",
    "q.t17#4.o0" to "Kein Wasser einflössen, stattdessen nass kühlen und zügig Hilfe holen",
    "q.t17#4.o1" to "Wasser einflössen",
    "q.t17#4.o2" to "Salztabletten geben",
    "q.t17#4.o3" to "Die Person selbst trinken lassen",
    "q.t17#4.e" to "Ist der Schluckreflex unzuverlässig, führt Einflössen zur Aspiration. Dann wirken nur Kühlung und professionelle Rettung.",

    "q.t17#5.p" to "Eine Blase behindert das Gehen. Wie ist richtig vorzugehen?",
    "q.t17#5.o0" to "Desinfizieren, vom Rand her entlasten, die Blasendecke erhalten und abdecken",
    "q.t17#5.o1" to "Die ganze Blasendecke abreissen",
    "q.t17#5.o2" to "In der Mitte einstechen",
    "q.t17#5.o3" to "Ignorieren",
    "q.t17#5.e" to "Die erhaltene Blasendecke ist der beste Verband. In der Mitte einzustechen reisst leicht weiter.",

    "q.t17#6.p" to "Was erhöht das Risiko eines Hitzeschadens beim Wandern?",
    "q.t17#6.o0" to "Hohe Luftfeuchtigkeit bei Windstille",
    "q.t17#6.o1" to "Anstieg in der Mittagshitze",
    "q.t17#6.o2" to "Nur Wasser trinken, ohne Elektrolyte",
    "q.t17#6.o3" to "Helle, luftdurchlässige Kleidung",
    "q.t17#6.e" to "Die ersten drei schwächen Wärmeabgabe oder Elektrolythaushalt. Helle, luftige Kleidung ist dagegen genau eine Kühlmassnahme.",

    "q.t17#7.p" to "Was gehört unbedingt in eine Wander-Erste-Hilfe-Tasche?",
    "q.t17#7.o0" to "Blasenpflaster und Wundauflagen",
    "q.t17#7.o1" to "Schmerz- und Fiebermittel",
    "q.t17#7.o2" to "Elastische Binde",
    "q.t17#7.o3" to "Antibiotika",
    "q.t17#7.e" to "Die ersten drei decken die häufigsten Wanderprobleme ab: Füsse, Schmerzen, Verstauchungen. Antibiotika brauchen ärztliche Beurteilung.",

    "q.t17#8.p" to "Bringe die Behandlung einer Hitzeerschöpfung in die richtige Reihenfolge.",
    "q.t17#8.o0" to "Bewegung stoppen, in den Schatten bringen",
    "q.t17#8.o1" to "Kleidung öffnen, mit Kühlung beginnen",
    "q.t17#8.o2" to "Elektrolythaltige Flüssigkeit zuführen",
    "q.t17#8.o3" to "Bewusstsein und Zustand beobachten, bei Bedarf Hilfe holen",
    "q.t17#8.e" to "Der Kern der Reihenfolge ist «zuerst die Hitzeexposition beenden». Weiterzugehen treibt die Hitzeerschöpfung in den Hitzschlag.",

    "q.t17#9.p" to "Eine Person hat beim Anstieg in der Mittagshitze plötzlich Kopfschmerz, Übelkeit und kalte, feuchte Haut. Was ist zu tun?",
    "q.t17#9.o0" to "Sofort anhalten, kühlen, Elektrolyte geben und beobachten",
    "q.t17#9.o1" to "Bis zum Lager weitergehen",
    "q.t17#9.o2" to "Schmerzmittel geben und weitergehen",
    "q.t17#9.o3" to "Wärmer anziehen",
    "q.t17#9.e" to "Das ist das typische Bild einer Hitzeerschöpfung. Weiterzugehen verschlechtert es schnell, und ein Hitzschlag kann in wenigen zehn Minuten tödlich verlaufen.",

    // ---------- t20 Ausrüstungspflege und Reparatur ----------
    "q.t20#0.p" to "Was ist der häufigste Ausrüstungsdefekt auf Langstrecken?",
    "q.t20#0.o0" to "Sich lösende Schuhsohlen und undichte Luftmatten",
    "q.t20#0.o1" to "Reissende Rucksackgurte",
    "q.t20#0.o2" to "Löcher im Zelt",
    "q.t20#0.o3" to "Brechende Trekkingstöcke",
    "q.t20#0.e" to "Beides führt direkt dazu, dass man «nicht gehen» oder «nicht schlafen» kann. Die Kontrolle vor dem Start sollte dort zuerst ansetzen.",

    "q.t20#1.p" to "Die Schuhsohle beginnt sich zu lösen. Was ist vor Ort am sinnvollsten?",
    "q.t20#1.o0" to "Zuerst mit Tape fixieren, damit es nicht weiter reisst; in der Stadt dann Spezialkleber",
    "q.t20#1.o1" to "Mit Feuer anschmelzen",
    "q.t20#1.o2" to "Mit einer Schnur festbinden",
    "q.t20#1.o3" to "Weitergehen und abwarten, bis sie abfällt",
    "q.t20#1.e" to "Tape ist Schadensbegrenzung, keine Reparatur. Reist es weiter, löst sich die ganze Sohle – dann geht wirklich nichts mehr.",

    "q.t20#2.p" to "Ein Zeltgestänge ist gebrochen. Was ist die praktischste Lösung vor Ort?",
    "q.t20#2.o0" to "Ein Reparaturhülsrohr über die Bruchstelle schieben und weiterverwenden",
    "q.t20#2.o1" to "Alles mit Tape umwickeln",
    "q.t20#2.o2" to "Das Zelt wegwerfen",
    "q.t20#2.o3" to "Die ganze Stange durch einen Ast ersetzen",
    "q.t20#2.e" to "Eine Hülse stellt einen Grossteil der Festigkeit wieder her. Tape hält ein bis zwei Nächte und verschlechtert die Bruchstelle weiter.",

    "q.t20#3.p" to "In die Daunenjacke ist ein kleines Loch gerissen. Wie ist vorzugehen?",
    "q.t20#3.o0" to "Flicken aufkleben und andrücken, nicht klopfen",
    "q.t20#3.o1" to "Die ausgetretenen Daunen wegklopfen",
    "q.t20#3.o2" to "Mit Feuer verschmelzen",
    "q.t20#3.o3" to "Mit Nadel und Faden zunähen",
    "q.t20#3.e" to "Klopfen lässt immer weiter Daunen aus den Nadelstichen austreten. Flicken plus leichtes Andrücken ist die wirksamste Schadensbegrenzung.",

    "q.t20#4.p" to "Was ist keine typische Ursache für eine undichte Luftmatte?",
    "q.t20#4.o0" to "Sonneneinstrahlung",
    "q.t20#4.o1" to "Spitze Steine am Boden",
    "q.t20#4.o2" to "Nicht ganz geschlossenes Ventil",
    "q.t20#4.o3" to "Ermüdete Nähte",
    "q.t20#4.e" to "Sonne sticht keine Kammer auf. Neben den ersten drei ist die häufigste Ursache ein nicht sauber geräumter Untergrund.",

    "q.t20#5.p" to "Was gehört sinnvollerweise in ein Reparaturset fürs Wandern?",
    "q.t20#5.o0" to "Dyneema-Tape",
    "q.t20#5.o1" to "Mattenflicken und Kleber",
    "q.t20#5.o2" to "Ersatz-Steckschnallen",
    "q.t20#5.o3" to "Ein komplettes Schraubendrehersortiment",
    "q.t20#5.e" to "Die ersten drei decken die drei häufigen Defektgruppen ab: Zeltstoff, Luftkammer, Rucksackverschluss. Ein Schraubendrehersortiment ist Gewicht, das man nicht braucht.",

    "q.t20#6.p" to "Was lohnt sich, abends im Lager in fünf Minuten zu prüfen?",
    "q.t20#6.o0" to "Ob Sand und Steine im Schuh sind",
    "q.t20#6.o1" to "Ob die Socken durchnässt sind",
    "q.t20#6.o2" to "Nähte und Verschlüsse des Rucksacks",
    "q.t20#6.o3" to "Die Länge der Trekkingstöcke",
    "q.t20#6.e" to "Die ersten beiden entscheiden über den Zustand der Füsse, der dritte darüber, ob morgen plötzlich ein Gurt reisst. Die Stocklänge lässt sich jederzeit anpassen.",

    "q.t20#7.p" to "Was ist die richtige Vorstellung vom «Ablaufdatum» von Ausrüstung?",
    "q.t20#7.o0" to "Nach Nutzungsintensität und Zustand beurteilen, nicht nach dem Kaufjahr",
    "q.t20#7.o1" to "Neu gekauft ist immer besser",
    "q.t20#7.o2" to "Erst ersetzen, wenn es kaputt ist",
    "q.t20#7.o3" to "Je älter, desto verlässlicher",
    "q.t20#7.e" to "Bei gleichem Teil unterscheidet sich die Lebensdauer stark mit der Nutzungshäufigkeit. Auf Verschleiss zu schauen – Sohle, Verschlüsse, Beschichtung – ist verlässlicher als auf das Datum.",
)
